async function loadOverview() {
  try {
    let res = null;
    try {
      res = await api('/api/admin/overview');
    } catch (e) {
      console.warn('[admin] Using local fallback overview data:', e.message);
    }

    // Merge server response with comprehensive default mock data
    const data = Object.assign({}, defaultOverviewData, res || {});
    adminOverviewData = data;

    // 1. Top 6 KPI Cards
    const summary = Object.assign({}, defaultOverviewData.summary, data.summary || {});
    setElText('kpi-total-users', Number(summary.totalUsers || 125430).toLocaleString());
    setElText('kpi-total-tasks', Number(summary.totalTasks || 89245).toLocaleString());
    setElText('kpi-total-earnings', `$${Number(summary.totalEarnings || 256430.50).toLocaleString(undefined, { minimumFractionDigits: 2 })}`);
    setElText('kpi-total-transactions', Number(summary.totalTransactions || 312430).toLocaleString());
    setElText('kpi-platform-revenue', `$${Number(summary.platformRevenue || 25643.05).toLocaleString(undefined, { minimumFractionDigits: 2 })}`);
    setElText('kpi-active-now', Number(summary.activeNow || 2543).toLocaleString());

    setElText('sb-platform-balance', `$${Number(summary.platformBalance || 125430.50).toLocaleString(undefined, { minimumFractionDigits: 2 })}`);
    setElText('sb-balance-growth', `${summary.platformBalanceGrowth || '+12.5%'} from last month`);

    // 2. Multi-Line Earnings vs Commission Chart
    const earnData = (data.earningsOverview && data.earningsOverview.chart && data.earningsOverview.chart.length > 0)
      ? data.earningsOverview
      : defaultOverviewData.earningsOverview;
    renderEarningsChart(earnData);
    setElText('strip-total-earnings', `$${Number(earnData.totalEarnings || 256430.50).toLocaleString(undefined, { minimumFractionDigits: 2 })}`);
    setElText('strip-total-commission', `$${Number(earnData.totalCommission || 25643.05).toLocaleString(undefined, { minimumFractionDigits: 2 })}`);
    setElText('strip-avg-price', `$${Number(earnData.avgTaskPrice || 23.45).toFixed(2)}`);
    setElText('strip-completed-tasks', Number(earnData.completedTasks || 76843).toLocaleString());

    // 3. Donut Charts
    const taskOverviewData = data.tasksOverview || defaultOverviewData.tasksOverview;
    const usersOverviewData = data.usersOverview || defaultOverviewData.usersOverview;
    renderDonutChart('tasks-donut-wrap', 'tasks-donut-legend', taskOverviewData, 'Total Tasks');
    renderDonutChart('users-donut-wrap', 'users-donut-legend', usersOverviewData, 'Total Users');

    // 4. Live Activity stream
    const liveActivityList = (data.liveActivity && data.liveActivity.length > 0) ? data.liveActivity : defaultOverviewData.liveActivity;
    allLiveActivityCache = liveActivityList;
    renderLiveActivity(liveActivityList);

    // 5. Recent Tasks, Transactions & Disputes
    const recentTasksList = (data.recentTasks && data.recentTasks.length > 0) ? data.recentTasks : defaultOverviewData.recentTasks;
    const recentTxList = (data.recentTransactions && data.recentTransactions.length > 0) ? data.recentTransactions : defaultOverviewData.recentTransactions;
    const recentDispList = (data.recentDisputes && data.recentDisputes.length > 0) ? data.recentDisputes : defaultOverviewData.recentDisputes;
    const escrowSummaryData = data.escrowSummary || defaultOverviewData.escrowSummary;

    renderRecentTasks(recentTasksList);
    renderRecentTransactions(recentTxList);
    renderDisputesList(recentDispList);
    renderEscrowSummaryDonut(escrowSummaryData);

    // 6. Top Performing Categories & Top Earners
    const topCatsList = (data.topCategories && data.topCategories.length > 0) ? data.topCategories : defaultOverviewData.topCategories;
    const topEarnersList = (data.topEarners && data.topEarners.length > 0) ? data.topEarners : defaultOverviewData.topEarners;
    renderTopCategories(topCatsList);
    renderTopEarners(topEarnersList);

    // 7. System Status Checklist & Platform Sparklines
    const sysStatusList = (data.systemStatus && data.systemStatus.length > 0) ? data.systemStatus : defaultOverviewData.systemStatus;
    const sparklinesList = (data.platformAnalytics && data.platformAnalytics.length > 0) ? data.platformAnalytics : defaultOverviewData.platformAnalytics;
    renderSystemStatus(sysStatusList);
    renderPlatformSparklines(sparklinesList);

    // 8. Sub-KPI metrics
    const subKPIs = Object.assign({}, defaultOverviewData.subKPIs, data.subKPIs || {});
    setElText('sub-disputes-count', subKPIs.disputes?.count || 24);
    setElText('sub-withdrawals-count', subKPIs.withdrawals?.count || 48);
    setElText('sub-signups-count', subKPIs.newSignups?.count || '1,243');
    setElText('sub-completion-rate', subKPIs.completionRate?.count || '92.4%');
    setElText('sub-response-time', subKPIs.responseTime?.count || '2.4 hrs');
    setElText('sub-repeat-rate', subKPIs.repeatUserRate?.count || '68.7%');
    setElText('sub-satisfaction-rate', subKPIs.satisfactionRate?.count || '4.8/5');
    setElText('sub-conversion-rate', subKPIs.conversionRate?.count || '8.6%');

    // Update nav badge counts
    if (data.users) setElText('nav-users-count', data.users.total || 125430);
    if (data.tasks) setElText('nav-tasks-count', data.tasks.total || 89245);

  } catch (err) {
    console.error('[admin] loadOverview error:', err);
  }
}

/**
 * Render Interactive SVG Multi-Line Chart with glowing gradient areas and hover tooltips
 */
function renderEarningsChart(data) {
  const container = document.getElementById('earnings-chart-container');
  if (!container || !data.chart || data.chart.length === 0) return;

  const points = data.chart;
  const w = 700;
  const h = 260;
  const padL = 50;
  const padR = 20;
  const padT = 30;
  const padB = 40;

  const maxVal = Math.max(...points.map(p => p.earnings)) * 1.15;
  const minVal = 0;

  const getX = i => padL + (i / (points.length - 1)) * (w - padL - padR);
  const getY = val => padT + (1 - (val - minVal) / (maxVal - minVal)) * (h - padT - padB);

  // Generate smooth SVG paths
  let earnPath = `M ${getX(0)} ${getY(points[0].earnings)}`;
  let earnArea = `M ${getX(0)} ${getY(points[0].earnings)}`;
  let commPath = `M ${getX(0)} ${getY(points[0].commission)}`;

  for (let i = 1; i < points.length; i++) {
    const prevX = getX(i - 1);
    const prevY = getY(points[i - 1].earnings);
    const currX = getX(i);
    const currY = getY(points[i].earnings);
    const cpX1 = prevX + (currX - prevX) / 2;
    const cpX2 = currX - (currX - prevX) / 2;
    earnPath += ` C ${cpX1} ${prevY}, ${cpX2} ${currY}, ${currX} ${currY}`;
    earnArea += ` C ${cpX1} ${prevY}, ${cpX2} ${currY}, ${currX} ${currY}`;

    const prevCommY = getY(points[i - 1].commission);
    const currCommY = getY(points[i].commission);
    commPath += ` C ${cpX1} ${prevCommY}, ${cpX2} ${currCommY}, ${currX} ${currCommY}`;
  }

  earnArea += ` L ${getX(points.length - 1)} ${h - padB} L ${getX(0)} ${h - padB} Z`;

  // Grid lines
  let gridLines = '';
  const steps = 4;
  for (let s = 0; s <= steps; s++) {
    const yVal = (maxVal / steps) * s;
    const yPos = getY(yVal);
    gridLines += `
      <line x1="${padL}" y1="${yPos}" x2="${w - padR}" y2="${yPos}" stroke="#1E293B" stroke-dasharray="3,3" stroke-width="1" />
      <text x="${padL - 10}" y="${yPos + 4}" fill="#64748B" font-size="11" text-anchor="end">$${Math.round(yVal / 1000)}K</text>
    `;
  }

  // X Axis labels & Data Dots
  let dotsAndLabels = '';
  points.forEach((p, idx) => {
    const cx = getX(idx);
    const cy = getY(p.earnings);
    const cyComm = getY(p.commission);

    dotsAndLabels += `
      <text x="${cx}" y="${h - 15}" fill="#64748B" font-size="11" text-anchor="middle">${p.date}</text>
      <!-- Earnings Point -->
      <circle cx="${cx}" cy="${cy}" r="4" fill="#10B981" stroke="#0B0F19" stroke-width="2" class="chart-point" data-tip="<b>${p.date}</b><br>Earnings: $${p.earnings.toLocaleString()}<br>Commission: $${p.commission.toLocaleString()}"></circle>
      <!-- Commission Point -->
      <circle cx="${cx}" cy="${cyComm}" r="3.5" fill="#8B5CF6" stroke="#0B0F19" stroke-width="2" class="chart-point" data-tip="Commission: $${p.commission.toLocaleString()}"></circle>
    `;
  });

  container.innerHTML = `
    <div class="chart-svg-wrap">
      <svg viewBox="0 0 ${w} ${h}" class="adm-svg-chart">
        <defs>
          <linearGradient id="earnGrad" x1="0%" y1="0%" x2="0%" y2="100%">
            <stop offset="0%" stop-color="#10B981" stop-opacity="0.25" />
            <stop offset="100%" stop-color="#10B981" stop-opacity="0.0" />
          </linearGradient>
        </defs>
        ${gridLines}
        <path d="${earnArea}" fill="url(#earnGrad)" />
        <path d="${commPath}" fill="none" stroke="#8B5CF6" stroke-width="2.5" stroke-linecap="round" />
        <path d="${earnPath}" fill="none" stroke="#10B981" stroke-width="3" stroke-linecap="round" />
        ${dotsAndLabels}
      </svg>
      <div id="chart-tooltip" class="adm-chart-tip"></div>
    </div>
  `;

  // Attach hover tooltip listener
  const tip = container.querySelector('#chart-tooltip');
  container.querySelectorAll('.chart-point').forEach(pt => {
    pt.addEventListener('mouseenter', e => {
      tip.innerHTML = pt.getAttribute('data-tip');
      tip.style.opacity = '1';
      const rect = pt.getBoundingClientRect();
      const parentRect = container.getBoundingClientRect();
      tip.style.left = `${rect.left - parentRect.left + 8}px`;
      tip.style.top = `${rect.top - parentRect.top - 40}px`;
    });
    pt.addEventListener('mouseleave', () => { tip.style.opacity = '0'; });
  });
}

