function renderPlatformSparklines(metrics) {
  const container = document.getElementById('platform-sparklines-body');
  if (!container || !metrics) return;
  container.innerHTML = metrics.map(m => {
    // Generate mini SVG sparkline
    const pts = m.points || [30, 32, 35, 33, 36, 38, 40];
    const min = Math.min(...pts);
    const max = Math.max(...pts);
    const w = 90;
    const h = 20;
    const svgPts = pts.map((val, i) => {
      const x = (i / (pts.length - 1)) * w;
      const y = h - ((val - min) / (max - min || 1)) * (h - 4) - 2;
      return `${x},${y}`;
    }).join(' ');

    const strokeColor = m.trend === 'up' ? '#10B981' : '#38BDF8';
    return `
      <div class="adm-spark-item">
        <div class="adm-spark-info">
          <small>${escapeHtml(m.label)}</small>
          <div>
            <b>${m.value}</b>
            <span class="adm-spark-trend ${m.trend}">${m.change}</span>
          </div>
        </div>
        <svg class="adm-sparkline-svg" viewBox="0 0 ${w} ${h}">
          <polyline fill="none" stroke="${strokeColor}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" points="${svgPts}" />
        </svg>
      </div>
    `;
  }).join('');
}

