function renderCommandResults(query) {
  const container = document.getElementById('cmd-results-list');
  if (!container) return;

  const matches = commandPaletteItems.filter(item =>
    !query || item.title.toLowerCase().includes(query) || item.desc.toLowerCase().includes(query) || item.badge.toLowerCase().includes(query)
  );

  if (matches.length === 0) {
    container.innerHTML = '<div style="padding:18px;text-align:center;color:#64748B;font-size:0.84rem">No commands found for "' + escapeHtml(query) + '"</div>';
    return;
  }

  container.innerHTML = matches.map((m, idx) => `
    <div class="cmd-item ${idx === 0 ? 'selected' : ''}" onclick="switchView('${m.view}');closeModal('modal-command-palette');">
      <span class="cmd-icon">${m.icon}</span>
      <div style="flex:1">
        <b style="display:block;font-size:0.84rem">${escapeHtml(m.title)}</b>
        <small style="color:#94A3B8;font-size:0.72rem">${escapeHtml(m.desc)}</small>
      </div>
      <span class="cmd-badge">${m.badge}</span>
    </div>
  `).join('');
}

