// Load 10 KPI Summary Cards
async function loadUsersKPIs() {
  try {
    const kpis = await api('/api/admin/users/kpis');
    if (!kpis) return;
    const setVal = (id, val, prefix = '') => {
      const el = document.getElementById(id);
      if (el) el.textContent = `${prefix}${val.toLocaleString()}`;
    };
    setVal('ukpi-total', kpis.totalUsers);
    setVal('ukpi-active', kpis.activeUsers);
    setVal('ukpi-today', kpis.newToday);
    setVal('ukpi-verified', kpis.verifiedUsers);
    setVal('ukpi-workers', kpis.workers);
    setVal('ukpi-clients', kpis.clients);
    setVal('ukpi-businesses', kpis.businesses);
    setVal('ukpi-suspended', kpis.suspended);
    setVal('ukpi-pending-kyc', kpis.pendingVerification);
    setVal('ukpi-online', kpis.onlineNow);
  } catch (err) {
    console.warn('[users] Could not load user KPIs:', err);
  }
}

// Interactive 1-Click Filtering by KPI Card
window.filterUsersByKpi = function(kpiType) {
  document.querySelectorAll('.adm-ukpi-card').forEach(c => c.classList.remove('active-filter-kpi'));
  const card = document.getElementById(`kpicard-${kpiType.replace('_', '-')}`);
  if (card) card.classList.add('active-filter-kpi');

  const searchInput = document.getElementById('users-search-input');
  const typeSelect = document.getElementById('users-type-filter');
  const verSelect = document.getElementById('users-verified-filter');
  const statusSelect = document.getElementById('users-status-filter');
  const riskSelect = document.getElementById('users-risk-filter');
  const tagSelect = document.getElementById('users-tag-filter');
  const sortSelect = document.getElementById('users-sort-filter');

  if (searchInput) searchInput.value = '';
  if (typeSelect) typeSelect.value = '';
  if (verSelect) verSelect.value = '';
  if (statusSelect) statusSelect.value = '';
  if (riskSelect) riskSelect.value = '';
  if (tagSelect) tagSelect.value = '';
  if (sortSelect) sortSelect.value = 'newest';

  if (kpiType === 'total') {
    toast('Showing All Users', 'info');
  } else if (kpiType === 'active') {
    if (statusSelect) statusSelect.value = 'active';
    toast('Filtered by: Active Accounts', 'info');
  } else if (kpiType === 'today') {
    if (sortSelect) sortSelect.value = 'newest';
    toast('Filtered by: New Today (Newest)', 'info');
  } else if (kpiType === 'verified') {
    if (verSelect) verSelect.value = '1';
    toast('Filtered by: Verified Credentials', 'info');
  } else if (kpiType === 'workers') {
    if (typeSelect) typeSelect.value = 'worker';
    toast('Filtered by: Workers & Freelancers', 'info');
  } else if (kpiType === 'clients') {
    if (typeSelect) typeSelect.value = 'client';
    toast('Filtered by: Clients & Employers', 'info');
  } else if (kpiType === 'businesses') {
    if (typeSelect) typeSelect.value = 'business';
    toast('Filtered by: Business Accounts', 'info');
  } else if (kpiType === 'suspended') {
    if (statusSelect) statusSelect.value = 'suspended';
    toast('Filtered by: Suspended Accounts', 'info');
  } else if (kpiType === 'pending_kyc') {
    if (verSelect) verSelect.value = '0';
    toast('Filtered by: Pending Verification / Unverified', 'info');
  } else if (kpiType === 'online') {
    if (searchInput) searchInput.value = 'Dhaka';
    toast('Filtered by: Active Live Region', 'info');
  }

  loadUsersTable();
};

// Load Users Master Table with Multi-Facet Filters
async function loadUsersTable() {
  const tbody = document.getElementById('users-table-body');
  if (!tbody) return;
  tbody.innerHTML = '<tr><td colspan="11" class="loading-td">Loading User Management Console...</td></tr>';

  loadUsersKPIs();

  const search = document.getElementById('users-search-input')?.value || '';
  const userType = document.getElementById('users-type-filter')?.value || '';
  const verified = document.getElementById('users-verified-filter')?.value || '';
  const status = document.getElementById('users-status-filter')?.value || '';
  const riskLevel = document.getElementById('users-risk-filter')?.value || '';
  const tag = document.getElementById('users-tag-filter')?.value || '';
  const sortBy = document.getElementById('users-sort-filter')?.value || 'newest';

  try {
    const params = new URLSearchParams({
      search,
      user_type: userType,
      verified,
      status,
      risk_level: riskLevel,
      tag,
      sort_by: sortBy
    });

    const res = await api(`/api/admin/users?${params.toString()}`);
    const users = res.items || [];

    if (users.length === 0) {
      tbody.innerHTML = '<tr><td colspan="11" class="empty-state">No users matching the active filter criteria.</td></tr>';
      return;
    }

    tbody.innerHTML = users.map(u => {
      const isSelected = selectedUserIds.has(u.id);
      const isSuspended = u.status === 'suspended' || u.status === 'banned';
      const isRestricted = u.status === 'restricted';
      const isOnline = u.is_online === 1 || (u.last_active || '').includes('Now') || (u.last_active || '').includes('m ago');

      // Risk score & level styling
      const riskClass = u.risk_level === 'high' ? 'high' : u.risk_level === 'medium' ? 'medium' : 'low';
      const riskEmoji = u.risk_level === 'high' ? '🔴' : u.risk_level === 'medium' ? '🟡' : '🟢';

      // Type Badge
      const typeBadgeClass = u.user_type === 'business' ? 'purple' : u.user_type === 'professional' || u.user_type === 'expert' ? 'blue' : u.role === 'client' ? 'amber' : 'green';
      const typeLabel = u.user_type ? u.user_type.charAt(0).toUpperCase() + u.user_type.slice(1) : (u.role || 'User');

      // Status chip
      const statusChip = isSuspended
        ? '<span class="adm-status-chip red">🔴 Suspended</span>'
        : isRestricted
        ? '<span class="adm-status-chip amber">🟡 Restricted</span>'
        : '<span class="adm-status-chip green">🟢 Active</span>';

      // Verification Badge
      const verBadge = u.is_verified
        ? `<span class="adm-badge verified" title="${escapeHtml(u.verified_as || 'Identity Verified')}">✓ Verified ${u.verified_as ? `<small>(${escapeHtml(u.verified_as)})</small>` : ''}</span>`
        : `<span class="adm-badge unverified">Unverified</span>`;

      // Tags pills
      const tagPills = (u.tags || []).slice(0, 2).map(t => `<span class="user-tag-pill">${escapeHtml(t)}</span>`).join('');

      // Earnings or Spent
      const isClient = u.role === 'client' || u.user_type === 'business';
      const financialVal = isClient
        ? `<span style="color:#EC4899;font-weight:700">Spent: $${Number(u.spent_amount || 0).toLocaleString()}</span>`
        : `<span style="color:#10B981;font-weight:700">৳${Number(u.total_earned || 0).toLocaleString()}</span>`;

      return `
        <tr style="${isSuspended ? 'opacity:0.75;background:rgba(239,68,68,0.03)' : ''}" class="${isSelected ? 'selected-row' : ''}">
          <td style="text-align:center">
            <input type="checkbox" class="user-row-chk" value="${u.id}" ${isSelected ? 'checked' : ''} onchange="toggleUserRowSelect(${u.id}, this.checked)">
          </td>
          <td>
            <div class="user-cell">
              <div class="user-avatar-wrap">
                <span class="adm-avatar-circle" style="background:${u.avatar_color || '#6366F1'};width:38px;height:38px;font-size:0.95rem">${(u.name || 'U').substring(0, 2).toUpperCase()}</span>
                <span class="user-online-dot ${isOnline ? '' : 'offline'}" title="${isOnline ? 'Online Now' : 'Offline'}"></span>
              </div>
              <div class="user-meta-info">
                <b style="cursor:pointer;color:#fff;display:inline-block" onclick="openUser360Drawer(${u.id})">${escapeHtml(u.name)}</b>
                <small style="color:#94A3B8;display:block">@${escapeHtml(u.username || 'user')} · ID #${u.id} · ${escapeHtml(u.country || 'BD')}</small>
                <div>${tagPills}</div>
              </div>
            </div>
          </td>
          <td>
            <span class="adm-status-chip ${typeBadgeClass}">${escapeHtml(typeLabel)}</span>
          </td>
          <td>${verBadge}</td>
          <td>
            <b style="color:#fff">${u.tasks_completed || 0}</b>
            <small style="color:#94A3B8;display:block">completed</small>
          </td>
          <td>
            ${financialVal}
            <small style="color:#94A3B8;display:block">Bal: $${Number(u.wallet_balance || 0).toFixed(2)}</small>
          </td>
          <td>
            <span style="color:#FBBF24;font-weight:700">⭐ ${Number(u.rating || 5).toFixed(1)}</span>
            <small style="color:#94A3B8;display:block">(${u.rating_count || 1} reviews)</small>
          </td>
          <td>
            <span class="risk-pill ${riskClass}">${riskEmoji} ${u.risk_score || 14}/100</span>
          </td>
          <td>${statusChip}</td>
          <td>
            <span style="font-size:0.75rem;color:#CBD5E1">${escapeHtml(u.last_active || '5m ago')}</span>
          </td>
          <td style="text-align:right">
            <div class="adm-action-dropdown-wrap" id="action-wrap-${u.id}">
              <button class="adm-action-trigger" onclick="toggleUserActionDropdown(${u.id}, event)">⋮</button>
              <div class="adm-action-menu">
                <a class="adm-act-link" href="javascript:void(0)" onclick="openUser360Drawer(${u.id})">👁️ View 360° Profile</a>
                <a class="adm-act-link" href="javascript:void(0)" onclick="openEditUserModal(${u.id})">✏️ Edit User Details</a>
                <a class="adm-act-link" href="javascript:void(0)" onclick="openBalanceAdjustModal(${u.id})">💳 Adjust Wallet Balance</a>
                <a class="adm-act-link" href="javascript:void(0)" onclick="openAddTagModal(${u.id})">🏷️ Assign Custom Tag</a>
                <a class="adm-act-link" href="javascript:void(0)" onclick="switchView('tasks');document.getElementById('task-search-input').value='${escapeHtml(u.name)}';loadTasksTable()">💼 View User Tasks</a>
                <a class="adm-act-link" href="javascript:void(0)" onclick="switchView('transactions');loadTransactionsTable()">📜 View Transactions</a>
                <a class="adm-act-link" href="javascript:void(0)" onclick="openPasswordModal(${u.id}, '${escapeHtml(u.name)}')">🔑 Reset Password</a>
                <a class="adm-act-link" href="javascript:void(0)" onclick="handleImpersonateUser(${u.id})">🎭 Impersonate User</a>
                <div class="adm-act-divider"></div>
                <a class="adm-act-link" href="javascript:void(0)" onclick="openRestrictModal(${u.id})">⚠️ Restrict Account</a>
                <a class="adm-act-link" href="javascript:void(0)" onclick="handleFreezeWallet(${u.id}, ${u.is_wallet_frozen ? 0 : 1})">${u.is_wallet_frozen ? '🟢 Unfreeze Wallet' : '❄️ Freeze Wallet'}</a>
                <a class="adm-act-link ${isSuspended ? '' : 'danger'}" href="javascript:void(0)" onclick="handleSuspendUser(${u.id})">${isSuspended ? '🟢 Unsuspend Account' : '🚫 Suspend Account'}</a>
                <a class="adm-act-link danger" href="javascript:void(0)" onclick="deleteUserRecord(${u.id})">🗑️ Delete Account</a>
              </div>
            </div>
          </td>
        </tr>
      `;
    }).join('');

  } catch (err) {
    tbody.innerHTML = `<tr><td colspan="11" class="error-td">Error loading users: ${err.message}</td></tr>`;
  }
}

// Toggle Dropdown Action Menu
window.toggleUserActionDropdown = function(userId, e) {
  e.stopPropagation();
  document.querySelectorAll('.adm-action-dropdown-wrap').forEach(w => {
    if (w.id !== `action-wrap-${userId}`) w.classList.remove('open');
  });
  const wrap = document.getElementById(`action-wrap-${userId}`);
  if (wrap) wrap.classList.toggle('open');
};

document.addEventListener('click', () => {
  document.querySelectorAll('.adm-action-dropdown-wrap').forEach(w => w.classList.remove('open'));
});

// User Filter & Search Event Listeners
['users-search-input', 'users-type-filter', 'users-verified-filter', 'users-status-filter', 'users-risk-filter', 'users-tag-filter', 'users-sort-filter'].forEach(id => {
  const el = document.getElementById(id);
  if (el) {
    el.addEventListener('input', () => {
      clearTimeout(usersSearchTimeout);
      usersSearchTimeout = setTimeout(loadUsersTable, 250);
    });
    el.addEventListener('change', loadUsersTable);
  }
});

// Multi-Select Checkbox Handling
window.toggleUserRowSelect = function(userId, isChecked) {
  if (isChecked) selectedUserIds.add(userId);
  else selectedUserIds.delete(userId);
  updateBulkActionBar();
};

window.toggleAllUsersSelection = function(masterCheckbox) {
  const isChecked = masterCheckbox.checked;
  document.querySelectorAll('.user-row-chk').forEach(chk => {
    chk.checked = isChecked;
    const uid = Number(chk.value);
    if (isChecked) selectedUserIds.add(uid);
    else selectedUserIds.delete(uid);
  });
  updateBulkActionBar();
};

function updateBulkActionBar() {
  const bar = document.getElementById('users-bulk-bar');
  const countEl = document.getElementById('users-bulk-count');
  if (!bar || !countEl) return;

  const count = selectedUserIds.size;
  countEl.textContent = `${count} user${count === 1 ? '' : 's'} selected`;
  if (count > 0) bar.classList.add('visible');
  else bar.classList.remove('visible');
}

window.clearUsersSelection = function() {
  selectedUserIds.clear();
  const masterChk = document.getElementById('chk-users-select-all');
  if (masterChk) masterChk.checked = false;
  document.querySelectorAll('.user-row-chk').forEach(chk => chk.checked = false);
  updateBulkActionBar();
};

window.executeBulkAction = async function(action) {
  if (selectedUserIds.size === 0) return toast('No users selected for bulk action', 'warning');
  const userIds = Array.from(selectedUserIds);

  let payload = {};
  if (action === 'add_tag') {
    const tag = prompt('Enter custom tag name to apply to selected users (e.g. VIP, Top Earner):', 'Verified Expert');
    if (!tag) return;
    payload.tag = tag;
  }

  if (!confirm(`Are you sure you want to execute bulk [${action.toUpperCase()}] on ${userIds.length} users?`)) return;

  try {
    const res = await api('/api/admin/users/bulk', {
      method: 'POST',
      body: { userIds, action, payload }
    });
    toast(`Successfully executed ${action.toUpperCase()} on ${res.affectedCount} users!`, 'success');
    clearUsersSelection();
    loadUsersTable();
  } catch (err) { toast(err.message, 'error'); }
};

window.triggerBulkSelected = function(action) {
  executeBulkAction(action);
};

/* ---------- USER 360° PROFILE DRAWER CONTROLLER ---------- */
window.openUser360Drawer = async function(userId) {
  current360UserId = userId;
  const overlay = document.getElementById('drawer-user-360-overlay');
  if (overlay) overlay.classList.add('open');

  try {
    const data = await api(`/api/admin/users/${userId}/360`);
    const u = data.user;
    const m = data.metrics || {};
    const risk = data.riskProfile || {};

    // Header updates
    setElText('u360-name', u.name);
    setElText('u360-username', `@${u.username || 'user'}`);
    setElText('u360-email', u.email);
    setElText('u360-country', `📍 ${u.country || 'Bangladesh'}`);
    const statusPill = document.getElementById('u360-status-pill');
    if (statusPill) {
      statusPill.textContent = (u.status || 'active').toUpperCase();
      statusPill.className = `adm-status-chip ${u.status === 'suspended' ? 'red' : u.status === 'restricted' ? 'amber' : 'green'}`;
    }
    const riskPill = document.getElementById('u360-risk-pill');
    if (riskPill) {
      riskPill.textContent = `🛡️ Risk: ${risk.score || 14}/100`;
      riskPill.className = `risk-pill ${risk.level || 'low'}`;
    }

    const verBadge = document.getElementById('u360-badge-verified');
    if (verBadge) {
      verBadge.style.display = u.is_verified ? 'inline-block' : 'none';
      verBadge.textContent = `✓ Verified ${u.verified_as ? `(${u.verified_as})` : ''}`;
    }

    const tagsContainer = document.getElementById('u360-tags-container');
    if (tagsContainer) {
      tagsContainer.innerHTML = (u.tags || []).map(t => `<span class="user-tag-pill">${escapeHtml(t)}</span>`).join('');
    }

    // Avatar
    const avatarImg = document.getElementById('u360-avatar-img');
    if (avatarImg) {
      avatarImg.src = `https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=100&auto=format&fit=crop&q=80`;
    }

    // 1. Overview Tab
    setElText('u360-m-tasks', m.tasksCompleted || 0);
    setElText('u360-m-success', `${m.successRate || 100}%`);
    setElText('u360-m-earnings', u.role === 'client' ? `Spent $${(m.lifetimeSpending || 0).toLocaleString()}` : `৳${(m.lifetimeEarnings || 0).toLocaleString()}`);
    setElText('u360-m-rating', `⭐ ${(m.averageRating || 5.0).toFixed(1)}`);
    setElText('u360-m-reviews', m.totalReviews || 0);
    setElText('u360-m-response', m.avgResponseTime || '20m');
    setElText('u360-ai-insight', u.ai_insight || 'High integrity user pattern with consistent successful task completion.');
    setElText('u360-bio', u.bio || 'No public bio provided.');

    // Recent Tasks
    const recentTasksContainer = document.getElementById('u360-recent-tasks-list');
    if (recentTasksContainer) {
      const allTasks = [...(data.createdTasks || []), ...(data.assignedTasks || [])].slice(0, 4);
      if (allTasks.length === 0) {
        recentTasksContainer.innerHTML = '<small style="color:#64748B">No recent tasks recorded.</small>';
      } else {
        recentTasksContainer.innerHTML = allTasks.map(t => `
          <div style="display:flex;justify-content:space-between;align-items:center;background:#0F172A;padding:8px 12px;border-radius:8px">
            <div>
              <b style="color:#fff;font-size:0.8rem">#${t.id} - ${escapeHtml(t.title)}</b>
              <small style="color:#94A3B8;display:block">$${t.budget.toFixed(2)}</small>
            </div>
            <span class="adm-status-chip ${t.status === 'completed' ? 'green' : 'blue'}">${t.status}</span>
          </div>
        `).join('');
      }
    }

    // 2. Personal Info Tab
    setElText('u360-pi-name', u.name);
    setElText('u360-pi-username', `@${u.username || 'user'}`);
    setElText('u360-pi-email', u.email);
    setElText('u360-pi-phone', u.phone || '+880 1711-000000');
    setElText('u360-pi-location', `${u.location || 'Dhaka'}, ${u.country || 'Bangladesh'}`);
    setElText('u360-pi-timezone', u.timezone || 'Asia/Dhaka (GMT+6)');
    setElText('u360-pi-languages', u.languages || 'Bengali, English');
    setElText('u360-pi-joined', u.created_at ? new Date(u.created_at).toLocaleDateString() : 'August 2026');

    // 3. Professional Info Tab
    setElText('u360-pr-title', u.profession || 'Micro-Task Specialist');
    setElText('u360-pr-verified-as', u.verified_as || 'Standard Member');
    setElText('u360-pr-avail', u.availability || 'Available');
    const skillsContainer = document.getElementById('u360-pr-skills');
    if (skillsContainer) {
      skillsContainer.innerHTML = (u.skills || 'General Freelancing').split(',').map(s => `<span class="user-tag-pill" style="background:#1E293B;color:#fff">${escapeHtml(s.trim())}</span>`).join('');
    }

    // 4. Financial Tab
    setElText('u360-fin-balance', `৳${Number(u.wallet_balance || 0).toLocaleString()}`);
    setElText('u360-fin-pending', `৳${Number(u.pending_balance || 0).toLocaleString()}`);
    const frozenEl = document.getElementById('u360-fin-frozen');
    if (frozenEl) {
      frozenEl.textContent = u.is_wallet_frozen ? '🔴 Wallet Frozen' : '🟢 Active / Unfrozen';
      frozenEl.style.color = u.is_wallet_frozen ? '#EF4444' : '#10B981';
    }

    // 5. Activity & Devices Tab
    const devList = document.getElementById('u360-devices-list');
    if (devList) {
      devList.innerHTML = (u.devices || ['Chrome (Windows 11)']).map(d => `
        <div style="background:#111827;padding:8px 12px;border-radius:8px;border:1px solid rgba(255,255,255,0.05);display:flex;align-items:center;gap:10px">
          <span style="font-size:1.1rem">💻</span>
          <b style="color:#fff;font-size:0.82rem">${escapeHtml(d)}</b>
        </div>
      `).join('');
    }
    const ipList = document.getElementById('u360-ip-list');
    if (ipList) {
      ipList.innerHTML = (u.ip_history || ['127.0.0.1']).map(ip => `
        <div style="background:#111827;padding:8px 12px;border-radius:8px;border:1px solid rgba(255,255,255,0.05);display:flex;justify-content:space-between;align-items:center">
          <span style="font-family:monospace;color:#38BDF8;font-size:0.82rem">${escapeHtml(ip)}</span>
          <span style="color:#64748B;font-size:0.75rem">Dhaka, Bangladesh</span>
        </div>
      `).join('');
    }

    // 6. Trust & Safety Tab
    const safetyScoreEl = document.getElementById('u360-safety-score');
    if (safetyScoreEl) {
      safetyScoreEl.textContent = `${risk.score || 14} / 100 — ${(risk.level || 'low').toUpperCase()} RISK`;
      safetyScoreEl.style.color = risk.level === 'high' ? '#EF4444' : risk.level === 'medium' ? '#F59E0B' : '#10B981';
    }
    const signalsList = document.getElementById('u360-signals-list');
    if (signalsList) {
      signalsList.innerHTML = (risk.signals || []).map(s => `
        <div class="risk-signal-item">
          <span style="color:#E2E8F0">${escapeHtml(s.text)}</span>
          <span class="adm-status-chip ${s.status === 'trusted' ? 'green' : 'amber'}">${s.status.toUpperCase()}</span>
        </div>
      `).join('');
    }

    // 7. Admin Notes Tab
    renderU360Notes(u.admin_notes || []);

    // Open first tab by default
    switchU360Tab('overview', document.querySelector('.u360-tab-btn'));

  } catch (err) {
    toast(`Failed to load user 360 dossier: ${err.message}`, 'error');
  }
};

window.closeUser360Drawer = function() {
  const overlay = document.getElementById('drawer-user-360-overlay');
  if (overlay) overlay.classList.remove('open');
  current360UserId = null;
};

window.switchU360Tab = function(tabName, btn) {
  document.querySelectorAll('.u360-tab-btn').forEach(b => b.classList.remove('active'));
  document.querySelectorAll('.u360-tab-content').forEach(c => c.style.display = 'none');
  if (btn) btn.classList.add('active');
  const target = document.getElementById(`u360-tab-${tabName}`);
  if (target) target.style.display = 'block';
};

function renderU360Notes(notes) {
  const container = document.getElementById('u360-notes-list');
  if (!container) return;
  if (!notes || notes.length === 0) {
    container.innerHTML = '<small style="color:#64748B">No internal notes written yet for this user.</small>';
    return;
  }
  container.innerHTML = notes.map(n => `
    <div style="background:#111827;padding:10px 14px;border-radius:8px;border:1px solid rgba(255,255,255,0.06)">
      <div style="display:flex;justify-content:space-between;margin-bottom:4px">
        <b style="color:#818CF8;font-size:0.78rem">🛡️ ${escapeHtml(n.admin || 'Admin')}</b>
        <small style="color:#64748B">${escapeHtml(n.date || 'Today')}</small>
      </div>
      <p style="margin:0;color:#CBD5E1;font-size:0.82rem;line-height:1.4">${escapeHtml(n.note)}</p>
    </div>
  `).join('');
}

window.handleU360AddNote = async function(e) {
  e.preventDefault();
  const input = document.getElementById('u360-new-note-text');
  if (!input || !input.value.trim() || !current360UserId) return;
  const note = input.value.trim();

  try {
    const res = await api(`/api/admin/users/${current360UserId}/notes`, {
      method: 'POST',
      body: { note }
    });
    input.value = '';
    toast('Private admin note appended and saved!', 'success');
    openUser360Drawer(current360UserId);
  } catch (err) { toast(err.message, 'error'); }
};

window.handleU360BalanceAdjust = async function(e) {
  e.preventDefault();
  if (!current360UserId) return;
  const type = document.getElementById('u360-adj-type').value;
  const amount = Number(document.getElementById('u360-adj-amount').value);
  const reason = document.getElementById('u360-adj-reason').value.trim();

  if (!amount || isNaN(amount)) return toast('Please enter a valid adjustment amount', 'warning');
  if (!reason) return toast('Mandatory audit justification required', 'warning');

  try {
    await api(`/api/admin/users/${current360UserId}/balance-adjust`, {
      method: 'POST',
      body: { amount, type, reason }
    });
    toast(`Balance successfully ${type === 'credit' ? 'credited' : 'debited'} by ৳${amount.toLocaleString()} with audit record!`, 'success');
    document.getElementById('u360-adj-amount').value = '';
    document.getElementById('u360-adj-reason').value = '';
    openUser360Drawer(current360UserId);
    loadUsersTable();
  } catch (err) { toast(err.message, 'error'); }
};

/* ---------- MODALS & STANDALONE HANDLERS ---------- */
window.openBalanceAdjustModal = function(userId) {
  document.getElementById('mba-user-id').value = userId;
  document.getElementById('mba-amount').value = '';
  document.getElementById('mba-reason').value = '';
  openModal('modal-user-balance-adjust');
};

window.handleDirectBalanceAdjust = async function(e) {
  e.preventDefault();
  const userId = document.getElementById('mba-user-id').value;
  const type = document.getElementById('mba-type').value;
  const amount = Number(document.getElementById('mba-amount').value);
  const reason = document.getElementById('mba-reason').value.trim();

  try {
    await api(`/api/admin/users/${userId}/balance-adjust`, {
      method: 'POST',
      body: { amount, type, reason }
    });
    toast(`Audited adjustment executed: ${type.toUpperCase()} $${amount}`, 'success');
    closeModal('modal-user-balance-adjust');
    loadUsersTable();
  } catch (err) { toast(err.message, 'error'); }
};

window.openAddTagModal = function(userId) {
  document.getElementById('tag-user-id').value = userId;
  openModal('modal-user-add-tag');
};

window.handleSaveUserTag = async function(e) {
  e.preventDefault();
  const userId = document.getElementById('tag-user-id').value;
  const tag = document.getElementById('tag-select-value').value;

  try {
    await api(`/api/admin/users/${userId}/tags`, {
      method: 'POST',
      body: { tags: [tag] }
    });
    toast(`Tag "${tag}" assigned to user!`, 'success');
    closeModal('modal-user-add-tag');
    loadUsersTable();
    if (current360UserId === Number(userId)) openUser360Drawer(userId);
  } catch (err) { toast(err.message, 'error'); }
};

window.openRestrictModal = function(userId) {
  document.getElementById('restrict-user-id').value = userId;
  document.getElementById('restrict-reason').value = '';
  openModal('modal-user-restrict');
};

window.handleSaveUserRestriction = async function(e) {
  e.preventDefault();
  const userId = document.getElementById('restrict-user-id').value;
  const status = document.getElementById('restrict-status-val').value;
  const reason = document.getElementById('restrict-reason').value.trim();

  try {
    await api(`/api/admin/users/${userId}/restrict`, {
      method: 'POST',
      body: { status, reason }
    });
    toast(`User status updated to ${status.toUpperCase()} (Audited)`, 'success');
    closeModal('modal-user-restrict');
    loadUsersTable();
    if (current360UserId === Number(userId)) openUser360Drawer(userId);
  } catch (err) { toast(err.message, 'error'); }
};

window.handleFreezeWallet = async function(userId, isFrozen) {
  const reason = prompt(`Enter mandatory reason for ${isFrozen ? 'FREEZING' : 'UNFREEZING'} wallet:`, isFrozen ? 'AML Review' : 'Verified');
  if (!reason) return;

  try {
    await api(`/api/admin/users/${userId}/freeze-wallet`, {
      method: 'POST',
      body: { isFrozen, reason }
    });
    toast(`Wallet ${isFrozen ? 'FROZEN' : 'UNFROZEN'} with audit entry.`, 'success');
    loadUsersTable();
    if (current360UserId === Number(userId)) openUser360Drawer(userId);
  } catch (err) { toast(err.message, 'error'); }
};

window.handleImpersonateUser = async function(userId) {
  if (!confirm(`⚠️ STRICT SECURITY WARNING: Impersonating User #${userId} will be logged in the immutable security audit trail with your IP and admin credentials. Proceed?`)) return;
  try {
    toast(`Logging in as User #${userId} (Audited session established)...`, 'info');
    setTimeout(() => {
      window.location.href = `/profile?impersonate_user=${userId}`;
    }, 600);
  } catch (err) { toast(err.message, 'error'); }
};

window.handleSuspendUser = async function(userId) {
  const isSuspended = confirm(`Do you want to toggle SUSPENSION for User #${userId}?`);
  if (!isSuspended) return;

  try {
    await api(`/api/admin/users/${userId}/restrict`, {
      method: 'POST',
      body: { status: 'suspended', reason: 'Admin Trust & Safety Action' }
    });
    toast(`User #${userId} suspended.`, 'success');
    loadUsersTable();
    if (current360UserId === Number(userId)) openUser360Drawer(userId);
  } catch (err) { toast(err.message, 'error'); }
};

/* ==========================================================================
   SECTION 3B. USER VERIFICATION & KYC MANAGEMENT CENTER
   ========================================================================== */

let kycSearchTimer = null;
let currentInspectedKycId = null;

window.debounceKycSearch = function() {
  clearTimeout(kycSearchTimer);
  kycSearchTimer = setTimeout(() => loadKycTable(), 300);
};

window.filterKycByKpi = function(kpiType) {
  document.querySelectorAll('#view-kyc .adm-ukpi-card').forEach(c => c.classList.remove('active-filter-kpi'));
  const card = document.getElementById(`kyccard-${kpiType}`);
  if (card) card.classList.add('active-filter-kpi');

  const statusSel = document.getElementById('kyc-status-filter');
  const typeSel = document.getElementById('kyc-type-filter');

  if (kpiType === 'total') {
    if (statusSel) statusSel.value = 'all';
    if (typeSel) typeSel.value = 'all';
  } else if (kpiType === 'pending') {
    if (statusSel) statusSel.value = 'pending';
    if (typeSel) typeSel.value = 'all';
  } else if (kpiType === 'approved') {
    if (statusSel) statusSel.value = 'approved';
    if (typeSel) typeSel.value = 'all';
  } else if (kpiType === 'rejected') {
    if (statusSel) statusSel.value = 'rejected';
    if (typeSel) typeSel.value = 'all';
  } else if (kpiType === 'pro') {
    if (statusSel) statusSel.value = 'all';
    if (typeSel) typeSel.value = 'bmdc_doctor';
  } else if (kpiType === 'nid') {
    if (statusSel) statusSel.value = 'all';
    if (typeSel) typeSel.value = 'nid';
  }

  loadKycTable();
};

window.resetKycFilters = function() {
  const searchInput = document.getElementById('kyc-search-input');
  if (searchInput) searchInput.value = '';
  const typeFilter = document.getElementById('kyc-type-filter');
  if (typeFilter) typeFilter.value = 'all';
  const statusFilter = document.getElementById('kyc-status-filter');
  if (statusFilter) statusFilter.value = 'all';
  const riskFilter = document.getElementById('kyc-risk-filter');
  if (riskFilter) riskFilter.value = 'all';
  const sortFilter = document.getElementById('kyc-sort-filter');
  if (sortFilter) sortFilter.value = 'newest';

  document.querySelectorAll('#view-kyc .adm-ukpi-card').forEach(c => c.classList.remove('active-filter-kpi'));
  const totalCard = document.getElementById('kyccard-total');
  if (totalCard) totalCard.classList.add('active-filter-kpi');

  loadKycTable();
};

window.loadKycTable = async function() {
  const tbody = document.getElementById('kyc-table-body');
  if (!tbody) return;

  // 1. Fetch Summary KPIs
  try {
    const kpis = await api('/api/admin/kyc/kpis');
    setElText('kyckpi-total', (kpis.totalSubmissions || 10).toLocaleString());
    setElText('kyckpi-pending', (kpis.pendingReview || 0).toLocaleString());
    setElText('kyckpi-approved', (kpis.approvedToday || 0).toLocaleString());
    setElText('kyckpi-rejected', (kpis.rejectedCount || 0).toLocaleString());
    setElText('kyckpi-pro', (kpis.proLicenses || 0).toLocaleString());
    setElText('kyckpi-nid', (kpis.nidPassports || 0).toLocaleString());
    setElText('kyckpi-sla', kpis.avgSla || '18m');
    setElText('kyckpi-aimatch', kpis.aiMatchRate || '99.2%');
  } catch (err) {
    console.warn('Could not load KYC KPIs:', err);
  }

  // 2. Fetch Filtered KYC List
  const search = document.getElementById('kyc-search-input')?.value.trim() || '';
  const docType = document.getElementById('kyc-type-filter')?.value || 'all';
  const status = document.getElementById('kyc-status-filter')?.value || 'all';
  const riskLevel = document.getElementById('kyc-risk-filter')?.value || 'all';
  const sortBy = document.getElementById('kyc-sort-filter')?.value || 'newest';

  tbody.innerHTML = '<tr><td colspan="9" class="loading-td">Loading Verification Queue...</td></tr>';

  try {
    const query = new URLSearchParams({
      search,
      doc_type: docType,
      status,
      risk_level: riskLevel,
      sort_by: sortBy
    });

    const res = await api(`/api/admin/kyc?${query.toString()}`);
    const items = res.items || [];

    if (items.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="9" style="text-align:center;padding:40px 20px;color:#94A3B8">
            <div style="font-size:2.2rem;margin-bottom:8px">🛡️</div>
            <b>No verification submissions found matching current criteria.</b>
            <div style="margin-top:6px"><button class="btn btn-outline-light btn-sm" onclick="resetKycFilters()">Reset Filters</button></div>
          </td>
        </tr>
      `;
      return;
    }

    tbody.innerHTML = items.map(item => {
      const riskClass = item.ai_risk_level === 'high' ? 'red' : item.ai_risk_level === 'medium' ? 'amber' : 'green';
      const statusChip = item.status === 'approved' ? '<span class="adm-status-chip green">✓ Verified</span>' :
                         item.status === 'rejected' ? '<span class="adm-status-chip red">✕ Rejected</span>' :
                         item.status === 'resubmit_requested' ? '<span class="adm-status-chip purple">🔄 Re-Submit</span>' :
                         '<span class="adm-status-chip warning">⏳ Pending</span>';

      return `
        <tr>
          <td style="text-align:center">
            <input type="checkbox" class="chk-kyc-row" value="${item.id}" onchange="updateKycSelectionState()">
          </td>
          <td>
            <div style="display:flex;align-items:center;gap:10px">
              <div class="adm-avatar-circle" style="width:34px;height:34px;font-size:0.85rem;background:${item.user_avatar_color || '#6366F1'};color:#fff;display:flex;align-items:center;justify-content:center;border-radius:50%;font-weight:700">
                ${(item.user_name || 'U').substring(0, 2).toUpperCase()}
              </div>
              <div>
                <b style="color:#fff;display:block;cursor:pointer" onclick="openUser360Drawer(${item.user_id})">${escapeHtml(item.user_name)}</b>
                <small style="color:#94A3B8">@${escapeHtml(item.user_username)} • ${escapeHtml(item.user_phone)}</small>
              </div>
            </div>
          </td>
          <td>
            <div style="font-weight:700;color:#E2E8F0;font-size:0.84rem">${escapeHtml(item.doc_type_label || item.doc_type)}</div>
            <small style="color:#64748B">${escapeHtml(item.council_name || 'Official Authority')}</small>
          </td>
          <td>
            <code style="background:rgba(255,255,255,0.06);padding:2px 6px;border-radius:4px;color:#38BDF8;font-size:0.8rem">${escapeHtml(item.doc_number || item.nid_number || 'N/A')}</code>
          </td>
          <td>
              <div onclick="openLightboxImageSrc('${item.front_image}')" title="Front / Main Document" style="width:32px;height:24px;border-radius:4px;overflow:hidden;background:#0F172A;border:1px solid rgba(255,255,255,0.1);cursor:pointer">
                <img src="${item.front_image}" alt="Front" style="width:100%;height:100%;object-fit:cover">
              </div>
              ${item.back_image ? `
                <div onclick="openLightboxImageSrc('${item.back_image}')" title="Back ID" style="width:32px;height:24px;border-radius:4px;overflow:hidden;background:#0F172A;border:1px solid rgba(255,255,255,0.1);cursor:pointer">
                  <img src="${item.back_image}" alt="Back" style="width:100%;height:100%;object-fit:cover">
                </div>
              ` : ''}
              ${item.selfie_image ? `
                <div onclick="openLightboxImageSrc('${item.selfie_image}')" title="Selfie with ID" style="width:32px;height:24px;border-radius:4px;overflow:hidden;background:#0F172A;border:1px solid rgba(255,255,255,0.1);cursor:pointer">
                  <img src="${item.selfie_image}" alt="Selfie" style="width:100%;height:100%;object-fit:cover">
                </div>
              ` : ''}
            </div>
          </td>
          <td>
            <div style="font-size:0.78rem;color:#34D399;font-weight:700">🤖 ${item.ai_face_match || 98}% Face Match</div>
            <small class="adm-status-chip ${riskClass}" style="font-size:0.68rem;padding:1px 6px">Risk: ${item.ai_risk_score || 10}/100</small>
          </td>
          <td>
            <div style="color:#CBD5E1;font-size:0.8rem">${escapeHtml(item.submitted_at ? item.submitted_at.substring(5, 16) : 'Today')}</div>
            <small style="color:#34D399">✓ Within 24h SLA</small>
          </td>
          <td>${statusChip}</td>
          <td style="text-align:right;white-space:nowrap">
            <button class="btn btn-outline-light btn-sm" onclick="openInspectKycModal(${item.id})" title="Inspect Full Documents Dossier">👁️ Inspect</button>
            ${item.status === 'pending' ? `
              <button class="btn btn-green btn-sm" onclick="quickApproveKyc(${item.id})" title="1-Click Approve">✓</button>
              <button class="btn btn-red btn-sm" onclick="quickRejectKyc(${item.id})" title="Reject with Reason">✕</button>
            ` : ''}
          </td>
        </tr>
      `;
    }).join('');

    updateKycSelectionState();

  } catch (err) {
    tbody.innerHTML = `<tr><td colspan="9" style="text-align:center;color:#EF4444;padding:30px">Failed to load verification queue: ${escapeHtml(err.message)}</td></tr>`;
  }
};

window.toggleAllKycSelection = function(master) {
  document.querySelectorAll('.chk-kyc-row').forEach(c => c.checked = master.checked);
  updateKycSelectionState();
};

window.updateKycSelectionState = function() {
  const checked = document.querySelectorAll('.chk-kyc-row:checked');
  const bar = document.getElementById('kyc-bulk-bar');
  const countEl = document.getElementById('kyc-bulk-count');
  if (bar && countEl) {
    if (checked.length > 0) {
      countEl.textContent = `${checked.length} submission${checked.length > 1 ? 's' : ''} selected`;
      bar.classList.add('active');
    } else {
      bar.classList.remove('active');
    }
  }
};

window.clearKycSelection = function() {
  document.querySelectorAll('.chk-kyc-row').forEach(c => c.checked = false);
  const master = document.getElementById('chk-kyc-select-all');
  if (master) master.checked = false;
  updateKycSelectionState();
};

window.openInspectKycModal = async function(kycId) {
  currentInspectedKycId = kycId;
  openModal('modal-inspect-kyc');

  try {
    const kyc = await api(`/api/admin/kyc/${kycId}`);
    
    // Header details
    setElText('mkyc-user-name', kyc.user_name);
    setElText('mkyc-user-username', `@${kyc.user_username}`);
    setElText('mkyc-user-email', kyc.user_email);
    setElText('mkyc-user-phone', kyc.user_phone || 'N/A');
    setElText('mkyc-sub-id', `#KYC-${kyc.id}`);
    setElText('mkyc-sub-time', `Submitted ${kyc.submitted_at || 'Recently'}`);

    const avatar = document.getElementById('mkyc-avatar');
    if (avatar) {
      avatar.style.background = kyc.user_avatar_color || '#6366F1';
      avatar.textContent = (kyc.user_name || 'U').substring(0, 2).toUpperCase();
    }

    const chip = document.getElementById('mkyc-status-chip');
    if (chip) {
      chip.className = `adm-status-chip ${kyc.status === 'approved' ? 'green' : kyc.status === 'rejected' ? 'red' : kyc.status === 'resubmit_requested' ? 'purple' : 'warning'}`;
      chip.textContent = kyc.status === 'approved' ? '✓ Verified' : kyc.status === 'rejected' ? '✕ Rejected' : kyc.status === 'resubmit_requested' ? '🔄 Re-Submit' : '⏳ Pending Review';
    }

    // Images
    const imgFront = document.getElementById('mkyc-img-front');
    const imgBack = document.getElementById('mkyc-img-back');
    const imgSelfie = document.getElementById('mkyc-img-selfie');
    const imgCert = document.getElementById('mkyc-img-cert');
    const certWrap = document.getElementById('mkyc-card-cert-wrap');

    if (imgFront) imgFront.src = kyc.front_image || '';
    if (imgBack) {
      imgBack.src = kyc.back_image || '';
      const backCard = imgBack.closest('.kyc-doc-card');
      if (backCard) backCard.style.display = kyc.back_image ? 'block' : 'none';
    }
    if (imgSelfie) {
      imgSelfie.src = kyc.selfie_image || '';
      const selfieCard = imgSelfie.closest('.kyc-doc-card');
      if (selfieCard) selfieCard.style.display = kyc.selfie_image ? 'block' : 'none';
    }
    if (imgCert) imgCert.src = kyc.certificate_image || kyc.front_image || '';
    if (certWrap) certWrap.style.display = kyc.certificate_image ? 'block' : 'none';

    // Info table
    setElText('mkyc-info-type', kyc.doc_type_label || kyc.doc_type);
    setElText('mkyc-info-docnum', kyc.doc_number || 'N/A');
    setElText('mkyc-info-nid', kyc.nid_number || kyc.doc_number || 'N/A');
    setElText('mkyc-info-council', kyc.institution_name ? `${kyc.degree_name || 'Degree'} • ${kyc.institution_name} (${kyc.passing_year || ''})` : (kyc.cert_title ? `${kyc.cert_title} (${kyc.council_name || 'Board'})` : (kyc.council_name || 'Official Authority')));

    // AI Biometrics
    setElText('mkyc-ai-face', `${kyc.ai_face_match || 98.4}%`);
    setElText('mkyc-ai-ocr', `${kyc.ai_ocr_match || 100}% Match`);
    setElText('mkyc-ai-tamper', `${kyc.ai_tamper_score || 0.0}% Clean`);
    setElText('mkyc-ai-risk', `${kyc.ai_risk_score || 8} / 100`);

    // Form inputs
    document.getElementById('mkyc-hidden-id').value = kyc.id;
    const badgeSelect = document.getElementById('mkyc-select-badge');
    if (badgeSelect) {
      if (kyc.verified_as) badgeSelect.value = kyc.verified_as;
      else if (kyc.doc_type === 'bmdc_doctor') badgeSelect.value = 'Doctor';
      else if (kyc.doc_type === 'ieb_engineer') badgeSelect.value = 'Engineer';
      else if (kyc.doc_type === 'bar_lawyer') badgeSelect.value = 'Lawyer';
      else if (kyc.doc_type === 'trade_license') badgeSelect.value = 'Enterprise Brand';
      else badgeSelect.value = 'Verified Member';
    }

    document.getElementById('mkyc-notes-input').value = kyc.notes || kyc.rejection_reason || '';

  } catch (err) {
    toast(`Failed to load dossier: ${err.message}`, 'error');
  }
};

window.openLightboxImage = function(imgElId) {
  const img = document.getElementById(imgElId);
  if (img && img.src) {
    openLightboxImageSrc(img.src);
  }
};

window.openLightboxImageSrc = function(src) {
  const fullImg = document.getElementById('lightbox-full-image');
  if (fullImg) fullImg.src = src;
  openModal('modal-lightbox-viewer');
};

window.submitKycAction = async function(actionType) {
  const id = document.getElementById('mkyc-hidden-id')?.value || currentInspectedKycId;
  if (!id) return;

  const verifiedAs = document.getElementById('mkyc-select-badge')?.value;
  const notes = document.getElementById('mkyc-notes-input')?.value.trim();

  try {
    if (actionType === 'approve') {
      await api(`/api/admin/kyc/${id}/approve`, {
        method: 'POST',
        body: { verified_as: verifiedAs, notes }
      });
      toast('Verification APPROVED! User granted verified badge.', 'success');
    } else if (actionType === 'reject') {
      if (!notes) return toast('Please provide a rejection reason for the user.', 'warning');
      await api(`/api/admin/kyc/${id}/reject`, {
        method: 'POST',
        body: { reason: notes }
      });
      toast('Verification application REJECTED with reason notification sent.', 'info');
    } else if (actionType === 'resubmit') {
      if (!notes) return toast('Please specify which document requires re-upload.', 'warning');
      await api(`/api/admin/kyc/${id}/resubmit`, {
        method: 'POST',
        body: { reason: notes }
      });
      toast('Re-submission request dispatched to user!', 'info');
    }

    closeModal('modal-inspect-kyc');
    loadKycTable();
    loadOverview();

  } catch (err) {
    toast(`Action failed: ${err.message}`, 'error');
  }
};

window.quickApproveKyc = async function(id) {
  if (!confirm(`Grant Verified credentials for KYC #${id}?`)) return;
  try {
    await api(`/api/admin/kyc/${id}/approve`, {
      method: 'POST',
      body: { verified_as: 'Verified Member' }
    });
    toast(`KYC #${id} approved!`, 'success');
    loadKycTable();
    loadOverview();
  } catch (err) { toast(err.message, 'error'); }
};

window.quickRejectKyc = async function(id) {
  const reason = prompt('Enter rejection reason for user notification:', 'Document image is unclear');
  if (!reason) return;
  try {
    await api(`/api/admin/kyc/${id}/reject`, {
      method: 'POST',
      body: { reason }
    });
    toast(`KYC #${id} rejected.`, 'info');
    loadKycTable();
    loadOverview();
  } catch (err) { toast(err.message, 'error'); }
};

window.executeKycBulk = async function(action) {
  const checked = Array.from(document.querySelectorAll('.chk-kyc-row:checked')).map(c => Number(c.value));
  if (!checked.length) return toast('No items selected', 'warning');

  let reason = '';
  if (action === 'reject' || action === 'resubmit') {
    reason = prompt(`Enter reason for bulk ${action.toUpperCase()}:`, 'Document quality verification required');
    if (!reason) return;
  }

  try {
    const res = await api('/api/admin/kyc/bulk', {
      method: 'POST',
      body: { ids: checked, action, payload: { reason } }
    });
    toast(`Bulk ${action.toUpperCase()} completed on ${res.affectedCount} applications!`, 'success');
    clearKycSelection();
    loadKycTable();
    loadOverview();
  } catch (err) { toast(err.message, 'error'); }
};

window.triggerBulkKyc = function(action) {
  executeKycBulk(action);
};

window.openManualKycModal = async function() {
  const select = document.getElementById('mkyc-manual-user-select');
  if (select) {
    try {
      const res = await api('/api/admin/users?limit=100');
      const users = res.items || [];
      select.innerHTML = '<option value="">-- Choose User Account --</option>' + users.map(u => `
        <option value="${u.id}">${escapeHtml(u.name)} (@${escapeHtml(u.username)}) - ${escapeHtml(u.email)}</option>
      `).join('');
    } catch (err) {
      console.warn('Could not populate users dropdown:', err);
    }
  }
  openModal('modal-manual-kyc');
};

window.handleManualKycSubmit = async function(e) {
  e.preventDefault();
  const userId = document.getElementById('mkyc-manual-user-select').value;
  const docType = document.getElementById('mkyc-manual-doc-type').value;
  const docNum = document.getElementById('mkyc-manual-docnum').value.trim();
  const badge = document.getElementById('mkyc-manual-badge').value.trim();
  const council = document.getElementById('mkyc-manual-council').value.trim();
  const notes = document.getElementById('mkyc-manual-notes').value.trim();
  const autoApprove = document.getElementById('mkyc-manual-autoapprove').checked;

  if (!userId) return toast('Please select a target user', 'warning');

  try {
    await api('/api/admin/kyc/manual', {
      method: 'POST',
      body: {
        user_id: userId,
        doc_type: docType,
        doc_number: docNum,
        verified_as: badge,
        council_name: council,
        notes,
        auto_approve: autoApprove
      }
    });
    toast('Manual verification record created and registered!', 'success');
    closeModal('modal-manual-kyc');
    loadKycTable();
    loadOverview();
  } catch (err) { toast(err.message, 'error'); }
};

window.openKycSettingsModal = function() {
  openModal('modal-kyc-settings');
};

window.handleKycSettingsSubmit = function(e) {
  e.preventDefault();
  toast('Verification and SLA policy rules saved successfully!', 'success');
  closeModal('modal-kyc-settings');
};

window.exportKycData = async function(format) {
  try {
    const res = await api('/api/admin/kyc');
    const items = res.items || [];
    if (format === 'json') {
      const dataStr = 'data:text/json;charset=utf-8,' + encodeURIComponent(JSON.stringify(items, null, 2));
      const a = document.createElement('a');
      a.href = dataStr;
      a.download = `xtraearn_kyc_export_${Date.now()}.json`;
      a.click();
    } else {
      const headers = ['ID', 'User', 'Username', 'Email', 'Doc Type', 'Doc Number', 'Council', 'Status', 'Risk Score', 'Submitted At'];
      const rows = items.map(k => [
        k.id, `"${k.user_name}"`, k.user_username, k.user_email, k.doc_type, k.doc_number, `"${k.council_name || ''}"`, k.status, k.ai_risk_score, k.submitted_at
      ]);
      const csvContent = 'data:text/csv;charset=utf-8,' + [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
      const a = document.createElement('a');
      a.href = encodeURI(csvContent);
      a.download = `xtraearn_kyc_export_${Date.now()}.csv`;
      a.click();
    }
    toast(`Exported ${items.length} verification records as ${format.toUpperCase()}`, 'success');
  } catch (err) { toast(err.message, 'error'); }
};

