window.openEditUserModal = async function(userId) {
  try {
    const res = await api(`/api/admin/users?q=${userId}`);
    const u = (res.items || []).find(x => x.id === userId);
    if (!u) return toast('User not found', 'error');

    document.getElementById('user-modal-title').textContent = `Edit User: ${u.name}`;
    document.getElementById('user-modal-sub').textContent = `ID #${u.id} · ${u.email}`;
    document.getElementById('uf-user-id').value = u.id;
    document.getElementById('uf-name').value = u.name;
    document.getElementById('uf-email').value = u.email;
    document.getElementById('uf-phone').value = u.phone || '';
    document.getElementById('uf-password-row').style.display = 'none';
    document.getElementById('uf-role').value = u.role;
    document.getElementById('uf-status').value = u.status || 'active';
    document.getElementById('uf-profession').value = u.profession || '';
    document.getElementById('uf-location').value = u.location || 'Bangladesh';
    document.getElementById('uf-skills').value = u.skills || '';
    document.getElementById('uf-languages').value = u.languages || 'Bengali, English';
    document.getElementById('uf-balance').value = Number(u.wallet_balance || 0).toFixed(2);
    document.getElementById('uf-rating').value = Number(u.rating || 5).toFixed(1);
    document.getElementById('uf-verified-as').value = u.verified_as || '';
    document.getElementById('uf-availability').value = u.availability || 'available';
    document.getElementById('uf-bio').value = u.bio || '';
    document.getElementById('uf-is-verified').checked = Boolean(u.is_verified);
    document.getElementById('uf-is-top-earner').checked = Boolean(u.is_top_earner);
    openModal('modal-user-editor');
  } catch (err) { toast(err.message, 'error'); }
};

window.deleteUserRecord = async function(userId) {
  if (!confirm(`Are you sure you want to permanently delete User #${userId}?`)) return;
  try {
    await api(`/api/admin/users/${userId}`, { method: 'DELETE' });
    toast(`User #${userId} deleted successfully`, 'info');
    loadUsersTable();
    loadOverview();
  } catch (err) { toast(err.message, 'error'); }
};

document.getElementById('user-form')?.addEventListener('submit', async e => {
  e.preventDefault();
  const id = document.getElementById('uf-user-id').value;
  const payload = {
    name: document.getElementById('uf-name').value.trim(),
    email: document.getElementById('uf-email').value.trim(),
    phone: document.getElementById('uf-phone').value.trim(),
    role: document.getElementById('uf-role').value,
    status: document.getElementById('uf-status').value,
    profession: document.getElementById('uf-profession').value.trim(),
    location: document.getElementById('uf-location').value.trim(),
    skills: document.getElementById('uf-skills').value.trim(),
    languages: document.getElementById('uf-languages').value.trim(),
    wallet_balance: Number(document.getElementById('uf-balance').value),
    rating: Number(document.getElementById('uf-rating').value),
    is_verified: document.getElementById('uf-is-verified').checked ? 1 : 0,
    verified_as: document.getElementById('uf-verified-as').value.trim(),
    availability: document.getElementById('uf-availability').value,
    bio: document.getElementById('uf-bio').value.trim(),
    is_top_earner: document.getElementById('uf-is-top-earner').checked ? 1 : 0
  };

  try {
    if (id) {
      await api(`/api/admin/users/${id}`, { method: 'POST', body: payload });
      toast('User profile updated successfully', 'success');
    } else {
      payload.password = document.getElementById('uf-password').value || 'Password123!';
      await api('/api/admin/users', { method: 'POST', body: payload });
      toast('New user account created successfully', 'success');
    }
    closeModal('modal-user-editor');
    loadUsersTable();
    loadOverview();
  } catch (err) { toast(err.message, 'error'); }
});


/* ---------- 4. TASKS MODERATION SUITE ---------- */
let tasksSearchTimeout = null;

async function loadTasksTable() {
  const tbody = document.getElementById('tasks-table-body');
  if (!tbody) return;
  tbody.innerHTML = '<tr><td colspan="7" class="loading-td">Loading tasks...</td></tr>';

  const q = document.getElementById('tasks-search-input')?.value || '';
  const status = document.getElementById('tasks-status-filter')?.value || '';
  const categoryId = document.getElementById('tasks-cat-filter')?.value || '';
  const taskType = document.getElementById('tasks-type-filter')?.value || '';
  const flag = document.getElementById('tasks-flag-filter')?.value || '';

  try {
    const p = new URLSearchParams();
    if (q) p.set('q', q);
    if (status) p.set('status', status);
    if (categoryId) p.set('categoryId', categoryId);
    if (taskType) p.set('taskType', taskType);
    if (flag) p.set('flag', flag);

    const res = await api(`/api/admin/tasks?${p.toString()}`);
    let tasks = res.items || [];

    if (tasks.length === 0) {
      tbody.innerHTML = '<tr><td colspan="7" class="empty-state">No tasks matching search criteria.</td></tr>';
      return;
    }

    tbody.innerHTML = tasks.map(t => {
      let statusColor = 'amber';
      let statusIcon = '🟢';
      if (t.status === 'completed') { statusColor = 'green'; statusIcon = '✅'; }
      else if (t.status === 'in_progress') { statusColor = 'blue'; statusIcon = '🔵'; }
      else if (t.status === 'submitted' || t.status === 'delivered') { statusColor = 'purple'; statusIcon = '🟣'; }
      else if (t.status === 'cancelled') { statusColor = 'red'; statusIcon = '🔴'; }
      else if (t.status === 'disputed') { statusColor = 'red'; statusIcon = '⚖️'; }

      const workerCell = t.worker ? `
        <div style="display:flex;align-items:center;gap:8px">
          ${avatarHtml(t.worker.name, '#6366F1', 28)}
          <div>
            <b style="color:#fff">${escapeHtml(t.worker.name)}</b>
            <small style="color:var(--muted);display:block">${escapeHtml(t.worker.email)}</small>
          </div>
        </div>
      ` : `
        <div>
          <span style="color:#FBBF24;font-weight:700;font-size:0.8rem">⚡ Open (${t.applicantCount || 0} bids)</span>
          <button class="adm-btn-act" onclick="openAssignWorkerModal(${t.id}, '${escapeHtml(t.title)}')" title="Assign Freelancer" style="font-size:0.68rem;padding:2px 6px;margin-left:4px">👤 Assign</button>
        </div>
      `;

      return `
        <tr>
          <td>
            <div style="display:flex;align-items:center;gap:10px">
              <span style="font-size:1.5rem;flex-shrink:0">${t.emoji || '💼'}</span>
              <div>
                <b style="cursor:pointer;color:#fff" onclick="openViewTaskModal(${t.id})">${escapeHtml(t.title)}</b>
                <div style="display:flex;gap:6px;align-items:center;margin-top:2px">
                  <small style="color:var(--muted)">ID #${t.id}</small>
                  <span class="adm-tag" style="font-size:0.68rem">${t.taskType === 'physical' ? '📍 Physical' : '🌐 Online'}</span>
                  ${t.isFeatured ? '<span class="adm-mini-tag yellow" onclick="toggleTaskFeatured(' + t.id + ')" style="cursor:pointer" title="Toggle Featured">⭐ Featured</span>' : ''}
                  ${t.isUrgent ? '<span class="adm-mini-tag red" onclick="toggleTaskUrgent(' + t.id + ')" style="cursor:pointer" title="Toggle Urgent">🔥 Urgent</span>' : ''}
                </div>
              </div>
            </div>
          </td>
          <td><span class="adm-tag">${escapeHtml(t.category?.name || 'General')}</span></td>
          <td>
            <div style="display:flex;align-items:center;gap:8px">
              ${avatarHtml(t.client?.name || 'Client', '#10B981', 28)}
              <div>
                <b style="color:#fff">${escapeHtml(t.client?.name || 'Admin')}</b>
                <small style="color:var(--muted);display:block">${escapeHtml(t.client?.email || 'admin@xtraearn.com')}</small>
              </div>
            </div>
          </td>
          <td>${workerCell}</td>
          <td>
            <b style="color:#10B981;font-size:0.92rem">$${Number(t.budget || 0).toFixed(2)}</b>
            <small style="color:var(--muted);display:block">⏱️ ${t.durationMinutes || 30} mins</small>
          </td>
          <td>
            <span class="adm-status-chip ${statusColor}" onclick="openTaskStatusModal(${t.id}, '${escapeHtml(t.title)}', '${t.status}')" style="cursor:pointer" title="Click to Force Status Change">
              ${statusIcon} ${t.status}
            </span>
          </td>
          <td>
            <div class="adm-action-btns">
              <button class="adm-btn-act" onclick="openViewTaskModal(${t.id})" title="View Full Dossier" style="background:#1E1B4B;border-color:#6366F1;color:#818CF8">👁️</button>
              <button class="adm-btn-act" onclick="openEditTaskModal(${t.id})" title="Edit Task">✏️</button>
              <button class="adm-btn-act" onclick="openTaskStatusModal(${t.id}, '${escapeHtml(t.title)}', '${t.status}')" title="Change Lifecycle State">🔄</button>
              ${t.status === 'in_progress' || t.status === 'submitted' ? `<button class="adm-btn-act" onclick="releaseTaskEscrow(${t.id})" title="Release Escrow Payout" style="color:#10B981;border-color:rgba(16,185,129,0.3)">💰</button>` : ''}
              ${t.status === 'open' || t.status === 'in_progress' ? `<button class="adm-btn-act" onclick="refundTask(${t.id})" title="Refund to Client" style="color:#FBBF24;border-color:rgba(245,158,11,0.3)">↩️</button>` : ''}
              <button class="adm-btn-act danger" onclick="deleteTaskRecord(${t.id})" title="Delete Task">🗑️</button>
            </div>
          </td>
        </tr>
      `;
    }).join('');

  } catch (err) {
    tbody.innerHTML = `<tr><td colspan="7" class="error-td">Error: ${err.message}</td></tr>`;
  }
}

// Tasks Search & Filter Listeners
['tasks-search-input', 'tasks-status-filter', 'tasks-cat-filter', 'tasks-type-filter', 'tasks-flag-filter'].forEach(id => {
  const el = document.getElementById(id);
  if (el) {
    el.addEventListener('input', () => {
      clearTimeout(tasksSearchTimeout);
      tasksSearchTimeout = setTimeout(loadTasksTable, 250);
    });
    el.addEventListener('change', loadTasksTable);
  }
});

/**
 * 1. Open Task Dossier Inspector Modal
 */
window.openViewTaskModal = async function(taskId) {
  const container = document.getElementById('task-view-container');
  if (!container) return;
  container.innerHTML = '<div class="loading-td" style="padding:40px;text-align:center">Loading task dossier...</div>';
  openModal('modal-task-view');

  try {
    const data = await api(`/api/admin/tasks/${taskId}`);
    const t = data.task;
    const client = data.client || {};
    const worker = data.worker;
    const fin = data.financials || {};

    const applicantRows = (data.applications || []).map(a => `
      <div class="task-applicant-row">
        <div style="display:flex;align-items:center;gap:10px">
          ${avatarHtml(a.freelancer?.name || 'Applicant', '#818CF8', 32)}
          <div>
            <b>${escapeHtml(a.freelancer?.name || 'Freelancer')}</b> <span style="color:#FBBF24">★ ${Number(a.freelancer?.rating || 5).toFixed(1)}</span>
            <small style="color:var(--muted);display:block">"${escapeHtml(a.cover_letter)}"</small>
          </div>
        </div>
        <div style="display:flex;align-items:center;gap:10px">
          <b style="color:#10B981">$${Number(a.bid_amount || t.budget).toFixed(2)}</b>
          ${t.status === 'open' ? `<button class="btn btn-green btn-sm" onclick="closeModal('modal-task-view');assignSpecificWorker(${t.id}, ${a.freelancer_id})">Award Task</button>` : `<span class="adm-status-chip ${a.status === 'accepted' ? 'green' : 'amber'}">${a.status}</span>`}
        </div>
      </div>
    `).join('');

    const deliveryRows = (data.deliveries || []).map(d => `
      <div class="task-delivery-card">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px">
          <b>Submission #${d.id}</b>
          <span class="adm-status-chip green">${d.status}</span>
        </div>
        <p style="margin:0 0 8px;color:#CBD5E1">"${escapeHtml(d.notes)}"</p>
        ${d.attachment_url ? `<p><a href="${d.attachment_url}" target="_blank" style="color:#818CF8">📎 View Deliverable Proof</a></p>` : ''}
        <small style="color:var(--muted)">Submitted on ${new Date(d.created_at).toLocaleString()}</small>
      </div>
    `).join('');

    container.innerHTML = `
      <div class="task-dossier-hero">
        <div class="task-dossier-emoji">${t.emoji || '💼'}</div>
        <div class="task-dossier-hero-info">
          <h3>
            ${escapeHtml(t.title)}
            <span class="adm-status-chip green">${t.status}</span>
            ${t.is_featured ? '<span class="adm-mini-tag yellow">⭐ Featured</span>' : ''}
            ${t.is_urgent ? '<span class="adm-mini-tag red">🔥 Urgent</span>' : ''}
          </h3>
          <p>ID #${t.id} · Category: <b>${escapeHtml(data.category?.name || 'General')}</b> · Type: <b>${t.task_type || 'online'}</b> · Created: ${new Date(t.created_at).toLocaleDateString()}</p>
        </div>
      </div>

      <!-- Parties Grid (Client + Worker) -->
      <div class="task-parties-grid">
        <div class="task-party-card">
          ${avatarHtml(client.name || 'Client', '#10B981', 40)}
          <div class="tpc-info">
            <span class="tpc-role">Client (Employer)</span>
            <b>${escapeHtml(client.name || 'Admin')}</b>
            <small>${escapeHtml(client.email || '—')} ${client.phone ? `· ${escapeHtml(client.phone)}` : ''}</small>
          </div>
        </div>

        <div class="task-party-card">
          ${worker ? avatarHtml(worker.name, '#6366F1', 40) : '<div class="adm-avatar-circle" style="background:#334155;color:#94A3B8">?</div>'}
          <div class="tpc-info">
            <span class="tpc-role">Assigned Freelancer</span>
            <b>${worker ? escapeHtml(worker.name) : '<span style="color:#FBBF24">Unassigned (Open for bids)</span>'}</b>
            <small>${worker ? `${escapeHtml(worker.email)} · ⭐ ${Number(worker.rating || 5).toFixed(1)}` : `Waiting for admin/client selection`}</small>
          </div>
        </div>
      </div>

      <!-- Escrow & Financial Box -->
      <div class="escrow-breakdown-box">
        <div class="ebb-row">
          <span>Gross Escrow Budget:</span>
          <b>$${fin.budget.toFixed(2)}</b>
        </div>
        <div class="ebb-row">
          <span>Platform Commission Fee (10%):</span>
          <b style="color:#FBBF24">$${fin.platformCommission.toFixed(2)}</b>
        </div>
        <div class="ebb-row">
          <span>Net Freelancer Payout (90%):</span>
          <b style="color:#10B981">$${fin.workerPayout.toFixed(2)}</b>
        </div>
        <div class="ebb-row total">
          <span>Vault Holding Status:</span>
          <span class="adm-status-chip ${fin.escrowStatus === 'Disbursed' ? 'green' : fin.escrowStatus === 'Refunded' ? 'red' : 'amber'}">${fin.escrowStatus}</span>
        </div>
      </div>

      <!-- Description -->
      <div style="background:rgba(15,23,42,0.6);border:1px solid rgba(255,255,255,0.06);border-radius:10px;padding:12px;margin-bottom:14px;font-size:0.82rem">
        <b style="color:#94A3B8;display:block;margin-bottom:4px;text-transform:uppercase;font-size:0.72rem">Task Requirements &amp; Description</b>
        <p style="margin:0;color:#E2E8F0;line-height:1.4">${escapeHtml(t.description || 'No description provided.')}</p>
        ${t.tags && t.tags.length ? `<div style="display:flex;gap:6px;margin-top:8px;flex-wrap:wrap">${t.tags.map(tag => `<span class="adm-tag">${escapeHtml(tag)}</span>`).join('')}</div>` : ''}
      </div>

      <!-- Dossier Tabs -->
      <div class="user-dossier-tabs">
        <button class="ud-tab-btn active" onclick="switchTaskTab('applicants')">Applicants &amp; Bids (${data.applications?.length || 0})</button>
        <button class="ud-tab-btn" onclick="switchTaskTab('deliveries')">Deliveries (${data.deliveries?.length || 0})</button>
      </div>

      <div class="ud-tab-content active" id="task-tab-applicants">
        ${applicantRows || '<p style="text-align:center;color:var(--muted);padding:14px">No freelancer bids placed yet.</p>'}
      </div>

      <div class="ud-tab-content" id="task-tab-deliveries">
        ${deliveryRows || '<p style="text-align:center;color:var(--muted);padding:14px">No work deliverable proof uploaded yet.</p>'}
      </div>

      <!-- Quick Action Controls -->
      <div class="user-dossier-ctrls" style="margin-top:14px">
        <button class="btn btn-purple" onclick="closeModal('modal-task-view');openEditTaskModal(${t.id})">✏️ Edit Details</button>
        <button class="btn btn-outline-light" onclick="closeModal('modal-task-view');openTaskStatusModal(${t.id}, '${escapeHtml(t.title)}', '${t.status}')">🔄 Force Status</button>
        <button class="btn btn-outline-light" onclick="closeModal('modal-task-view');openAssignWorkerModal(${t.id}, '${escapeHtml(t.title)}')">👤 Assign Worker</button>
        ${t.status === 'in_progress' || t.status === 'submitted' ? `<button class="btn btn-green" onclick="closeModal('modal-task-view');releaseTaskEscrow(${t.id})">💰 Release Escrow Payout</button>` : ''}
        ${t.status === 'open' || t.status === 'in_progress' ? `<button class="btn btn-outline-light" style="color:#FBBF24;border-color:rgba(245,158,11,0.4)" onclick="closeModal('modal-task-view');refundTask(${t.id})">↩️ Refund Client</button>` : ''}
        <button class="btn btn-outline-light" style="color:#F87171;border-color:rgba(239,68,68,0.4)" onclick="closeModal('modal-task-view');deleteTaskRecord(${t.id})">🗑️ Delete Task</button>
      </div>
    `;

  } catch (err) {
    container.innerHTML = `<div class="error-td" style="padding:30px;text-align:center">Error loading task dossier: ${err.message}</div>`;
  }
};

window.switchTaskTab = function(tabName) {
  document.querySelectorAll('#modal-task-view .ud-tab-btn').forEach(b => b.classList.remove('active'));
  document.querySelectorAll('#modal-task-view .ud-tab-content').forEach(c => c.classList.remove('active'));
  const btn = event.target;
  const target = document.getElementById(`task-tab-${tabName}`);
  if (btn) btn.classList.add('active');
  if (target) target.classList.add('active');
};

/**
 * 2. Force Task Status Modal Logic
 */
window.openTaskStatusModal = function(taskId, taskTitle, currentStatus) {
  document.getElementById('ts-task-id').value = taskId;
  document.getElementById('ts-modal-sub').textContent = `Task #${taskId}: "${taskTitle}" (Current: ${currentStatus})`;
  document.getElementById('ts-new-status').value = currentStatus;
  document.getElementById('ts-note').value = 'Administrative status update';
  openModal('modal-task-status');
};

document.getElementById('task-status-form')?.addEventListener('submit', async e => {
  e.preventDefault();
  const taskId = document.getElementById('ts-task-id').value;
  const status = document.getElementById('ts-new-status').value;
  const note = document.getElementById('ts-note').value.trim();

  try {
    await api(`/api/admin/tasks/${taskId}/status`, {
      method: 'POST',
      body: { status, note }
    });
    toast(`Task #${taskId} status changed to ${status.toUpperCase()}`, 'success');
    closeModal('modal-task-status');
    loadTasksTable();
    loadOverview();
  } catch (err) { toast(err.message, 'error'); }
});

/**
 * 3. Assign Worker Modal Logic
 */
window.openAssignWorkerModal = async function(taskId, taskTitle) {
  document.getElementById('ta-task-id').value = taskId;
  document.getElementById('ta-modal-sub').textContent = `Assign worker to Task #${taskId}: "${taskTitle}"`;
  const select = document.getElementById('ta-freelancer-select');
  select.innerHTML = '<option value="">Loading registered freelancers...</option>';
  openModal('modal-task-assign');

  try {
    const res = await api('/api/admin/users?role=freelancer');
    const freelancers = res.items || [];
    select.innerHTML = freelancers.map(f => `
      <option value="${f.id}">#${f.id} · ${escapeHtml(f.name)} (${escapeHtml(f.profession || 'Freelancer')}) · ⭐ ${Number(f.rating || 5).toFixed(1)}</option>
    `).join('');
  } catch (err) {
    select.innerHTML = `<option value="">Error loading freelancers</option>`;
  }
};

window.assignSpecificWorker = async function(taskId, freelancerId) {
  try {
    await api(`/api/admin/tasks/${taskId}/assign`, {
      method: 'POST',
      body: { freelancerId }
    });
    toast(`Freelancer successfully assigned to Task #${taskId}`, 'success');
    loadTasksTable();
    loadOverview();
  } catch (err) { toast(err.message, 'error'); }
};

document.getElementById('task-assign-form')?.addEventListener('submit', async e => {
  e.preventDefault();
  const taskId = document.getElementById('ta-task-id').value;
  const freelancerId = document.getElementById('ta-freelancer-select').value;
  if (!freelancerId) return toast('Please select a freelancer', 'warning');

  try {
    await api(`/api/admin/tasks/${taskId}/assign`, {
      method: 'POST',
      body: { freelancerId }
    });
    toast(`Task #${taskId} assigned to worker #${freelancerId}`, 'success');
    closeModal('modal-task-assign');
    loadTasksTable();
    loadOverview();
  } catch (err) { toast(err.message, 'error'); }
});

/**
 * 4. Toggle Featured & Urgent Flags
 */
window.toggleTaskFeatured = async function(taskId) {
  try {
    const res = await api(`/api/admin/tasks/${taskId}/featured`, { method: 'POST' });
    toast(`Task #${taskId} featured status updated`, 'info');
    loadTasksTable();
  } catch (err) { toast(err.message, 'error'); }
};

window.toggleTaskUrgent = async function(taskId) {
  try {
    const res = await api(`/api/admin/tasks/${taskId}/urgent`, { method: 'POST' });
    toast(`Task #${taskId} urgent status updated`, 'info');
    loadTasksTable();
  } catch (err) { toast(err.message, 'error'); }
};

/**
 * 5. Escrow Release & Refund Handlers
 */
window.releaseTaskEscrow = async function(taskId) {
  if (!confirm(`Are you sure you want to approve delivery and immediately disburse 90% payout to the worker?`)) return;
  try {
    await api(`/api/admin/tasks/${taskId}/release-escrow`, { method: 'POST' });
    toast(`Escrow payout successfully disbursed for Task #${taskId}`, 'success');
    loadTasksTable();
    loadOverview();
  } catch (err) { toast(err.message, 'error'); }
};

window.refundTask = async function(taskId) {
  if (!confirm(`Are you sure you want to cancel Task #${taskId} and refund 100% budget to the client's wallet?`)) return;
  try {
    await api(`/api/admin/tasks/${taskId}/refund`, { method: 'POST' });
    toast(`Task #${taskId} cancelled and budget refunded to client`, 'info');
    loadTasksTable();
    loadOverview();
  } catch (err) { toast(err.message, 'error'); }
};

/**
 * 6. Create & Edit Task Modal Logic
 */
window.openCreateTaskModal = function() {
  if (typeof closeModal === 'function') {
    closeModal('modal-global-create');
  }
  if (typeof openPostTaskModal === 'function') {
    openPostTaskModal();
  } else if (typeof window.openPostTaskModal === 'function') {
    window.openPostTaskModal();
  } else {
    // Fallback to manual editor if dynamic engine unavailable
    window.openLegacyTaskEditorModal();
  }
};

window.openLegacyTaskEditorModal = function() {
  document.getElementById('task-modal-title').textContent = 'Create New Micro Task';
  document.getElementById('task-modal-sub').textContent = 'Publish a new micro-job or task for freelancers.';
  document.getElementById('tf-task-id').value = '';
  document.getElementById('tf-emoji').value = '💼';
  document.getElementById('tf-title').value = '';
  document.getElementById('tf-desc').value = '';
  document.getElementById('tf-type').value = 'online';
  document.getElementById('tf-budget').value = '150';
  document.getElementById('tf-status').value = 'open';
  document.getElementById('tf-duration').value = '30';
  document.getElementById('tf-location').value = '';
  document.getElementById('tf-tags').value = '';
  document.getElementById('tf-featured').checked = false;
  document.getElementById('tf-urgent').checked = false;
  populateCategorySelect('tf-category');
  openModal('modal-task-editor');
};

window.openEditTaskModal = async function(taskId) {
  try {
    const res = await api(`/api/admin/tasks/${taskId}`);
    const t = res.task;
    if (!t) return toast('Task not found', 'error');

    document.getElementById('task-modal-title').textContent = `Edit Task #${t.id}`;
    document.getElementById('task-modal-sub').textContent = `Manage task requirements, category and budget.`;
    document.getElementById('tf-task-id').value = t.id;
    document.getElementById('tf-emoji').value = t.emoji || '💼';
    document.getElementById('tf-title').value = t.title;
    document.getElementById('tf-desc').value = t.description;
    document.getElementById('tf-type').value = t.task_type || t.taskType || 'online';
    document.getElementById('tf-budget').value = t.budget;
    document.getElementById('tf-status').value = t.status;
    document.getElementById('tf-duration').value = t.duration_minutes || t.durationMinutes || 30;
    document.getElementById('tf-location').value = t.location_text || '';
    document.getElementById('tf-tags').value = Array.isArray(t.tags) ? t.tags.join(', ') : (t.tags || '');
    document.getElementById('tf-featured').checked = Boolean(t.is_featured || t.isFeatured);
    document.getElementById('tf-urgent').checked = Boolean(t.is_urgent || t.isUrgent);
    populateCategorySelect('tf-category', t.category_id || t.category?.id);
    openModal('modal-task-editor');
  } catch (err) { toast(err.message, 'error'); }
};

window.deleteTaskRecord = async function(taskId) {
  if (!confirm(`Are you sure you want to permanently delete Task #${taskId}?`)) return;
  try {
    await api(`/api/admin/tasks/${taskId}`, { method: 'DELETE' });
    toast(`Task #${taskId} deleted successfully`, 'info');
    loadTasksTable();
    loadOverview();
  } catch (err) { toast(err.message, 'error'); }
};

document.getElementById('task-form')?.addEventListener('submit', async e => {
  e.preventDefault();
  const id = document.getElementById('tf-task-id').value;
  const payload = {
    emoji: document.getElementById('tf-emoji').value.trim() || '💼',
    title: document.getElementById('tf-title').value.trim(),
    description: document.getElementById('tf-desc').value.trim(),
    category_id: Number(document.getElementById('tf-category').value),
    task_type: document.getElementById('tf-type').value,
    budget: Number(document.getElementById('tf-budget').value),
    status: document.getElementById('tf-status').value,
    duration_minutes: Number(document.getElementById('tf-duration').value),
    location_text: document.getElementById('tf-location').value.trim(),
    tags: document.getElementById('tf-tags').value.trim(),
    is_featured: document.getElementById('tf-featured').checked ? 1 : 0,
    is_urgent: document.getElementById('tf-urgent').checked ? 1 : 0
  };

  try {
    if (id) {
      await api(`/api/admin/tasks/${id}`, { method: 'POST', body: payload });
      toast('Task updated successfully', 'success');
    } else {
      await api('/api/admin/tasks', { method: 'POST', body: payload });
      toast('New task created successfully', 'success');
    }
    closeModal('modal-task-editor');
    loadTasksTable();
    loadOverview();
  } catch (err) { toast(err.message, 'error'); }
});


/* ---------- 5. CATEGORIES CMS ---------- */
async function loadCategoriesCache() {
  try {
    const res = await api('/api/categories');
    currentCategories = res.categories || res.items || (Array.isArray(res) ? res : []);
    populateCategorySelect('tasks-cat-filter', null, true);
  } catch (err) { console.error(err); }
}

function populateCategorySelect(selectId, selectedId = null, includeAll = false) {
  const sel = document.getElementById(selectId);
  if (!sel) return;
  const allOpt = includeAll ? '<option value="">All Categories</option>' : '';
  sel.innerHTML = allOpt + currentCategories.map(c => `<option value="${c.id}" ${c.id === Number(selectedId) ? 'selected' : ''}>${c.icon} ${escapeHtml(c.name)}</option>`).join('');
}

async function loadCategoriesGrid() {
  const grid = document.getElementById('categories-grid-body');
  if (!grid) return;
  grid.innerHTML = '<div class="loading-td">Loading categories...</div>';

  try {
    const res = await api('/api/admin/categories');
    const cats = res.items || [];
    grid.innerHTML = cats.map(c => `
      <div class="adm-cat-card" style="--cat-accent:${c.color || '#10B981'}">
        <div class="cat-top">
          <span class="cat-emoji" style="background:${c.color || '#10B981'}22">${c.icon || '📁'}</span>
          <div class="cat-actions">
            <button class="adm-btn-act" onclick="openEditCategoryModal(${c.id})">✏️</button>
            <button class="adm-btn-act danger" onclick="deleteCategoryRecord(${c.id})">🗑️</button>
          </div>
        </div>
        <h4>${escapeHtml(c.name)}</h4>
        <small class="cat-slug">/${c.slug}</small>
        <div class="cat-count"><b>${c.task_count || 0}</b> active tasks</div>
      </div>
    `).join('');
  } catch (err) { grid.innerHTML = `<div class="error-td">${err.message}</div>`; }
}

window.openCreateCategoryModal = function() {
  closeModal('modal-global-create');
  document.getElementById('cat-modal-title').textContent = 'Add New Category';
  document.getElementById('cf-id').value = '';
  document.getElementById('cf-name').value = '';
  document.getElementById('cf-icon').value = '🎨';
  document.getElementById('cf-color').value = '#10B981';
  document.getElementById('cf-desc').value = '';
  openModal('modal-category-editor');
};

window.openEditCategoryModal = function(catId) {
  const c = currentCategories.find(x => x.id === catId);
  if (!c) return toast('Category not found', 'error');
  document.getElementById('cat-modal-title').textContent = `Edit: ${c.name}`;
  document.getElementById('cf-id').value = c.id;
  document.getElementById('cf-name').value = c.name;
  document.getElementById('cf-icon').value = c.icon;
  document.getElementById('cf-color').value = c.color || '#10B981';
  document.getElementById('cf-desc').value = c.description || '';
  openModal('modal-category-editor');
};

window.deleteCategoryRecord = async function(catId) {
  if (!confirm('Are you sure you want to delete this category?')) return;
  try {
    await api(`/api/admin/categories/${catId}`, { method: 'DELETE' });
    toast('Category deleted', 'info');
    await loadCategoriesCache();
    loadCategoriesGrid();
  } catch (err) { toast(err.message, 'error'); }
};

document.getElementById('cat-form')?.addEventListener('submit', async e => {
  e.preventDefault();
  const id = document.getElementById('cf-id').value;
  const payload = {
    name: document.getElementById('cf-name').value.trim(),
    icon: document.getElementById('cf-icon').value.trim(),
    color: document.getElementById('cf-color').value,
    description: document.getElementById('cf-desc').value.trim()
  };

  try {
    if (id) {
      await api(`/api/admin/categories/${id}`, { method: 'POST', body: payload });
      toast('Category updated', 'success');
    } else {
      await api('/api/admin/categories', { method: 'POST', body: payload });
      toast('Category created', 'success');
    }
    closeModal('modal-category-editor');
    await loadCategoriesCache();
    loadCategoriesGrid();
  } catch (err) { toast(err.message, 'error'); }
});

/* ---------- 6. TRANSACTIONS & FINANCIAL LEDGER SUITE ---------- */
let txSearchTimeout = null;

async function loadTransactionsTable() {
  const tbody = document.getElementById('transactions-table-body');
  if (!tbody) return;
  tbody.innerHTML = '<tr><td colspan="7" class="loading-td">Loading financial ledger...</td></tr>';

  const q = document.getElementById('tx-search-input')?.value || '';
  const type = document.getElementById('tx-type-filter')?.value || '';
  const method = document.getElementById('tx-method-filter')?.value || '';

  try {
    const res = await api(`/api/admin/transactions?q=${encodeURIComponent(q)}&type=${encodeURIComponent(type)}&method=${encodeURIComponent(method)}`);
    const items = res.items || [];
    const met = res.metrics || {};

    // Update KPI Metric Strip
    if (document.getElementById('tx-kpi-volume')) {
      document.getElementById('tx-kpi-volume').textContent = `$${Number(met.totalVolume || 0).toFixed(2)}`;
      document.getElementById('tx-kpi-deposits').textContent = `$${Number(met.totalDeposits || 0).toFixed(2)}`;
      document.getElementById('tx-kpi-payouts').textContent = `$${Number(met.totalPayouts || 0).toFixed(2)}`;
      document.getElementById('tx-kpi-commission').textContent = `$${Number(met.totalCommission || 0).toFixed(2)}`;
      document.getElementById('tx-kpi-refunds').textContent = `$${Number(met.totalRefunds || 0).toFixed(2)}`;
    }

    if (items.length === 0) {
      tbody.innerHTML = '<tr><td colspan="7" class="empty-state">No financial transactions matching filter criteria.</td></tr>';
      return;
    }

    tbody.innerHTML = items.map(tx => {
      const isCredit = ['deposit', 'admin_credit', 'task_payout', 'escrow_refund'].includes(tx.type);
      const isNegative = ['admin_deduct', 'withdrawal', 'escrow_hold'].includes(tx.type);
      const sign = isNegative ? '-' : '+';
      const amtColor = isNegative ? '#F87171' : '#34D399';

      let typeBadgeClass = 'green';
      let typeLabel = tx.type.replace(/_/g, ' ').toUpperCase();
      if (tx.type === 'deposit') typeBadgeClass = 'green';
      else if (tx.type === 'task_payout' || tx.type === 'withdrawal') typeBadgeClass = 'blue';
      else if (tx.type === 'escrow_hold') typeBadgeClass = 'amber';
      else if (tx.type === 'escrow_refund' || tx.type === 'transaction_reversal') typeBadgeClass = 'red';
      else if (tx.type === 'admin_credit' || tx.type === 'admin_deduct') typeBadgeClass = 'purple';

      const user = tx.user || { name: 'Platform User', email: '—', role: 'user' };

      return `
        <tr style="${tx.is_reversed ? 'opacity:0.6;background:rgba(239,68,68,0.03)' : ''}">
          <td>
            <div style="display:flex;align-items:center;gap:8px">
              <span class="adm-tag" style="font-family:monospace;font-weight:700">#TXN-${String(tx.id).padStart(5, '0')}</span>
              <span class="adm-status-chip ${typeBadgeClass}" style="font-size:0.68rem">${typeLabel}</span>
            </div>
            <small style="color:var(--muted);display:block;margin-top:3px">${new Date(tx.created_at).toLocaleString()}</small>
          </td>
          <td>
            <div style="display:flex;align-items:center;gap:8px">
              ${avatarHtml(user.name, '#6366F1', 28)}
              <div>
                <b style="color:#fff">${escapeHtml(user.name)}</b>
                <small style="color:var(--muted);display:block">${escapeHtml(user.email)} ${user.role ? `· <span class="adm-tag" style="font-size:0.62rem">${user.role}</span>` : ''}</small>
              </div>
            </div>
          </td>
          <td>
            <span style="font-size:0.84rem;color:#E2E8F0;font-weight:600">${escapeHtml(tx.method || 'Escrow Vault')}</span>
          </td>
          <td>
            <b style="color:${amtColor};font-size:0.96rem;font-family:monospace">${sign}$${Number(tx.amount || 0).toFixed(2)}</b>
          </td>
          <td>
            <span style="font-size:0.8rem;color:#CBD5E1">${escapeHtml(tx.taskTitle ? `Task: ${tx.taskTitle}` : (tx.note || 'System transfer'))}</span>
          </td>
          <td>
            ${tx.is_reversed ?
              '<span class="adm-status-chip red" style="font-size:0.7rem">🔴 REVERSED</span>' :
              '<span class="adm-status-chip green" style="font-size:0.7rem">✅ SETTLED</span>'}
          </td>
          <td>
            <div class="adm-action-btns">
              <button class="adm-btn-act" onclick="openInvoiceModal('transaction', ${tx.id})" title="View & Print Official PDF Receipt" style="background:#1E1B4B;border-color:#6366F1;color:#818CF8">📄</button>
              <button class="adm-btn-act" onclick="downloadInvoicePdf('transaction', ${tx.id})" title="Download Official PDF" style="color:#34D399;border-color:rgba(52,211,153,0.3)">⬇️</button>
              ${!tx.is_reversed ? `<button class="adm-btn-act" onclick="openReverseTxModal(${tx.id}, ${tx.amount}, '${escapeHtml(user.name)}')" title="Reverse Transaction" style="color:#F87171;border-color:rgba(239,68,68,0.3)">↩️</button>` : ''}
              <button class="adm-btn-act" onclick="printTxReceipt(${tx.id})" title="Print Digital Receipt">🖨️</button>
              <button class="adm-btn-act danger" onclick="deleteTransactionRecord(${tx.id})" title="Delete Record">🗑️</button>
            </div>
          </td>
        </tr>
      `;
    }).join('');

  } catch (err) {
    tbody.innerHTML = `<tr><td colspan="7" class="error-td">Error loading ledger: ${err.message}</td></tr>`;
  }
}

// Transaction Search & Filter Listeners
['tx-search-input', 'tx-type-filter', 'tx-method-filter'].forEach(id => {
  const el = document.getElementById(id);
  if (el) {
    el.addEventListener('input', () => {
      clearTimeout(txSearchTimeout);
      txSearchTimeout = setTimeout(loadTransactionsTable, 250);
    });
    el.addEventListener('change', loadTransactionsTable);
  }
});

/**
 * 1. Open Transaction Digital Receipt & Dossier Modal
 */
window.openViewTransactionModal = async function(txId) {
  const container = document.getElementById('tx-view-container');
  if (!container) return;
  container.innerHTML = '<div class="loading-td" style="padding:40px;text-align:center">Loading transaction receipt...</div>';
  openModal('modal-tx-view');

  try {
    const data = await api(`/api/admin/transactions/${txId}`);
    const tx = data.transaction || {};
    const u = data.user || {};
    const task = data.task;

    const isNegative = ['admin_deduct', 'withdrawal', 'escrow_hold'].includes(tx.type);
    const sign = isNegative ? '-' : '+';
    const heroClass = isNegative ? 'negative' : 'positive';

    container.innerHTML = `
      <div class="tx-receipt-card" id="printable-receipt-${tx.id}">
        <div class="tx-receipt-top">
          <div class="tx-receipt-brand">
            <b>Xtra<span>Earn</span> Financial Services</b>
            <small>Official Escrow &amp; Payment Settlement Receipt</small>
          </div>
          <div style="text-align:right">
            <span class="adm-tag" style="font-family:monospace;font-size:0.85rem">#TXN-${String(tx.id).padStart(6, '0')}</span>
            <small style="color:var(--muted);display:block;margin-top:4px">${new Date(tx.created_at).toLocaleString()}</small>
          </div>
        </div>

        <div class="tx-amount-hero">
          <div class="tah-label">Settled Transaction Value</div>
          <div class="tah-value ${heroClass}">${sign}$${Number(tx.amount || 0).toFixed(2)}</div>
          <div>
            ${tx.is_reversed ?
              '<span class="adm-status-chip red">🔴 REVERSED TRANSACTION</span>' :
              '<span class="adm-status-chip green">✅ SETTLED &amp; VERIFIED IN VAULT</span>'}
          </div>
        </div>

        <div class="tx-details-list">
          <div class="tx-detail-item">
            <label>Account Holder</label>
            <b>${escapeHtml(u.name || 'Platform User')}</b>
            <small style="color:var(--muted);display:block">${escapeHtml(u.email || '—')} (${u.role || 'user'})</small>
          </div>

          <div class="tx-detail-item">
            <label>Payment Channel</label>
            <b>${escapeHtml(tx.method || 'Escrow Vault')}</b>
            <small style="color:var(--muted);display:block">Type: ${tx.type.toUpperCase()}</small>
          </div>

          <div class="tx-detail-item">
            <label>Wallet Balance</label>
            <b style="color:#10B981">$${Number(u.wallet_balance || 0).toFixed(2)}</b>
            <small style="color:var(--muted);display:block">Current Available Funds</small>
          </div>

          <div class="tx-detail-item">
            <label>Associated Task</label>
            <b>${task ? escapeHtml(task.title) : 'Direct Account Transfer'}</b>
            <small style="color:var(--muted);display:block">${task ? `Task #${task.id} · Budget $${task.budget}` : 'No task attached'}</small>
          </div>
        </div>

        <div style="background:#1E293B;border:1px solid rgba(255,255,255,0.05);border-radius:10px;padding:12px;margin-bottom:16px;font-size:0.82rem">
          <label style="color:#94A3B8;display:block;font-size:0.72rem;text-transform:uppercase;margin-bottom:4px">Audit Note &amp; Reference</label>
          <p style="margin:0;color:#F1F5F9;font-style:italic">"${escapeHtml(tx.note || 'Official platform transaction')}"</p>
        </div>

        <div class="tx-barcode-strip">
          ||||| | |||| ||| ||||||| | ||||| || |||||| | |||| |||||
          <div style="margin-top:4px">SECURE-LEDGER-HASH: ${Math.random().toString(36).substring(2, 15).toUpperCase()}</div>
        </div>
      </div>

      <div class="user-dossier-ctrls" style="margin-top:16px">
        <button class="btn btn-green" onclick="downloadInvoicePdf('transaction', ${tx.id})">⬇️ Download PDF</button>
        <button class="btn btn-purple" onclick="printTxReceipt(${tx.id})">🖨️ Print Receipt</button>
        ${!tx.is_reversed ? `<button class="btn btn-outline-light" style="color:#F87171;border-color:rgba(239,68,68,0.4)" onclick="closeModal('modal-tx-view');openReverseTxModal(${tx.id}, ${tx.amount}, '${escapeHtml(u.name)}')">↩️ Reverse Transaction</button>` : ''}
        <button class="btn btn-outline-light" onclick="closeModal('modal-tx-view')">Close</button>
      </div>
    `;
  } catch (err) {
    container.innerHTML = `<div class="error-td" style="padding:30px;text-align:center">Error: ${err.message}</div>`;
  }
};

/**
 * 2. Record Manual Transaction Modal Logic
 */
window.openCreateTxModal = async function() {
  const select = document.getElementById('mtf-user');
  select.innerHTML = '<option value="">Loading users...</option>';
  document.getElementById('mtf-amount').value = '';
  document.getElementById('mtf-task-id').value = '';
  document.getElementById('mtf-note').value = '';
  openModal('modal-tx-create');

  try {
    const res = await api('/api/admin/users');
    const users = res.items || [];
    select.innerHTML = users.map(u => `
      <option value="${u.id}">#${u.id} · ${escapeHtml(u.name)} (${escapeHtml(u.email)}) · Balance: $${Number(u.wallet_balance || 0).toFixed(2)}</option>
    `).join('');
  } catch (err) {
    select.innerHTML = '<option value="">Error loading users</option>';
  }
};

document.getElementById('tx-create-form')?.addEventListener('submit', async e => {
  e.preventDefault();
  const payload = {
    userId: Number(document.getElementById('mtf-user').value),
    type: document.getElementById('mtf-type').value,
    method: document.getElementById('mtf-method').value,
    amount: Number(document.getElementById('mtf-amount').value),
    taskId: document.getElementById('mtf-task-id').value ? Number(document.getElementById('mtf-task-id').value) : null,
    note: document.getElementById('mtf-note').value.trim()
  };

  if (!payload.userId) return toast('Please select a target user account', 'warning');
  if (!payload.amount || payload.amount <= 0) return toast('Please enter a valid positive amount', 'warning');

  try {
    await api('/api/admin/transactions', { method: 'POST', body: payload });
    toast('Transaction recorded and wallet updated successfully', 'success');
    closeModal('modal-tx-create');
    loadTransactionsTable();
    loadOverview();
  } catch (err) { toast(err.message, 'error'); }
});

/**
 * 3. Transaction Reversal Modal Logic
 */
window.openReverseTxModal = function(txId, amount, userName) {
  document.getElementById('tr-tx-id').value = txId;
  document.getElementById('tr-modal-sub').textContent = `Reversing Tx #${txId} of $${Number(amount).toFixed(2)} for ${userName}`;
  document.getElementById('tr-note').value = `Administrative reversal of Tx #${txId}`;
  openModal('modal-tx-reverse');
};

document.getElementById('tx-reverse-form')?.addEventListener('submit', async e => {
  e.preventDefault();
  const txId = document.getElementById('tr-tx-id').value;
  const note = document.getElementById('tr-note').value.trim();

  try {
    await api(`/api/admin/transactions/${txId}/reverse`, {
      method: 'POST',
      body: { note }
    });
    toast(`Transaction #${txId} reversed successfully`, 'info');
    closeModal('modal-tx-reverse');
    loadTransactionsTable();
    loadOverview();
  } catch (err) { toast(err.message, 'error'); }
});

/**
 * 4. Print Digital Receipt
 */
window.printTxReceipt = function(txId) {
  const elem = document.getElementById(`printable-receipt-${txId}`) || document.getElementById('tx-view-container');
  if (!elem) return window.print();

  const printWin = window.open('', '_blank', 'width=750,height=600');
  printWin.document.write(`
    <html>
      <head>
        <title>Transaction Receipt #${txId} - XtraEarn</title>
        <style>
          body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; padding: 24px; color: #111; }
          .tx-receipt-card { border: 2px solid #333; border-radius: 8px; padding: 24px; max-width: 600px; margin: 0 auto; }
          .tx-receipt-top { display: flex; justify-content: space-between; border-bottom: 1px dashed #666; padding-bottom: 12px; margin-bottom: 16px; }
          .tx-amount-hero { text-align: center; padding: 16px; background: #f4f4f5; border-radius: 8px; margin-bottom: 16px; }
          .tah-value { font-size: 28px; font-weight: bold; }
          .tx-details-list { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 16px; font-size: 14px; }
          .tx-detail-item { background: #fafafa; border: 1px solid #ddd; padding: 8px; border-radius: 6px; }
          .tx-detail-item label { font-size: 11px; color: #666; text-transform: uppercase; display: block; }
          .tx-barcode-strip { text-align: center; border-top: 1px dashed #666; padding-top: 12px; font-family: monospace; font-size: 12px; letter-spacing: 2px; }
          .adm-status-chip { display: inline-block; padding: 3px 8px; border-radius: 4px; font-size: 11px; font-weight: bold; background: #e0f2fe; color: #0284c7; }
          .adm-tag { display: inline-block; padding: 2px 6px; border-radius: 4px; background: #f3f4f6; font-size: 12px; }
        </style>
      </head>
      <body>
        ${elem.outerHTML}
        <script>window.onload = function() { window.print(); window.close(); }<\/script>
      </body>
    </html>
  `);
  printWin.document.close();
};

/**
 * 5. Delete Transaction Record
 */
window.deleteTransactionRecord = async function(txId) {
  if (!confirm(`Are you sure you want to permanently delete Transaction #${txId} from the ledger?`)) return;
  try {
    await api(`/api/admin/transactions/${txId}`, { method: 'DELETE' });
    toast(`Transaction #${txId} deleted`, 'info');
    loadTransactionsTable();
    loadOverview();
  } catch (err) { toast(err.message, 'error'); }
};


