/* ---------- 9. BULK DATA IMPORT & EXPORT ---------- */
window.exportEntityData = function(entity, format) {
  const url = `/api/admin/export/${entity}?format=${format}`;
  // Use invisible iframe or direct window trigger
  const a = document.createElement('a');
  a.href = url;
  a.download = `${entity}_export.${format}`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  toast(`Exporting ${entity} (${format.toUpperCase()})...`, 'info');
};

function setupImportExport() {
  const dropzone = document.getElementById('import-dropzone');
  const fileInput = document.getElementById('import-file-input');
  if (!dropzone || !fileInput) return;

  dropzone.addEventListener('click', () => fileInput.click());
  dropzone.addEventListener('dragover', e => { e.preventDefault(); dropzone.classList.add('dragover'); });
  dropzone.addEventListener('dragleave', () => dropzone.classList.remove('dragover'));
  dropzone.addEventListener('drop', e => {
    e.preventDefault();
    dropzone.classList.remove('dragover');
    if (e.dataTransfer.files.length) handleFileImport(e.dataTransfer.files[0]);
  });

  fileInput.addEventListener('change', e => {
    if (e.target.files.length) handleFileImport(e.target.files[0]);
  });

  document.getElementById('btn-commit-import')?.addEventListener('click', async () => {
    if (!pendingImportData) return;
    const entity = document.getElementById('import-entity-select').value;
    try {
      const res = await api(`/api/admin/import/${entity}`, { method: 'POST', body: { items: pendingImportData } });
      toast(`✅ Batch import finished: ${res.imported} imported, ${res.skipped} skipped.`, 'success');
      document.getElementById('import-preview-area').style.display = 'none';
      pendingImportData = null;
      loadOverview();
    } catch (err) { toast(err.message, 'error'); }
  });
}

function handleFileImport(file) {
  const reader = new FileReader();
  reader.onload = e => {
    try {
      const content = e.target.result;
      let parsed = [];
      if (file.name.endsWith('.json')) {
        parsed = JSON.parse(content);
        if (!Array.isArray(parsed)) parsed = [parsed];
      } else {
        // Simple CSV parser
        const lines = content.split('\n').map(l => l.trim()).filter(Boolean);
        const headers = lines[0].split(',').map(h => h.replace(/^["']|["']$/g, '').trim());
        for (let i = 1; i < lines.length; i++) {
          const vals = lines[i].split(',').map(v => v.replace(/^["']|["']$/g, '').trim());
          const obj = {};
          headers.forEach((h, idx) => { obj[h] = vals[idx] || ''; });
          parsed.push(obj);
        }
      }

      pendingImportData = parsed;
      document.getElementById('import-preview-area').style.display = 'block';
      document.getElementById('import-preview-count').textContent = `${parsed.length} records detected`;
      document.getElementById('import-preview-json').textContent = JSON.stringify(parsed.slice(0, 3), null, 2) + (parsed.length > 3 ? '\n... and more' : '');
      toast(`File parsed: ${parsed.length} items ready for import.`, 'info');
    } catch (err) { toast(`File parse error: ${err.message}`, 'error'); }
  };
  reader.readAsText(file);
}

/* ---------- 10. GLOBAL CONTROLS & SHORTCUTS ---------- */
function setupGlobalControls() {
  // Quick Create Modal
  document.getElementById('btn-global-create')?.addEventListener('click', () => {
    openModal('modal-global-create');
  });

  // Quick Access Dropdown
  const qaBtn = document.getElementById('btn-quick-access');
  const qaMenu = document.getElementById('quick-access-menu');
  if (qaBtn && qaMenu) {
    qaBtn.addEventListener('click', e => {
      e.stopPropagation();
      qaMenu.classList.toggle('open');
    });
    document.addEventListener('click', () => qaMenu.classList.remove('open'));
  }

  // Quick Export button on top
  document.getElementById('btn-quick-export')?.addEventListener('click', () => {
    exportEntityData('users', 'csv');
  });

  // Support ticket button
  document.getElementById('btn-create-ticket')?.addEventListener('click', () => {
    toast('Support ticket dispatched to system operators.', 'info');
  });

  // Live search inputs
  const uSearch = document.getElementById('users-search-input');
  if (uSearch) {
    uSearch.addEventListener('input', () => {
      clearTimeout(usersSearchTimeout);
      usersSearchTimeout = setTimeout(loadUsersTable, 250);
    });
  }
  document.getElementById('users-role-filter')?.addEventListener('change', loadUsersTable);
  document.getElementById('users-verified-filter')?.addEventListener('change', loadUsersTable);

  const tSearch = document.getElementById('tasks-search-input');
  if (tSearch) {
    tSearch.addEventListener('input', () => {
      clearTimeout(usersSearchTimeout);
      usersSearchTimeout = setTimeout(loadTasksTable, 250);
    });
  }
  document.getElementById('tasks-status-filter')?.addEventListener('change', loadTasksTable);
  document.getElementById('tasks-cat-filter')?.addEventListener('change', loadTasksTable);

  // Keyboard shortcut Ctrl+K
  document.addEventListener('keydown', e => {
    if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') {
      e.preventDefault();
      const s = document.getElementById('adm-global-search');
      if (s) { s.focus(); s.select(); }
    }
    if (e.key === 'Escape') {
      document.querySelectorAll('.modal-overlay.open').forEach(m => m.classList.remove('open'));
    }
  });

  // Global search input handling
  const gSearch = document.getElementById('adm-global-search');
  if (gSearch) {
    gSearch.addEventListener('keydown', e => {
      if (e.key === 'Enter') {
        const val = gSearch.value.trim();
        if (val) {
          switchView('tasks');
          const ts = document.getElementById('tasks-search-input');
          if (ts) { ts.value = val; loadTasksTable(); }
        }
      }
    });
  }

  // Topbar Dropdown Toggles
  setupDropdownToggle('btn-lang-toggle', 'lang-dropdown-menu');
  setupDropdownToggle('btn-notif-bell', 'notif-dropdown-menu');
  setupDropdownToggle('btn-msg-icon', 'msg-dropdown-menu');
  setupDropdownToggle('adm-user-pill', 'user-dropdown-menu');

  // Language switch items
  document.querySelectorAll('.lang-opt').forEach(opt => {
    opt.addEventListener('click', e => {
      e.preventDefault();
      const lang = opt.dataset.lang;
      document.getElementById('current-lang-text').textContent = `🌐 ${lang}`;
      document.getElementById('lang-dropdown-menu')?.classList.remove('open');
      toast(`Language switched to ${lang}`, 'info');
    });
  });

  // Mark all notifications read
  document.getElementById('btn-mark-notifs-read')?.addEventListener('click', () => {
    document.querySelectorAll('.adm-badge-count').forEach(b => { b.style.display = 'none'; });
    toast('All notifications marked as read', 'success');
  });

  // Dropdown logout
  document.getElementById('btn-dropdown-logout')?.addEventListener('click', e => {
    e.preventDefault();
    Auth.logout();
  });

  // Theme toggle
  document.getElementById('btn-theme-toggle')?.addEventListener('click', () => {
    toast('Dark Mode is the optimized enterprise theme for XtraEarn.', 'info');
  });

  // Save platform settings button
  document.getElementById('btn-save-settings')?.addEventListener('click', savePlatformSettings);
}

function setupDropdownToggle(btnId, menuId) {
  const btn = document.getElementById(btnId);
  const menu = document.getElementById(menuId);
  if (!btn || !menu) return;

  btn.addEventListener('click', e => {
    e.stopPropagation();
    // Close other dropdowns
    document.querySelectorAll('.adm-dropdown-menu.open').forEach(m => {
      if (m !== menu) m.classList.remove('open');
    });
    menu.classList.toggle('open');
  });
  document.addEventListener('click', () => menu.classList.remove('open'));
}

