async function loadReviewsTable() {
  const tbody = document.getElementById('reviews-table-body');
  if (!tbody) return;
  tbody.innerHTML = '<tr><td colspan="7" class="loading-td">Loading reviews...</td></tr>';

  try {
    const res = await api('/api/admin/reviews');
    const items = res.items || [];
    if (items.length === 0) {
      tbody.innerHTML = '<tr><td colspan="7" class="empty-state">No reviews posted yet.</td></tr>';
      return;
    }

    tbody.innerHTML = items.map(r => `
      <tr>
        <td><b>${escapeHtml(r.reviewer?.name || 'Client')}</b></td>
        <td><b>${escapeHtml(r.reviewee?.name || 'Freelancer')}</b> <small style="color:var(--muted)">(${r.reviewee?.role || 'worker'})</small></td>
        <td>${escapeHtml(r.task?.title || 'Micro Task')}</td>
        <td><span style="color:#FBBF24">★ ${r.rating}.0</span></td>
        <td>"${escapeHtml(r.comment || 'Great work completed.')}"</td>
        <td style="color:var(--muted)">${new Date(r.created_at).toLocaleDateString()}</td>
        <td>
          <button class="adm-btn-act danger" onclick="deleteReviewRecord(${r.id})" title="Delete Review">🗑️</button>
        </td>
      </tr>
    `).join('');
  } catch (err) { tbody.innerHTML = `<tr><td colspan="7" class="error-td">${err.message}</td></tr>`; }
}

