async function loadWithdrawalsTable() {
  const tbody = document.getElementById('withdrawals-table-body');
  if (!tbody) return;
  tbody.innerHTML = '<tr><td colspan="7" class="loading-td">Loading withdrawal requests...</td></tr>';

  try {
    const res = await api('/api/admin/withdrawals');
    const items = res.items || [];
    if (items.length === 0) {
      tbody.innerHTML = '<tr><td colspan="7" class="empty-state">No pending withdrawal requests.</td></tr>';
      return;
    }

    tbody.innerHTML = items.map(w => {
      const statusPill = w.status === 'approved' ? 'green' : w.status === 'rejected' ? 'red' : 'amber';
      return `
        <tr>
          <td><b>#WDR-${w.id}</b></td>
          <td>
            <b>${escapeHtml(w.user_name)}</b>
            <small style="color:var(--muted);display:block">${escapeHtml(w.user_email)}</small>
          </td>
          <td><span class="adm-tag">${w.method.toUpperCase()}</span></td>
          <td><code>${escapeHtml(w.account_number)}</code></td>
          <td><b style="color:#10B981">$${Number(w.amount).toFixed(2)}</b></td>
          <td><span class="adm-status-chip ${statusPill}">${w.status}</span></td>
          <td>
            ${w.status === 'pending' ? `
              <div class="adm-action-btns">
                <button class="btn btn-green btn-sm" onclick="approveWithdrawal(${w.id})">✓ Approve</button>
                <button class="btn btn-outline-light btn-sm" onclick="rejectWithdrawal(${w.id})">✕ Reject</button>
              </div>
            ` : `<span style="color:var(--muted)">Processed</span>`}
          </td>
        </tr>
      `;
    }).join('');
  } catch (err) { tbody.innerHTML = `<tr><td colspan="7" class="error-td">${err.message}</td></tr>`; }
}

