  document.getElementById('cpn-form-fixed').value = '100';
  document.getElementById('cpn-form-max').value = '250';
  document.getElementById('cpn-form-min-spend').value = '300';
  document.getElementById('cpn-form-audience').value = 'all';
  document.getElementById('cpn-form-category').value = 'all';
  document.getElementById('cpn-form-limit-global').value = '500';
  document.getElementById('cpn-form-limit-user').value = '1';
