  document.getElementById('cpn-form-from').value = new Date().toISOString().slice(0, 10);
  document.getElementById('cpn-form-until').value = '2026-12-31';
  document.getElementById('cpn-form-status').value = 'active';

  openModal('modal-coupon-create');
