// Open Edit Coupon Modal
window.openEditCouponModal = async function(id) {
  try {
    const c = await api(`/api/admin/coupons/${id}`);
    document.getElementById('cpn-edit-id').value = c.id;
    document.getElementById('modal-coupon-title').textContent = `Edit Campaign: ${c.code}`;
    document.getElementById('cpn-form-submit-btn').textContent = 'Save Changes';

    document.getElementById('cpn-form-code').value = c.code;
    document.getElementById('cpn-form-code').disabled = true;
    document.getElementById('cpn-form-title').value = c.title || '';
    document.getElementById('cpn-form-desc').value = c.description || '';
    document.getElementById('cpn-form-type').value = c.type || 'percentage';
    handleCouponTypeChange(c.type || 'percentage');
    document.getElementById('cpn-form-pct').value = c.discountPct || 20;
    document.getElementById('cpn-form-fixed').value = c.fixedDiscount || 100;
    document.getElementById('cpn-form-max').value = c.maxDiscount || 250;
    document.getElementById('cpn-form-min-spend').value = c.minSpend || 0;
    document.getElementById('cpn-form-audience').value = c.targetAudience || 'all';
    document.getElementById('cpn-form-category').value = c.categoryScope || 'all';
    document.getElementById('cpn-form-limit-global').value = c.usageLimitGlobal || 500;
    document.getElementById('cpn-form-limit-user').value = c.usageLimitPerUser || 1;
    document.getElementById('cpn-form-budget-cap').value = c.budgetCap || 100000;
    document.getElementById('cpn-form-from').value = c.validFrom || new Date().toISOString().slice(0, 10);
    document.getElementById('cpn-form-until').value = c.validUntil || '2026-12-31';
    document.getElementById('cpn-form-status').value = c.status || 'active';

    openModal('modal-coupon-create');
  } catch (err) { toast(err.message, 'error'); }
};

// Handle Save Coupon (Create or Update)
window.handleSaveCoupon = async function(e) {
  e.preventDefault();
  const editId = document.getElementById('cpn-edit-id').value;
  const payload = {
    code: document.getElementById('cpn-form-code').value.trim().toUpperCase(),
    title: document.getElementById('cpn-form-title').value.trim(),
    description: document.getElementById('cpn-form-desc').value.trim(),
    type: document.getElementById('cpn-form-type').value,
    discountPct: Number(document.getElementById('cpn-form-pct').value),
    fixedDiscount: Number(document.getElementById('cpn-form-fixed').value),
    maxDiscount: Number(document.getElementById('cpn-form-max').value),
    minSpend: Number(document.getElementById('cpn-form-min-spend').value),
    targetAudience: document.getElementById('cpn-form-audience').value,
    categoryScope: document.getElementById('cpn-form-category').value,
    usageLimitGlobal: Number(document.getElementById('cpn-form-limit-global').value),
    usageLimitPerUser: Number(document.getElementById('cpn-form-limit-user').value),
    budgetCap: Number(document.getElementById('cpn-form-budget-cap').value),
    validFrom: document.getElementById('cpn-form-from').value,
    validUntil: document.getElementById('cpn-form-until').value,
    status: document.getElementById('cpn-form-status').value
  };

  try {
    if (editId) {
      await api(`/api/admin/coupons/${editId}`, { method: 'PATCH', body: payload });
      toast(`Campaign '${payload.code}' updated successfully!`, 'success');
    } else {
      await api('/api/admin/coupons', { method: 'POST', body: payload });
      toast(`Campaign '${payload.code}' launched successfully!`, 'success');
    }
    closeModal('modal-coupon-create');
    loadCouponsDashboard();
  } catch (err) { toast(err.message, 'error'); }
};

// Toggle Status (Pause / Activate)
window.toggleCouponStatus = async function(id) {
  try {
    const c = await api(`/api/admin/coupons/${id}`);
    const nextStatus = c.status === 'active' ? 'paused' : 'active';
    await api(`/api/admin/coupons/${id}`, { method: 'PATCH', body: { status: nextStatus } });
    toast(`Campaign '${c.code}' is now ${nextStatus.toUpperCase()}`, 'info');
    loadCouponsDashboard();
  } catch (err) { toast(err.message, 'error'); }
};

// Delete Coupon Record
window.deleteCouponRecord = async function(id) {
  if (!confirm('Permanently delete this promotional campaign? This cannot be undone.')) return;
  try {
    await api(`/api/admin/coupons/${id}`, { method: 'DELETE' });
    toast('Campaign permanently deleted.', 'info');
    loadCouponsDashboard();
  } catch (err) { toast(err.message, 'error'); }
};

