// Bulk Voucher Batch Generator
window.openVoucherBatchModal = function() {
  document.getElementById('vch-form-title').value = '';
  document.getElementById('vch-form-prefix').value = 'XE26';
  document.getElementById('vch-form-qty').value = '25';
  document.getElementById('vch-form-pct').value = '25';
  document.getElementById('vch-form-max').value = '300';
  document.getElementById('vch-form-min').value = '250';
  document.getElementById('vch-form-until').value = '2026-12-31';
  document.getElementById('vch-generated-output').style.display = 'none';
  openModal('modal-voucher-batch');
};

window.handleGenerateVoucherBatch = async function(e) {
  e.preventDefault();
  const btn = document.getElementById('vch-generate-btn');
  btn.disabled = true;
  btn.textContent = 'Generating...';

  const payload = {
    title: document.getElementById('vch-form-title').value.trim(),
    prefix: document.getElementById('vch-form-prefix').value.trim().toUpperCase(),
    quantity: Number(document.getElementById('vch-form-qty').value),
    discountPct: Number(document.getElementById('vch-form-pct').value),
    maxDiscount: Number(document.getElementById('vch-form-max').value),
    minSpend: Number(document.getElementById('vch-form-min').value),
    targetAudience: document.getElementById('vch-form-audience').value,
    validUntil: document.getElementById('vch-form-until').value
  };

  try {
    const res = await api('/api/admin/coupons/batch-generate', { method: 'POST', body: payload });
    toast(`Successfully generated ${res.total_codes} single-use voucher codes!`, 'success');

    // Display output
    const outputBox = document.getElementById('vch-generated-output');
    const textarea = document.getElementById('vch-codes-textarea');
    if (outputBox && textarea) {
      outputBox.style.display = 'block';
      textarea.value = (res.codes || []).join('\n');
    }
    loadCouponsDashboard();
  } catch (err) { toast(err.message, 'error'); }
  finally {
    btn.disabled = false;
    btn.textContent = 'Generate Batch';
  }
};

window.copyGeneratedVouchers = function() {
  const textarea = document.getElementById('vch-codes-textarea');
  if (!textarea) return;
  navigator.clipboard.writeText(textarea.value);
  toast('All voucher codes copied to clipboard!', 'success');
};

// Real-Time Discount Sandbox Simulator
window.openCouponSimulatorModal = function() {
  document.getElementById('sim-cpn-code').value = 'WELCOME50';
  document.getElementById('sim-task-budget').value = '1000';
  document.getElementById('sim-category-name').value = 'all';
  document.getElementById('sim-result-box').style.display = 'none';
  openModal('modal-coupon-simulator');
};

window.handleSimulateCoupon = async function(e) {
  e.preventDefault();
  const code = document.getElementById('sim-cpn-code').value.trim().toUpperCase();
  const taskBudget = Number(document.getElementById('sim-task-budget').value) || 1000;
  const categoryName = document.getElementById('sim-category-name').value;

  const resultBox = document.getElementById('sim-result-box');
  resultBox.style.display = 'block';
  resultBox.innerHTML = '<div style="color:#94A3B8;font-size:0.85rem">Calculating simulation...</div>';

  try {
    const sim = await api('/api/admin/coupons/simulate', {
      method: 'POST',
      body: { code, taskBudget, categoryName }
    });

    if (!sim.valid) {
      resultBox.innerHTML = `
        <div style="display:flex;align-items:center;gap:8px;color:#EF4444;margin-bottom:6px">
          <span>❌</span>
          <b>Coupon Ineligible / Invalid</b>
        </div>
        <p style="color:#FCA5A5;font-size:0.85rem;margin:0">${escapeHtml(sim.message)}</p>
      `;
      return;
    }

    resultBox.innerHTML = `
      <div style="display:flex;align-items:center;gap:8px;color:#10B981;margin-bottom:10px">
        <span>✅</span>
        <b>${escapeHtml(sim.message)}</b>
      </div>

      <div style="background:#1E293B;padding:12px;border-radius:6px;font-size:0.85rem">
        <div style="display:flex;justify-content:space-between;margin-bottom:6px">
          <span style="color:#94A3B8">Original Task Escrow:</span>
          <b style="color:#fff">৳${Number(sim.original_price).toLocaleString()} BDT</b>
        </div>
        <div style="display:flex;justify-content:space-between;margin-bottom:6px">
          <span style="color:#34D399">Discount Incentive:</span>
          <b style="color:#34D399">-৳${Number(sim.discount_amount).toLocaleString()} BDT</b>
        </div>
        <div style="display:flex;justify-content:space-between;margin-bottom:6px;border-top:1px solid rgba(255,255,255,0.08);padding-top:6px">
          <span style="color:#fff;font-weight:700">Net Client Payable:</span>
          <b style="color:#818CF8;font-size:1rem">৳${Number(sim.final_client_price).toLocaleString()} BDT</b>
        </div>
        <div style="display:flex;justify-content:space-between;font-size:0.78rem;color:#64748B;margin-top:6px">
          <span>Net Freelancer Receives:</span>
          <span>৳${Number(sim.net_freelancer_payout).toLocaleString()} BDT</span>
        </div>
      </div>
    `;
  } catch (err) {
    resultBox.innerHTML = `<div style="color:#EF4444;font-size:0.85rem">${err.message}</div>`;
  }
};

