/* ---------- 16. ADVANCED SYSTEM CONFIGURATION ---------- */
async function loadPlatformSettings() {
  try {
    const res = await api('/api/admin/config');
    const cfg = res.config || {};
    if (document.getElementById('cfg-fee-percent')) document.getElementById('cfg-fee-percent').value = cfg.commissionPercent ?? 10;
    if (document.getElementById('cfg-min-payout')) document.getElementById('cfg-min-payout').value = cfg.minWithdrawal ?? 100;
    if (document.getElementById('cfg-auto-release')) document.getElementById('cfg-auto-release').value = cfg.autoReleaseHours ?? 48;
    if (document.getElementById('cfg-support-email')) document.getElementById('cfg-support-email').value = cfg.supportEmail || 'support@xtraearn.com';
    if (document.getElementById('cfg-emergency-phone')) document.getElementById('cfg-emergency-phone').value = cfg.emergencyPhone || '+880 1711-100000';
    if (document.getElementById('cfg-allow-reg')) document.getElementById('cfg-allow-reg').checked = Boolean(cfg.allowNewRegistrations);
    if (document.getElementById('cfg-maint-mode')) document.getElementById('cfg-maint-mode').checked = Boolean(cfg.maintenanceMode);
  } catch (err) { console.error(err); }
}

async function savePlatformSettings() {
  const payload = {
    commissionPercent: Number(document.getElementById('cfg-fee-percent').value),
    minWithdrawal: Number(document.getElementById('cfg-min-payout').value),
    autoReleaseHours: Number(document.getElementById('cfg-auto-release').value),
    supportEmail: document.getElementById('cfg-support-email').value.trim(),
    emergencyPhone: document.getElementById('cfg-emergency-phone').value.trim(),
    allowNewRegistrations: document.getElementById('cfg-allow-reg').checked,
    maintenanceMode: document.getElementById('cfg-maint-mode').checked
  };

  try {
    await api('/api/admin/config', { method: 'POST', body: payload });
    toast('⚙️ Platform settings saved to database successfully!', 'success');
  } catch (err) { toast(err.message, 'error'); }
}

