function renderFinancialAnalytics(data) {
  if (!data) return;

  setElText('fin-kpi-gross-gmv', `৳${Number(data.gross_volume || 0).toLocaleString('en-US', { minimumFractionDigits: 0 })}`);
  setElText('fin-kpi-net-profit', `৳${Number(data.net_platform_profit || 0).toLocaleString('en-US', { minimumFractionDigits: 0 })}`);
  setElText('fin-kpi-paid-out', `৳${Number(data.total_paid_out || 0).toLocaleString('en-US', { minimumFractionDigits: 0 })}`);
  setElText('fin-kpi-escrow-float', `৳${Number(data.escrow_held || 0).toLocaleString('en-US', { minimumFractionDigits: 0 })}`);

  // 1. Render Multi-Line SVG Chart
  const chartWrap = document.getElementById('fin-rev-chart-wrap');
  if (chartWrap && data.chart && data.chart.length > 0) {
    const pts = data.chart;
    const w = 540, h = 200, padX = 40, padY = 24;
    const maxGmv = Math.max(...pts.map(p => p.gmv || 0)) * 1.15 || 1000;

    const gmvCoords = pts.map((p, i) => {
      const x = padX + (i / (pts.length - 1)) * (w - padX * 2);
      const y = h - padY - ((p.gmv || 0) / maxGmv) * (h - padY * 2);
      return { x, y, ...p };
    });

    const commCoords = pts.map((p, i) => {
      const x = padX + (i / (pts.length - 1)) * (w - padX * 2);
      const y = h - padY - (((p.revenue || 0) * 10) / maxGmv) * (h - padY * 2);
      return { x, y, ...p };
    });

    const gmvPath = gmvCoords.map((c, i) => `${i === 0 ? 'M' : 'L'} ${c.x.toFixed(1)} ${c.y.toFixed(1)}`).join(' ');
    const commPath = commCoords.map((c, i) => `${i === 0 ? 'M' : 'L'} ${c.x.toFixed(1)} ${c.y.toFixed(1)}`).join(' ');

    chartWrap.innerHTML = `
      <svg viewBox="0 0 ${w} ${h}" style="width:100%;height:100%;overflow:visible">
        <defs>
          <linearGradient id="finGmvGrad" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stop-color="#10B981" stop-opacity="0.3"/>
            <stop offset="100%" stop-color="#10B981" stop-opacity="0.0"/>
          </linearGradient>
          <linearGradient id="finCommGrad" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stop-color="#8B5CF6" stop-opacity="0.25"/>
            <stop offset="100%" stop-color="#8B5CF6" stop-opacity="0.0"/>
          </linearGradient>
        </defs>
        <!-- Horizontal Gridlines -->
        <line x1="${padX}" y1="${padY}" x2="${w - padX}" y2="${padY}" stroke="rgba(255,255,255,0.06)" stroke-dasharray="3,3"/>
        <line x1="${padX}" y1="${h / 2}" x2="${w - padX}" y2="${h / 2}" stroke="rgba(255,255,255,0.06)" stroke-dasharray="3,3"/>
        <line x1="${padX}" y1="${h - padY}" x2="${w - padX}" y2="${h - padY}" stroke="rgba(255,255,255,0.1)"/>
        
        <!-- GMV Area & Line -->
        <path d="${gmvPath} L ${gmvCoords[gmvCoords.length - 1].x} ${h - padY} L ${gmvCoords[0].x} ${h - padY} Z" fill="url(#finGmvGrad)"/>
        <path d="${gmvPath}" fill="none" stroke="#10B981" stroke-width="2.5" stroke-linecap="round"/>
        
        <!-- Commission Area & Line -->
        <path d="${commPath} L ${commCoords[commCoords.length - 1].x} ${h - padY} L ${commCoords[0].x} ${h - padY} Z" fill="url(#finCommGrad)"/>
        <path d="${commPath}" fill="none" stroke="#8B5CF6" stroke-width="2" stroke-linecap="round"/>

        <!-- Points & Labels -->
        ${gmvCoords.map(c => `
          <circle cx="${c.x}" cy="${c.y}" r="3.5" fill="#10B981" stroke="#0B1120" stroke-width="2"/>
          <text x="${c.x}" y="${h - 6}" font-size="10" fill="#94A3B8" text-anchor="middle" font-weight="600">${c.label}</text>
        `).join('')}
      </svg>
    `;
  }

  // 2. Render Payment Gateways
  const gwWrap = document.getElementById('fin-gateways-list');
  if (gwWrap && data.gateway_breakdown) {
    gwWrap.innerHTML = data.gateway_breakdown.map(g => `
      <div style="background:#0B1120;border:1px solid rgba(255,255,255,0.06);border-radius:10px;padding:10px 14px">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px">
          <div style="display:flex;align-items:center;gap:8px">
            <span>${g.icon}</span>
            <b style="color:#fff;font-size:0.85rem">${escapeHtml(g.name)}</b>
          </div>
          <b style="color:#10B981;font-size:0.85rem">${g.sharePct}%</b>
        </div>
        <div style="width:100%;height:5px;background:#1E293B;border-radius:3px;overflow:hidden;margin-bottom:6px">
          <div style="width:${g.sharePct}%;background:#10B981;height:100%"></div>
        </div>
        <div style="display:flex;justify-content:space-between;color:#94A3B8;font-size:0.72rem">
          <span>Vol: ৳${(g.volume || 0).toLocaleString()}</span>
          <span>Success: <b style="color:#34D399">${g.successRate}</b> · Latency: ${g.latency}</span>
        </div>
      </div>
    `).join('');
  }

  // 3. Render General Ledger Table
  const tbody = document.getElementById('fin-ledger-table-body');
  if (tbody && data.ledger_breakdown) {
    tbody.innerHTML = data.ledger_breakdown.map(l => `
      <tr>
        <td><b style="color:#fff">${escapeHtml(l.month)}</b></td>
        <td><b style="color:#38BDF8">৳${Number(l.gmv || 0).toLocaleString()}</b></td>
        <td><span style="color:#CBD5E1">৳${Number(l.escrowInflow || 0).toLocaleString()}</span></td>
        <td><span style="color:#94A3B8">৳${Number(l.payouts || 0).toLocaleString()}</span></td>
        <td><b style="color:#10B981">৳${Number(l.netCommission || 0).toLocaleString()}</b></td>
        <td><span class="badge-chip" style="background:rgba(139,92,246,0.2);color:#A78BFA;font-weight:700">${l.marginPct}%</span></td>
        <td><span class="badge-chip" style="background:rgba(16,185,129,0.2);color:#34D399;font-weight:700">✓ ${escapeHtml(l.status)}</span></td>
      </tr>
    `).join('');
  }
}

