function renderGmvTakeRateAnalytics(data) {
  if (!data) return;

  setElText('gmv-kpi-monthly', `৳${Number(data.current_monthly_gmv || 480000).toLocaleString()} BDT`);
  setElText('gmv-kpi-take-rate', data.effective_take_rate || '10.18%');
  setElText('gmv-kpi-net-revenue', `৳${Number(data.net_monthly_revenue || 48864).toLocaleString()} BDT`);
  setElText('gmv-kpi-projected', data.projected_6month_gmv || '৳4.2M BDT');

  // Render GMV Trendline
  const chartWrap = document.getElementById('gmv-forecast-chart-wrap');
  if (chartWrap && data.trendline) {
    const pts = data.trendline;
    const w = 540, h = 200, padX = 40, padY = 24;
    const maxVal = 800000;

    const coords = pts.map((p, i) => {
      const x = padX + (i / (pts.length - 1)) * (w - padX * 2);
      const val = p.actualGmv || p.projectedGmv || 300000;
      const y = h - padY - (val / maxVal) * (h - padY * 2);
      return { x, y, isProjected: !p.actualGmv, ...p };
    });

    const actualCoords = coords.filter(c => !c.isProjected);
    const projCoords = coords.filter(c => c.isProjected || c.period.includes('Aug'));

    const actualPath = actualCoords.map((c, i) => `${i === 0 ? 'M' : 'L'} ${c.x.toFixed(1)} ${c.y.toFixed(1)}`).join(' ');
    const projPath = projCoords.map((c, i) => `${i === 0 ? 'M' : 'L'} ${c.x.toFixed(1)} ${c.y.toFixed(1)}`).join(' ');

    chartWrap.innerHTML = `
      <svg viewBox="0 0 ${w} ${h}" style="width:100%;height:100%;overflow:visible">
        <line x1="${padX}" y1="${padY}" x2="${w - padX}" y2="${padY}" stroke="rgba(255,255,255,0.06)" stroke-dasharray="3,3"/>
        <line x1="${padX}" y1="${h / 2}" x2="${w - padX}" y2="${h / 2}" stroke="rgba(255,255,255,0.06)" stroke-dasharray="3,3"/>
        <line x1="${padX}" y1="${h - padY}" x2="${w - padX}" y2="${h - padY}" stroke="rgba(255,255,255,0.1)"/>
        
        <path d="${actualPath}" fill="none" stroke="#10B981" stroke-width="2.5" stroke-linecap="round"/>
        <path d="${projPath}" fill="none" stroke="#F59E0B" stroke-width="2" stroke-dasharray="4,4" stroke-linecap="round"/>

        ${coords.map(c => `
          <circle cx="${c.x}" cy="${c.y}" r="${c.isProjected ? 3 : 4}" fill="${c.isProjected ? '#F59E0B' : '#10B981'}" stroke="#0B1120" stroke-width="2"/>
          <text x="${c.x}" y="${h - 6}" font-size="9" fill="#94A3B8" text-anchor="middle" font-weight="600">${c.period.split(' ')[0]}</text>
        `).join('')}
      </svg>
    `;
  }

  // Revenue Streams
  const streamsWrap = document.getElementById('gmv-revenue-streams-wrap');
  if (streamsWrap && data.revenue_streams) {
    streamsWrap.innerHTML = data.revenue_streams.map(s => `
      <div style="background:#0B1120;border:1px solid rgba(255,255,255,0.06);border-radius:10px;padding:10px 14px">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px">
          <b style="color:#fff;font-size:0.82rem">${escapeHtml(s.stream)}</b>
          <b style="color:${s.color};font-size:0.85rem">${s.sharePct}%</b>
        </div>
        <div style="width:100%;height:5px;background:#1E293B;border-radius:3px;overflow:hidden;margin-bottom:6px">
          <div style="width:${s.sharePct}%;background:${s.color};height:100%"></div>
        </div>
        <div style="display:flex;justify-content:space-between;color:#94A3B8;font-size:0.72rem">
          <span>Monthly: <b style="color:#fff">৳${Number(s.monthlyAmount || 0).toLocaleString()}</b></span>
          <span style="color:${s.color}">Active Stream</span>
        </div>
      </div>
    `).join('');
  }
}

