function renderRetentionAnalytics(data) {
  if (!data) return;
  setElText('ret-kpi-m1', data.month_1_retention || '68.4%');
  setElText('ret-kpi-m3', data.month_3_retention || '51.4%');
  setElText('ret-kpi-ltv-cac', data.ltv_cac_ratio || '4.8x');
  setElText('ret-kpi-churn', data.churn_risk_rate || '4.2%');

  const cWrap = document.getElementById('ret-decay-chart-wrap');
  if (cWrap && data.decay_curve) {
    const pts = data.decay_curve;
    const w = 540, h = 200, padX = 40, padY = 24;

    const coords = pts.map((p, i) => {
      const x = padX + (i / (pts.length - 1)) * (w - padX * 2);
      const y = h - padY - ((p.retentionPct || 0) / 100) * (h - padY * 2);
      return { x, y, ...p };
    });

    const path = coords.map((c, i) => `${i === 0 ? 'M' : 'L'} ${c.x.toFixed(1)} ${c.y.toFixed(1)}`).join(' ');

    cWrap.innerHTML = `
      <svg viewBox="0 0 ${w} ${h}" style="width:100%;height:100%;overflow:visible">
        <defs>
          <linearGradient id="retGrad" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stop-color="#10B981" stop-opacity="0.3"/>
            <stop offset="100%" stop-color="#10B981" stop-opacity="0.0"/>
          </linearGradient>
        </defs>
        <line x1="${padX}" y1="${padY}" x2="${w - padX}" y2="${padY}" stroke="rgba(255,255,255,0.06)" stroke-dasharray="3,3"/>
        <line x1="${padX}" y1="${h / 2}" x2="${w - padX}" y2="${h / 2}" stroke="rgba(255,255,255,0.06)" stroke-dasharray="3,3"/>
        <line x1="${padX}" y1="${h - padY}" x2="${w - padX}" y2="${h - padY}" stroke="rgba(255,255,255,0.1)"/>
        
        <path d="${path} L ${coords[coords.length - 1].x} ${h - padY} L ${coords[0].x} ${h - padY} Z" fill="url(#retGrad)"/>
        <path d="${path}" fill="none" stroke="#10B981" stroke-width="2.5" stroke-linecap="round"/>

        ${coords.map(c => `
          <circle cx="${c.x}" cy="${c.y}" r="3.5" fill="#10B981" stroke="#0B1120" stroke-width="2"/>
          <text x="${c.x}" y="${h - 6}" font-size="9" fill="#94A3B8" text-anchor="middle" font-weight="600">${c.month}</text>
        `).join('')}
      </svg>
    `;
  }

  const fWrap = document.getElementById('ret-frequency-wrap');
  if (fWrap && data.repeat_frequencies) {
    fWrap.innerHTML = data.repeat_frequencies.map(f => `
      <div style="background:#0B1120;border:1px solid rgba(255,255,255,0.06);border-radius:10px;padding:10px 14px">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px">
          <b style="color:#fff;font-size:0.82rem">${escapeHtml(f.frequency)}</b>
          <b style="color:${f.color};font-size:0.85rem">${f.userSharePct}%</b>
        </div>
        <div style="width:100%;height:5px;background:#1E293B;border-radius:3px;overflow:hidden">
          <div style="width:${f.userSharePct}%;background:${f.color};height:100%"></div>
        </div>
      </div>
    `).join('');
  }
}

