async function loadPushAnalytics() {
  try {
    const data = await api('/api/admin/push/analytics');
    if (!data) return;

    // Render Hourly Volume SVG Chart
    const cWrap = document.getElementById('push-hourly-chart-wrap');
    if (cWrap && data.hourly_volume) {
      const pts = data.hourly_volume;
      const w = 540, h = 200, padX = 40, padY = 24;
      const maxSent = Math.max(...pts.map(p => p.sent || 1));

      const coordsSent = pts.map((p, i) => {
        const x = padX + (i / (pts.length - 1)) * (w - padX * 2);
        const y = h - padY - (p.sent / maxSent) * (h - padY * 2);
        return { x, y, ...p };
      });

      const coordsClicks = pts.map((p, i) => {
        const x = padX + (i / (pts.length - 1)) * (w - padX * 2);
        const y = h - padY - (p.clicked / (maxSent * 0.3)) * (h - padY * 2);
        return { x, y, ...p };
      });

      const pathSent = coordsSent.map((c, i) => `${i === 0 ? 'M' : 'L'} ${c.x.toFixed(1)} ${c.y.toFixed(1)}`).join(' ');
      const pathClicks = coordsClicks.map((c, i) => `${i === 0 ? 'M' : 'L'} ${c.x.toFixed(1)} ${c.y.toFixed(1)}`).join(' ');

      cWrap.innerHTML = `
        <svg viewBox="0 0 ${w} ${h}" style="width:100%;height:100%;overflow:visible">
          <line x1="${padX}" y1="${padY}" x2="${w - padX}" y2="${padY}" stroke="rgba(255,255,255,0.06)" stroke-dasharray="3,3"/>
          <line x1="${padX}" y1="${h / 2}" x2="${w - padX}" y2="${h / 2}" stroke="rgba(255,255,255,0.06)" stroke-dasharray="3,3"/>
          <line x1="${padX}" y1="${h - padY}" x2="${w - padX}" y2="${h - padY}" stroke="rgba(255,255,255,0.1)"/>
          
          <path d="${pathSent}" fill="none" stroke="#10B981" stroke-width="2.5" stroke-linecap="round"/>
          <path d="${pathClicks}" fill="none" stroke="#8B5CF6" stroke-width="2" stroke-linecap="round"/>

          ${coordsSent.map(c => `
            <circle cx="${c.x}" cy="${c.y}" r="3" fill="#10B981" stroke="#0B1120" stroke-width="1.5"/>
            <text x="${c.x}" y="${h - 6}" font-size="8.5" fill="#94A3B8" text-anchor="middle" font-weight="600">${c.hour}</text>
          `).join('')}
        </svg>
      `;
    }

    // Render Category CTR Table
    const tbody = document.getElementById('push-category-ctr-body');
    if (tbody && data.category_ctr) {
      tbody.innerHTML = data.category_ctr.map(c => `
        <tr>
          <td><b style="color:#fff">${escapeHtml(c.category)}</b></td>
          <td><b style="color:#10B981">${c.ctr}</b></td>
          <td><span style="color:#38BDF8">${c.avgDeliveryMs} ms</span></td>
          <td><span style="color:#CBD5E1">${Number(c.volume).toLocaleString()}</span></td>
          <td><span class="badge-chip" style="background:rgba(16,185,129,0.2);color:#34D399;font-weight:700">${c.conversion}</span></td>
        </tr>
      `).join('');
    }
  } catch (err) {
    console.error('Error loading push analytics:', err);
  }
}

