    setElText('email-kpi-templates', `${data.total_templates} Templates`);
    setElText('email-kpi-volume24h', Number(data.volume_24h || 24850).toLocaleString());
    setElText('email-kpi-open-rate', data.avg_open_rate || '46.2%');
    setElText('email-kpi-click-rate', data.avg_click_rate || '18.5%');
    setElText('email-kpi-smtp-status', `Online (${data.smtp_latency_ms || 42}ms)`);
    setElText('email-kpi-bounce-rate', data.bounce_rate || '0.02%');
