          <span class="badge-chip" style="background:${t.status === 'active' ? 'rgba(16,185,129,0.2)' : 'rgba(239,68,68,0.2)'};color:${t.status === 'active' ? '#34D399' : '#F87171'}">${t.status.toUpperCase()}</span>
