async function openEmailEditor(id) {
  try {
    const tpl = await api(`/api/admin/email-templates/${id}`);
    currentEditingTemplate = tpl;

    const elId = document.getElementById('editor-template-id');
    const elName = document.getElementById('editor-name');
    const elCategory = document.getElementById('editor-category');
    const elSubject = document.getElementById('editor-subject');
    const elPreheader = document.getElementById('editor-preheader');
    const elFromName = document.getElementById('editor-from-name');
    const elFromEmail = document.getElementById('editor-from-email');
    const elBody = document.getElementById('editor-body-html');
    const elBadge = document.getElementById('editor-active-badge');

    if (elId) elId.value = tpl.id;
    if (elName) elName.value = tpl.name;
    if (elCategory) elCategory.value = tpl.category;
    if (elSubject) elSubject.value = tpl.subject;
    if (elPreheader) elPreheader.value = tpl.preheader || '';
    if (elFromName) elFromName.value = tpl.from_name;
    if (elFromEmail) elFromEmail.value = tpl.from_email;
    if (elBody) elBody.value = tpl.body_html || '';
    if (elBadge) elBadge.textContent = `Editing #${tpl.id} (${tpl.slug})`;

    switchEmailTab('editor');
    updateLiveEmailPreview();
  } catch (err) {
    toast(err.message || 'Error opening template editor', 'error');
  }
}

