async function loadEmailAnalytics() {
  try {
    const data = await api('/api/admin/email-templates/analytics');
    if (!data) return;

    // Render 24h Hourly Trajectory SVG
    const cWrap = document.getElementById('email-hourly-chart-wrap');
    if (cWrap && data.hourly_trajectory) {
      const pts = data.hourly_trajectory;
      const w = 540, h = 200, padX = 40, padY = 24;
      const maxSent = Math.max(...pts.map(p => p.sent || 1));

      const coordsSent = pts.map((p, i) => {
        const x = padX + (i / (pts.length - 1)) * (w - padX * 2);
        const y = h - padY - (p.sent / maxSent) * (h - padY * 2);
        return { x, y, ...p };
      });

      const coordsOpened = pts.map((p, i) => {
        const x = padX + (i / (pts.length - 1)) * (w - padX * 2);
        const y = h - padY - (p.opened / (maxSent * 0.55)) * (h - padY * 2);
        return { x, y, ...p };
      });

      const pathSent = coordsSent.map((c, i) => `${i === 0 ? 'M' : 'L'} ${c.x.toFixed(1)} ${c.y.toFixed(1)}`).join(' ');
      const pathOpened = coordsOpened.map((c, i) => `${i === 0 ? 'M' : 'L'} ${c.x.toFixed(1)} ${c.y.toFixed(1)}`).join(' ');

      cWrap.innerHTML = `
        <svg viewBox="0 0 ${w} ${h}" style="width:100%;height:100%;overflow:visible">
          <line x1="${padX}" y1="${padY}" x2="${w - padX}" y2="${padY}" stroke="rgba(255,255,255,0.06)" stroke-dasharray="3,3"/>
          <line x1="${padX}" y1="${h / 2}" x2="${w - padX}" y2="${h / 2}" stroke="rgba(255,255,255,0.06)" stroke-dasharray="3,3"/>
          <line x1="${padX}" y1="${h - padY}" x2="${w - padX}" y2="${h - padY}" stroke="rgba(255,255,255,0.1)"/>
          
          <path d="${pathSent}" fill="none" stroke="#10B981" stroke-width="2.5" stroke-linecap="round"/>
          <path d="${pathOpened}" fill="none" stroke="#38BDF8" stroke-width="2" stroke-linecap="round"/>

          ${coordsSent.map(c => `
            <circle cx="${c.x}" cy="${c.y}" r="3" fill="#10B981" stroke="#0B1120" stroke-width="1.5"/>
            <text x="${c.x}" y="${h - 6}" font-size="8.5" fill="#94A3B8" text-anchor="middle" font-weight="600">${c.hour}</text>
          `).join('')}
        </svg>
      `;
    }

    // Render Category Benchmarks Table
    const tbody = document.getElementById('email-category-benchmarks-body');
    if (tbody && data.category_benchmarks) {
      tbody.innerHTML = data.category_benchmarks.map(c => `
        <tr>
          <td><b style="color:#fff">${escapeHtml(c.category)}</b></td>
          <td><b style="color:#10B981">${c.open_rate}</b></td>
          <td><b style="color:#A78BFA">${c.click_rate}</b></td>
          <td><span style="color:#CBD5E1">${Number(c.sent_24h).toLocaleString()}</span></td>
          <td><span class="badge-chip" style="background:rgba(16,185,129,0.2);color:#34D399;font-weight:700">${c.status}</span></td>
        </tr>
      `).join('');
    }
  } catch (err) {
    console.error('Error loading email analytics:', err);
  }
}

