async function handleSendTestSms() {
  const phone = document.getElementById('sms-test-target-phone')?.value.trim();
  const message = document.getElementById('sms-test-message-body')?.value.trim();
  const activeProv = document.getElementById('sms-cfg-provider')?.value || 'greenweb';
  const senderId = document.getElementById('sms-cfg-sender-id')?.value.trim() || 'XtraEarn';

  if (!phone) {
    toast('Please enter a recipient phone number', 'warning');
    return;
  }
  if (!message) {
    toast('Please enter SMS message body text', 'warning');
    return;
  }

  const btn = document.getElementById('btn-dispatch-test-sms');
  const feedback = document.getElementById('sms-test-dispatch-feedback');

  if (btn) btn.disabled = true;
  if (feedback) feedback.textContent = 'Transmitting SMS to carrier...';

  try {
    const res = await api('/api/admin/sms/send-test', {
      method: 'POST',
      body: {
        phone,
        message,
        senderId,
        provider: activeProv
      }
    });

    if (res && res.success) {
      toast(`✅ SMS dispatched! Status: ${res.status}, Message ID: ${res.message_id}`, 'success');
      if (feedback) feedback.textContent = `Delivered in ${res.latency_ms}ms via ${res.provider} (Cost: ৳${res.cost_bdt})`;
      loadSmsKPIs();
      loadSmsLogs();
    } else {
      toast(res.error || 'Failed to dispatch SMS', 'error');
      if (feedback) feedback.textContent = `Failed: ${res.error || 'Unknown error'}`;
    }
  } catch (err) {
    toast(`Dispatch error: ${err.message}`, 'error');
    if (feedback) feedback.textContent = `Error: ${err.message}`;
  } finally {
    if (btn) btn.disabled = false;
  }
}

function exportSmsLogsCsv() {
  window.open('/api/admin/sms/export/logs', '_blank');
}

/* ---------- 13. KYC & VERIFICATIONS ---------- */
let kycDataCache = [];

async function loadKycTable() {
  const tbody = document.getElementById('kyc-table-body');
  if (!tbody) return;
  tbody.innerHTML = '<tr><td colspan="6" class="loading-td">Loading KYC applications...</td></tr>';
  try {
    const res = await api('/api/admin/kyc');
    kycDataCache = res.items || [];
    if (kycDataCache.length === 0) {
      tbody.innerHTML = '<tr><td colspan="6" style="text-align:center;padding:24px;color:#94A3B8">No pending KYC applications.</td></tr>';
      return;
    }
    tbody.innerHTML = kycDataCache.map(k => `
      <tr>
        <td>
          <b style="color:#fff;display:block">${escapeHtml(k.name)}</b>
          <small style="color:#94A3B8">${escapeHtml(k.email)}</small>
        </td>
        <td><span class="adm-status-chip blue">${escapeHtml(k.profession)}</span></td>
        <td>
          <b>${escapeHtml(k.doc_type)}</b>
          <small style="display:block;color:#10B981">${escapeHtml(k.doc_number)}</small>
        </td>
        <td>${k.submitted_at}</td>
        <td><span class="adm-status-chip ${k.status === 'approved' ? 'green' : k.status === 'rejected' ? 'red' : 'amber'}">${k.status.toUpperCase()}</span></td>
        <td>
          <button class="btn btn-outline-light btn-sm" onclick="inspectKycDoc(${k.id})">👁️ Inspect</button>
          ${k.status === 'pending' ? `
            <button class="btn btn-green btn-sm" onclick="handleKycDecision(${k.id}, 'approve')">✅ Approve</button>
            <button class="btn btn-red btn-sm" onclick="handleKycDecision(${k.id}, 'reject')">❌ Reject</button>
          ` : ''}
        </td>
      </tr>
    `).join('');
  } catch (err) {
    tbody.innerHTML = `<tr><td colspan="6" style="color:#EF4444;text-align:center">${err.message}</td></tr>`;
  }
}

function inspectKycDoc(id) {
  const item = kycDataCache.find(k => k.id === id);
  if (!item) return;
  document.getElementById('kyc-modal-name').textContent = item.name;
  document.getElementById('kyc-modal-profession').textContent = item.profession;
  document.getElementById('kyc-modal-docnum').textContent = item.doc_number;
  document.getElementById('kyc-modal-doc-img').src = item.doc_url;

  const approveBtn = document.getElementById('btn-kyc-approve');
  const rejectBtn = document.getElementById('btn-kyc-reject');

  approveBtn.onclick = () => handleKycDecision(id, 'approve');
  rejectBtn.onclick = () => handleKycDecision(id, 'reject');

  openModal('modal-kyc-inspect');
}

async function handleKycDecision(id, decision) {
  try {
    await api(`/api/admin/kyc/${id}/${decision}`, { method: 'POST', body: { reason: 'Administrative review completed' } });
    closeModal('modal-kyc-inspect');
    toast(`KYC application ${decision === 'approve' ? 'approved & verified badge granted' : 'rejected'}!`, 'success');
    loadKycTable();
  } catch (err) { toast(err.message, 'error'); }
}

/* ---------- 14. SUBCATEGORIES ---------- */
async function loadSubcategories() {
  const container = document.getElementById('subcategories-grid-body');
  if (!container) return;
  try {
    const res = await api('/api/admin/subcategories');
    const items = res.items || [];
    container.innerHTML = items.map(s => `
      <div class="adm-cat-card">
        <div class="adm-cat-icon">${s.icon}</div>
        <div class="adm-cat-info">
          <b>${escapeHtml(s.name)}</b>
          <small style="color:#94A3B8">Slug: /${s.slug}</small>
          <span style="font-size:0.75rem;color:#10B981;display:block;margin-top:4px">${s.task_count} Tasks Active</span>
        </div>
        <button class="btn btn-outline-light btn-sm" onclick="deleteSubcategory(${s.id})" style="margin-top:8px">🗑️ Remove</button>
      </div>
    `).join('');
  } catch (err) { container.innerHTML = `<div style="color:#EF4444">${err.message}</div>`; }
}

async function handleSubcategoryCreate(e) {
  e.preventDefault();
  const parent_id = document.getElementById('subcat-parent-id').value;
  const name = document.getElementById('subcat-name').value.trim();
  const icon = document.getElementById('subcat-icon').value.trim() || '📑';

  try {
    await api('/api/admin/subcategories', { method: 'POST', body: { category_id: parent_id, name, icon } });
    closeModal('modal-subcategory-create');
    toast(`Subcategory "${name}" created successfully!`, 'success');
    loadSubcategories();
  } catch (err) { toast(err.message, 'error'); }
}

async function deleteSubcategory(id) {
  if (!confirm('Are you sure you want to remove this subcategory?')) return;
  try {
    await api(`/api/admin/subcategories/${id}`, { method: 'DELETE' });
    toast('Subcategory deleted.', 'success');
    loadSubcategories();
  } catch (err) { toast(err.message, 'error'); }
}

/* ---------- 14B. SERVICES & GIG CATALOG CONTROLLER ---------- */
let currentServicesTab = 'all';
let currentServicesViewMode = 'cards'; // 'cards' or 'table'
let selectedServiceIds = new Set();
let srvSearchTimer = null;
let allServicesCache = [];
let isServicesListenersBound = false;

async function loadServices() {
  try {
    // 1. Fetch KPIs
    const kpis = await api('/api/admin/services/kpis');
    renderServicesKPIs(kpis);

    // 2. Build Query Params
    const searchVal = document.getElementById('srv-search-input')?.value.trim() || '';
    const catVal = document.getElementById('srv-cat-filter')?.value || 'all';
    const typeVal = document.getElementById('srv-type-filter')?.value || 'all';
    const modelVal = document.getElementById('srv-model-filter')?.value || 'all';
    const statusVal = document.getElementById('srv-status-filter')?.value || 'all';
    const sortVal = document.getElementById('srv-sort-filter')?.value || 'rating';

    let flagParam = '';
    let typeParam = typeVal;

    if (currentServicesTab === 'online') typeParam = 'online';
    else if (currentServicesTab === 'physical') typeParam = 'physical';
    else if (currentServicesTab === 'expert') typeParam = 'expert';
    else if (currentServicesTab === 'featured') flagParam = 'featured';
    else if (currentServicesTab === 'pending') flagParam = 'pending';

    const params = new URLSearchParams();
    if (searchVal) params.set('q', searchVal);
    if (catVal !== 'all') params.set('categoryId', catVal);
    if (typeParam !== 'all') params.set('serviceType', typeParam);
    if (modelVal !== 'all') params.set('pricingModel', modelVal);
    if (statusVal !== 'all') params.set('status', statusVal);
    if (flagParam) params.set('flag', flagParam);
    if (sortVal) params.set('sortBy', sortVal);

    const res = await api(`/api/admin/services?${params.toString()}`);
    allServicesCache = res.items || [];

    // Populate Category Dropdowns if not populated
    populateServicesCategorySelect();
    populateServicesProviderSelect();

    // Render in active view mode
    if (currentServicesViewMode === 'cards') {
      renderServicesCards(allServicesCache);
    } else {
      renderServicesTable(allServicesCache);
    }

    setupServicesListeners();
    updateSelectedServicesCount();
  } catch (err) {
    console.error('Error loading services:', err);
    toast('Could not load services catalog', 'error');
  }
}

function renderServicesKPIs(kpis = {}) {
  setElText('kpi-srv-total', kpis.total_services || 0);
  setElText('kpi-srv-active-sub', `${kpis.active_services || 0} Active · ${kpis.pending_approval || 0} In Review`);
  setElText('kpi-srv-online', kpis.online_services || 0);
  setElText('kpi-srv-physical', kpis.physical_services || 0);
  setElText('kpi-srv-bookings', Number(kpis.total_bookings || 0).toLocaleString());
  setElText('kpi-srv-gmv', `৳${Number(kpis.total_gmv || 0).toLocaleString()} GMV`);
  setElText('kpi-srv-rating', `${kpis.avg_rating || '4.95'}★`);

  setElText('srv-badge-all', kpis.total_services || 0);
  setElText('srv-badge-online', kpis.online_services || 0);
  setElText('srv-badge-physical', kpis.physical_services || 0);
  setElText('srv-badge-expert', kpis.expert_services || 0);
  setElText('srv-badge-pending', kpis.pending_approval || 0);
}

