function openCreateServiceModal() {
  const form = document.getElementById('form-create-service');
  if (form) form.reset();
  setElText('modal-service-title', '➕ Create Service Package');
  document.getElementById('srv-edit-id').value = '';
  populateServicesCategorySelect();
  populateServicesProviderSelect();
  handleServiceTypeChange('online');
  openModal('modal-create-service');
}
window.openCreateServiceModal = openCreateServiceModal;

async function openEditServiceModal(id) {
  try {
    const s = await api(`/api/admin/services/${id}`);
    if (!s) return;

    populateServicesCategorySelect();
    populateServicesProviderSelect();

    setElText('modal-service-title', `✏️ Edit Service: ${s.service_code}`);
    document.getElementById('srv-edit-id').value = s.id;
    document.getElementById('msrv-title').value = s.title || '';
    document.getElementById('msrv-type').value = s.service_type || 'online';
    document.getElementById('msrv-category').value = s.category_id || 1;
    document.getElementById('msrv-subcategory').value = s.subcategory || '';
    document.getElementById('msrv-model').value = s.pricing_model || 'tiered';
    document.getElementById('msrv-price-start').value = s.price_start || 250;
    document.getElementById('msrv-sla').value = s.delivery_sla || '24 Hours';
    document.getElementById('msrv-status').value = s.status || 'active';
    document.getElementById('msrv-featured').checked = s.is_featured === 1;
    document.getElementById('msrv-urgent').checked = s.is_urgent === 1;

    if (s.district) document.getElementById('msrv-district').value = s.district;
    if (s.area) document.getElementById('msrv-area').value = s.area;

    handleServiceTypeChange(s.service_type || 'online');

    const t = s.tiers || {};
    if (t.basic) {
      document.getElementById('tier-basic-name').value = t.basic.name || 'Starter';
      document.getElementById('tier-basic-price').value = t.basic.price || 250;
      document.getElementById('tier-basic-delivery').value = t.basic.delivery || '24 Hours';
      document.getElementById('tier-basic-features').value = (t.basic.features || []).join(', ');
    }
    if (t.standard) {
      document.getElementById('tier-std-name').value = t.standard.name || 'Pro Package';
      document.getElementById('tier-std-price').value = t.standard.price || 650;
      document.getElementById('tier-std-delivery').value = t.standard.delivery || '2 Days';
      document.getElementById('tier-std-features').value = (t.standard.features || []).join(', ');
    }
    if (t.premium) {
      document.getElementById('tier-prem-name').value = t.premium.name || 'Full Suite';
      document.getElementById('tier-prem-price').value = t.premium.price || 1500;
      document.getElementById('tier-prem-delivery').value = t.premium.delivery || '3 Days';
      document.getElementById('tier-prem-features').value = (t.premium.features || []).join(', ');
    }

    openModal('modal-create-service');
  } catch (err) {
    toast('Could not load service details for editing', 'error');
  }
}
window.openEditServiceModal = openEditServiceModal;

async function handleSaveService(e) {
  e.preventDefault();
  const editId = document.getElementById('srv-edit-id').value;

  const basicFeatures = (document.getElementById('tier-basic-features').value || '')
    .split(',').map(x => x.trim()).filter(Boolean);
  const stdFeatures = (document.getElementById('tier-std-features').value || '')
    .split(',').map(x => x.trim()).filter(Boolean);
  const premFeatures = (document.getElementById('tier-prem-features').value || '')
    .split(',').map(x => x.trim()).filter(Boolean);

  const providerSel = document.getElementById('msrv-provider');
  const providerText = providerSel.options[providerSel.selectedIndex]?.text || '';
  const providerName = providerText.split('(')[0].trim() || 'Verified Pro';

  const body = {
    title: document.getElementById('msrv-title').value.trim(),
    service_type: document.getElementById('msrv-type').value,
    category_id: Number(document.getElementById('msrv-category').value) || 1,
    subcategory: document.getElementById('msrv-subcategory').value.trim(),
    district: document.getElementById('msrv-type').value === 'physical' ? document.getElementById('msrv-district').value : null,
    area: document.getElementById('msrv-type').value === 'physical' ? document.getElementById('msrv-area').value.trim() : null,
    pricing_model: document.getElementById('msrv-model').value,
    price_start: Number(document.getElementById('msrv-price-start').value) || 250,
    delivery_sla: document.getElementById('msrv-sla').value.trim(),
    provider_id: Number(document.getElementById('msrv-provider').value) || 1,
    provider_name: providerName,
    status: document.getElementById('msrv-status').value,
    is_featured: document.getElementById('msrv-featured').checked ? 1 : 0,
    is_urgent: document.getElementById('msrv-urgent').checked ? 1 : 0,
    tiers: {
      basic: {
        name: document.getElementById('tier-basic-name').value.trim() || 'Starter',
        price: Number(document.getElementById('tier-basic-price').value) || 250,
        delivery: document.getElementById('tier-basic-delivery').value.trim() || '24 Hours',
        features: basicFeatures.length ? basicFeatures : ['Standard Delivery']
      },
      standard: {
        name: document.getElementById('tier-std-name').value.trim() || 'Pro',
        price: Number(document.getElementById('tier-std-price').value) || 650,
        delivery: document.getElementById('tier-std-delivery').value.trim() || '2 Days',
        features: stdFeatures.length ? stdFeatures : ['Pro Delivery + Revisions']
      },
      premium: {
        name: document.getElementById('tier-prem-name').value.trim() || 'VIP',
        price: Number(document.getElementById('tier-prem-price').value) || 1500,
        delivery: document.getElementById('tier-prem-delivery').value.trim() || '3 Days',
        features: premFeatures.length ? premFeatures : ['Full Package + Unlimited Support']
      }
    }
  };

  try {
    if (editId) {
      await api(`/api/admin/services/${editId}`, { method: 'PUT', body });
      toast('Service package updated successfully!', 'success');
    } else {
      await api('/api/admin/services', { method: 'POST', body });
      toast('New service package created successfully!', 'success');
    }
    closeModal('modal-create-service');
    loadServices();
  } catch (err) {
    toast(err.message || 'Error saving service package', 'error');
  }
}
window.handleSaveService = handleSaveService;

