/* Multi-Select & Bulk Operations */
function handleServiceSelectChange(id, checked) {
  if (checked) selectedServiceIds.add(id);
  else selectedServiceIds.delete(id);
  updateSelectedServicesCount();
}
window.handleServiceSelectChange = handleServiceSelectChange;

function toggleAllServiceCheckboxes(checked) {
  if (checked) {
    allServicesCache.forEach(s => selectedServiceIds.add(s.id));
  } else {
    selectedServiceIds.clear();
  }
  updateSelectedServicesCount();
  if (currentServicesViewMode === 'cards') renderServicesCards(allServicesCache);
  else renderServicesTable(allServicesCache);
}
window.toggleAllServiceCheckboxes = toggleAllServiceCheckboxes;

function updateSelectedServicesCount() {
  const count = selectedServiceIds.size;
  const bar = document.getElementById('services-bulk-bar');
  const countEl = document.getElementById('srv-selected-count');
  if (countEl) countEl.textContent = count;
  if (bar) bar.style.display = count > 0 ? 'flex' : 'none';
}

function deselectAllServices() {
  selectedServiceIds.clear();
  updateSelectedServicesCount();
  if (currentServicesViewMode === 'cards') renderServicesCards(allServicesCache);
  else renderServicesTable(allServicesCache);
}
window.deselectAllServices = deselectAllServices;

async function bulkUpdateServicesStatus(status) {
  if (!selectedServiceIds.size) return;
  try {
    await api('/api/admin/services/bulk', {
      method: 'POST',
      body: { action: 'status', serviceIds: Array.from(selectedServiceIds), payload: { status } }
    });
    toast(`Updated ${selectedServiceIds.size} services to ${status}`, 'success');
    deselectAllServices();
    loadServices();
  } catch (err) {
    toast('Bulk status update failed', 'error');
  }
}
window.bulkUpdateServicesStatus = bulkUpdateServicesStatus;

async function bulkToggleServicesFeature(is_featured) {
  if (!selectedServiceIds.size) return;
  try {
    await api('/api/admin/services/bulk', {
      method: 'POST',
      body: { action: 'feature', serviceIds: Array.from(selectedServiceIds), payload: { is_featured } }
    });
    toast(`Updated ${selectedServiceIds.size} services featured state`, 'success');
    deselectAllServices();
    loadServices();
  } catch (err) {
    toast('Bulk feature update failed', 'error');
  }
}
window.bulkToggleServicesFeature = bulkToggleServicesFeature;

function handleBulkActionTypeChange(action) {
  const row = document.getElementById('bulk-price-input-row');
  if (row) row.style.display = (action === 'price_discount' || action === 'price_markup') ? 'block' : 'none';
}
window.handleBulkActionTypeChange = handleBulkActionTypeChange;

async function handleApplyBulkServices(e) {
  e.preventDefault();
  const actionType = document.getElementById('bulk-srv-action').value;
  const percent = Number(document.getElementById('bulk-srv-percent')?.value) || 10;
  const targetIds = selectedServiceIds.size ? Array.from(selectedServiceIds) : allServicesCache.map(s => s.id);

  try {
    let action = 'status';
    let payload = {};

    if (actionType === 'status_active') { action = 'status'; payload = { status: 'active' }; }
    else if (actionType === 'status_paused') { action = 'status'; payload = { status: 'paused' }; }
    else if (actionType === 'feature_on') { action = 'feature'; payload = { is_featured: 1 }; }
    else if (actionType === 'feature_off') { action = 'feature'; payload = { is_featured: 0 }; }
    else if (actionType === 'price_discount') { action = 'price_adjust'; payload = { percent: -Math.abs(percent) }; }
    else if (actionType === 'price_markup') { action = 'price_adjust'; payload = { percent: Math.abs(percent) }; }

    await api('/api/admin/services/bulk', {
      method: 'POST',
      body: { action, serviceIds: targetIds, payload }
    });

    toast(`Bulk action applied to ${targetIds.length} services!`, 'success');
    closeModal('modal-bulk-services');
    deselectAllServices();
    loadServices();
  } catch (err) {
    toast('Bulk operation failed', 'error');
  }
}
window.handleApplyBulkServices = handleApplyBulkServices;

function exportServicesCatalog(format = 'json') {
  if (!allServicesCache.length) {
    toast('No services available to export', 'info');
    return;
  }

  if (format === 'json') {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(allServicesCache, null, 2));
    const a = document.createElement('a');
    a.setAttribute("href", dataStr);
    a.setAttribute("download", `xtraearn_services_catalog_${new Date().toISOString().split('T')[0]}.json`);
    document.body.appendChild(a);
    a.click();
    a.remove();
    toast('Services catalog exported to JSON', 'success');
  } else if (format === 'csv') {
    const headers = ['ID', 'Code', 'Title', 'Type', 'Category', 'Subcategory', 'Price Starting', 'Rating', 'Orders Completed', 'Provider', 'Status'];
    const rows = allServicesCache.map(s => [
      s.id,
      `"${s.service_code || ''}"`,
      `"${(s.title || '').replace(/"/g, '""')}"`,
      s.service_type || 'online',
      `"${s.category_name || ''}"`,
      `"${s.subcategory || ''}"`,
      s.price_start || 0,
      s.rating || 5.0,
      s.orders_completed || 0,
      `"${s.provider_name || ''}"`,
      s.status || 'active'
    ]);

    const csvContent = "data:text/csv;charset=utf-8," + [headers.join(','), ...rows.map(e => e.join(','))].join('\n');
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement('a');
    link.setAttribute('href', encodedUri);
    link.setAttribute('download', `xtraearn_services_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    link.remove();
    toast('Services catalog exported to CSV', 'success');
  }
}
window.exportServicesCatalog = exportServicesCatalog;

/* ---------- 15. TASK TEMPLATES & BLUEPRINTS CENTER ---------- */
let tmplSearchTimer = null;
let currentTemplateViewMode = 'grid'; // 'grid' or 'table'
let currentTemplateCategoryFilter = 'all';
let currentTemplateTagFilter = '';
let currentTemplatePage = 1;
const TEMPLATES_PER_PAGE = 8;
let allTemplatesCache = [];

function debounceTemplatesSearch() {
  clearTimeout(tmplSearchTimer);
  tmplSearchTimer = setTimeout(() => {
    currentTemplatePage = 1;
    loadTemplates();
  }, 300);
}
window.debounceTemplatesSearch = debounceTemplatesSearch;

function switchTemplateViewMode(mode) {
  currentTemplateViewMode = mode;
  const gridBtn = document.getElementById('btn-tmpl-view-grid');
  const tableBtn = document.getElementById('btn-tmpl-view-table');
  const gridContainer = document.getElementById('templates-grid-container');
  const tableContainer = document.getElementById('templates-table-container');

  if (mode === 'grid') {
    if (gridBtn) { gridBtn.className = 'btn btn-sm btn-purple'; }
    if (tableBtn) { tableBtn.className = 'btn btn-sm btn-outline-light'; }
    if (gridContainer) gridContainer.style.display = 'grid';
    if (tableContainer) tableContainer.style.display = 'none';
  } else {
    if (gridBtn) { gridBtn.className = 'btn btn-sm btn-outline-light'; }
    if (tableBtn) { tableBtn.className = 'btn btn-sm btn-purple'; }
    if (gridContainer) gridContainer.style.display = 'none';
    if (tableContainer) tableContainer.style.display = 'block';
  }
}
window.switchTemplateViewMode = switchTemplateViewMode;

function filterTemplatesByKpi(kpiType) {
  document.querySelectorAll('.tmpl-kpi-card').forEach(c => c.classList.remove('active-filter'));
  const card = document.getElementById(`tmplcard-${kpiType}`);
  if (card) card.classList.add('active-filter');

  const statusSel = document.getElementById('tmpl-status-filter');
  const popSel = document.getElementById('tmpl-popularity-filter');
  const catSel = document.getElementById('tmpl-cat-filter');

  if (kpiType === 'total') {
    if (statusSel) statusSel.value = 'all';
    if (popSel) popSel.value = 'all';
    if (catSel) catSel.value = 'all';
    currentTemplateCategoryFilter = 'all';
  } else if (kpiType === 'active') {
    if (statusSel) statusSel.value = 'active';
  } else if (kpiType === 'popular') {
    if (popSel) popSel.value = 'popular';
  } else if (kpiType === 'categories') {
    window.location.hash = 'categories';
    switchView('categories');
    return;
  } else if (kpiType === 'requests' || kpiType === 'pending') {
    if (statusSel) statusSel.value = 'draft';
  }

  currentTemplatePage = 1;
  loadTemplates();
}
window.filterTemplatesByKpi = filterTemplatesByKpi;

function filterTemplatesByCategory(catKey) {
  currentTemplateCategoryFilter = catKey;
  const catSel = document.getElementById('tmpl-cat-filter');
  if (catSel) catSel.value = catKey === 'all' ? 'all' : catKey;
  currentTemplatePage = 1;
  loadTemplates();
}
window.filterTemplatesByCategory = filterTemplatesByCategory;

function filterTemplatesByTag(tag) {
  currentTemplateTagFilter = tag;
  const searchInput = document.getElementById('tmpl-search-input');
  if (searchInput) searchInput.value = tag;
  currentTemplatePage = 1;
  loadTemplates();
}
window.filterTemplatesByTag = filterTemplatesByTag;

function changeTemplatePage(page) {
  currentTemplatePage = page;
  loadTemplates();
}
window.changeTemplatePage = changeTemplatePage;

// Render custom SVG illustration banner for each blueprint theme
