  document.getElementById('mte-emoji').value = '📝';
  document.getElementById('mte-category-id').value = '1';
  document.getElementById('mte-task-type').value = 'online';
  document.getElementById('mte-complexity').value = 'beginner';
  document.getElementById('mte-budget').value = '200';
  document.getElementById('mte-duration').value = '20';
  document.getElementById('mte-delivery-hours').value = '24';
  document.getElementById('mte-short-desc').value = '';
  document.getElementById('mte-instructions').value = '';
  document.getElementById('mte-deliverables').value = '';
  document.getElementById('mte-skills').value = '';
  document.getElementById('mte-status').value = 'active';
