async function openEditTemplateModal(id) {
  try {
    const t = await api(`/api/admin/templates/${id}`);
    document.getElementById('mte-modal-title').textContent = `✏️ Edit Template: ${t.title}`;
    document.getElementById('mte-template-id').value = t.id;
    document.getElementById('mte-title').value = t.title || '';
    document.getElementById('mte-emoji').value = t.emoji || '📝';
    document.getElementById('mte-category-id').value = t.category_id || '1';
    document.getElementById('mte-task-type').value = t.task_type || 'online';
    document.getElementById('mte-complexity').value = t.complexity || 'beginner';
    document.getElementById('mte-budget').value = t.default_budget || 200;
    document.getElementById('mte-duration').value = t.duration_minutes || 20;
    document.getElementById('mte-delivery-hours').value = t.delivery_hours || 24;
    document.getElementById('mte-short-desc').value = t.short_desc || '';
    document.getElementById('mte-instructions').value = t.instructions || '';
    document.getElementById('mte-deliverables').value = Array.isArray(t.deliverables) ? t.deliverables.join('\n') : (t.deliverables || '');
    document.getElementById('mte-skills').value = t.skills || '';
    document.getElementById('mte-status').value = t.status || 'active';
    document.getElementById('mte-featured').checked = !!t.is_featured;

    openModal('modal-template-editor');
  } catch (err) {
    toast(`Failed to load template: ${err.message}`, 'error');
  }
}
window.openEditTemplateModal = openEditTemplateModal;

function autoGenTemplateSlug(title) {
  // auto slug helper
}
window.autoGenTemplateSlug = autoGenTemplateSlug;

async function handleSaveTemplate(e) {
  e.preventDefault();
  const id = document.getElementById('mte-template-id').value;
  const payload = {
    title: document.getElementById('mte-title').value.trim(),
    emoji: document.getElementById('mte-emoji').value.trim() || '📝',
    category_id: document.getElementById('mte-category-id').value,
    task_type: document.getElementById('mte-task-type').value,
    complexity: document.getElementById('mte-complexity').value,
    default_budget: Number(document.getElementById('mte-budget').value),
    duration_minutes: Number(document.getElementById('mte-duration').value),
    delivery_hours: Number(document.getElementById('mte-delivery-hours').value),
    short_desc: document.getElementById('mte-short-desc').value.trim(),
    instructions: document.getElementById('mte-instructions').value.trim(),
    deliverables: document.getElementById('mte-deliverables').value.trim(),
    skills: document.getElementById('mte-skills').value.trim(),
    status: document.getElementById('mte-status').value,
    is_featured: document.getElementById('mte-featured').checked
  };

  try {
    if (id) {
      await api(`/api/admin/templates/${id}`, { method: 'PUT', body: payload });
      toast('Template updated successfully!', 'success');
    } else {
      await api('/api/admin/templates', { method: 'POST', body: payload });
      toast(`New template "${payload.title}" created!`, 'success');
    }
    closeModal('modal-template-editor');
    loadTemplates();
  } catch (err) {
    toast(`Failed to save template: ${err.message}`, 'error');
  }
}
window.handleSaveTemplate = handleSaveTemplate;

