async function handleLaunchTaskFromTemplate(e) {
  e.preventDefault();
  const templateId = document.getElementById('mtl-template-id').value;
  const title = document.getElementById('mtl-task-title').value.trim();
  const budget = Number(document.getElementById('mtl-task-budget').value);
  const clientId = Number(document.getElementById('mtl-client-select').value) || 10;
  const description = document.getElementById('mtl-task-desc').value.trim();
  const isUrgent = document.getElementById('mtl-is-urgent').checked;

  try {
    const t = await api(`/api/admin/templates/${templateId}`);
    await api('/api/admin/tasks', {
      method: 'POST',
      body: {
        title,
        description,
        budget,
        category_id: t.category_id || 1,
        client_id: clientId,
        task_type: t.task_type || 'online',
        duration_minutes: t.duration_minutes || 30,
        is_urgent: isUrgent ? 1 : 0,
        status: 'open'
      }
    });

    toast(`🚀 Live task "${title}" published on marketplace!`, 'success');
    closeModal('modal-template-launcher');
    loadTemplates();
    loadOverview();
  } catch (err) { toast(err.message, 'error'); }
}
window.handleLaunchTaskFromTemplate = handleLaunchTaskFromTemplate;

async function executeTemplateBulk(action) {
  const checked = Array.from(document.querySelectorAll('.chk-tmpl-row:checked')).map(c => Number(c.value));
  if (!checked.length) return toast('No templates selected', 'warning');

  if (action === 'delete') {
    if (!confirm(`Delete ${checked.length} selected templates permanently?`)) return;
  }

  try {
    const res = await api('/api/admin/templates/bulk', {
      method: 'POST',
      body: { ids: checked, action }
    });
    toast(`Bulk ${action.toUpperCase()} applied to ${res.affectedCount} templates!`, 'success');
    clearTemplateSelection();
    loadTemplates();
  } catch (err) { toast(err.message, 'error'); }
}
window.executeTemplateBulk = executeTemplateBulk;

function triggerBulkTemplates(action) {
  executeTemplateBulk(action);
}
window.triggerBulkTemplates = triggerBulkTemplates;

async function exportTemplatesData(format) {
  try {
    const res = await api('/api/admin/templates');
    const items = res.items || [];
    if (format === 'json') {
      const dataStr = 'data:text/json;charset=utf-8,' + encodeURIComponent(JSON.stringify(items, null, 2));
      const a = document.createElement('a');
      a.href = dataStr;
      a.download = `xtraearn_templates_export_${Date.now()}.json`;
      a.click();
    } else {
      const headers = ['ID', 'Title', 'Category', 'Type', 'Complexity', 'Default Budget (BDT)', 'Duration (Mins)', 'SLA (Hours)', 'Usage Count', 'Rating', 'Status'];
      const rows = items.map(t => [
        t.id, `"${t.title}"`, `"${t.category_name}"`, t.task_type, t.complexity, t.default_budget, t.duration_minutes, t.delivery_hours, t.usage_count, t.rating, t.status
      ]);
      const csvContent = 'data:text/csv;charset=utf-8,' + [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
      const a = document.createElement('a');
      a.href = encodeURI(csvContent);
      a.download = `xtraearn_templates_export_${Date.now()}.csv`;
      a.click();
    }
    toast(`Exported ${items.length} templates as ${format.toUpperCase()}`, 'success');
  } catch (err) { toast(err.message, 'error'); }
}
window.exportTemplatesData = exportTemplatesData;

/* ---------- 16. DISPUTES MEDIATION ---------- */
let disputesDataCache = [];

async function loadDisputesTable() {
  const tbody = document.getElementById('disputes-table-body');
  if (!tbody) return;
  tbody.innerHTML = '<tr><td colspan="7" class="loading-td">Loading dispute tickets...</td></tr>';
  try {
    const res = await api('/api/admin/disputes');
    disputesDataCache = res.items || [];
    if (disputesDataCache.length === 0) {
      tbody.innerHTML = '<tr><td colspan="7" style="text-align:center;padding:24px;color:#94A3B8">No active dispute cases.</td></tr>';
      return;
    }
    tbody.innerHTML = disputesDataCache.map(d => `
      <tr>
        <td><b style="color:#10B981">${escapeHtml(d.ticket_code)}</b></td>
        <td>${escapeHtml(d.task_title)}</td>
        <td>${escapeHtml(d.client_name)}</td>
        <td>${escapeHtml(d.worker_name)}</td>
        <td><small style="color:#94A3B8">${escapeHtml(d.reason)}</small></td>
        <td style="font-weight:700;color:#10B981">$${d.amount}</td>
        <td>
          <button class="btn btn-purple btn-sm" onclick="inspectDispute(${d.id})">⚖️ Arbitrate</button>
        </td>
      </tr>
    `).join('');
  } catch (err) { tbody.innerHTML = `<tr><td colspan="7" style="color:#EF4444">${err.message}</td></tr>`; }
}

function inspectDispute(id) {
  const d = disputesDataCache.find(item => item.id === id);
  if (!d) return;
  document.getElementById('disp-resolve-id').value = d.id;
  document.getElementById('disp-modal-title').textContent = `${d.ticket_code} — ${d.task_title}`;
  document.getElementById('disp-modal-amount').textContent = `$${d.amount}.00 Held in Escrow`;
  document.getElementById('disp-modal-reason').textContent = `Reason: ${d.reason} | Client: ${d.client_name} | Worker: ${d.worker_name}`;
  openModal('modal-dispute-resolve');
}

async function handleResolveDispute(e) {
  e.preventDefault();
  const id = document.getElementById('disp-resolve-id').value;
  const resolution = document.getElementById('disp-resolve-action').value;
  const note = document.getElementById('disp-resolve-note').value.trim();

  try {
    await api(`/api/admin/disputes/${id}/resolve`, { method: 'POST', body: { resolution, note } });
    closeModal('modal-dispute-resolve');
    toast(`⚖️ Dispute resolved: ${resolution.replace('_', ' ')} executed!`, 'success');
    loadDisputesTable();
  } catch (err) { toast(err.message, 'error'); }
}

