/* ---------- 19. NOTIFICATION AUTOMATION & BROADCAST SUITE ---------- */
let notifSearchTimeout = null;
let notifTemplatesCache = [];

async function loadNotificationsTable() {
  const tbody = document.getElementById('notifications-table-body');
  if (!tbody) return;

  const q = document.getElementById('notif-search-input')?.value.trim() || '';
  const category = document.getElementById('notif-category-filter')?.value || 'all';
  const channel = document.getElementById('notif-channel-filter')?.value || 'all';
  const status = document.getElementById('notif-status-filter')?.value || 'all';

  tbody.innerHTML = '<tr><td colspan="6" class="loading-td">Loading notification automation templates...</td></tr>';

  try {
    const query = new URLSearchParams({ q, category, channel, status });
    const res = await api(`/api/admin/notifications?${query.toString()}`);
    const items = res.items || [];
    const metrics = res.metrics || {};
    notifTemplatesCache = items;

    // Update KPI Metric Strip
    setElText('notif-kpi-total', metrics.totalTemplates || items.length);
    setElText('notif-kpi-active', `${metrics.activeCount || items.length} Active`);
    setElText('notif-kpi-email', `${metrics.emailChannels || items.length} Triggers`);
    setElText('notif-kpi-sms', `${metrics.smsChannels || 6} Alerts`);
    setElText('notif-kpi-push', `${metrics.pushChannels || 8} Feeds`);
    setElText('notif-kpi-sla', metrics.avgDeliveryRate || '99.8%');

    if (items.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="6" style="text-align:center;padding:36px;color:#94A3B8">
            <div style="font-size:2rem;margin-bottom:6px">🔕</div>
            <b>No notification templates found matching current filters.</b>
            <div style="margin-top:6px"><button class="btn btn-outline-light btn-sm" onclick="resetNotifFilters()">Reset Filters</button></div>
          </td>
        </tr>
      `;
      return;
    }

    tbody.innerHTML = items.map(n => {
      const channelPills = [];
      if (n.channel_email) channelPills.push('<span class="adm-status-chip blue" style="font-size:0.68rem">✉️ Email</span>');
      if (n.channel_sms) channelPills.push('<span class="adm-status-chip amber" style="font-size:0.68rem">📱 SMS</span>');
      if (n.channel_push) channelPills.push('<span class="adm-status-chip purple" style="font-size:0.68rem">🔔 Push</span>');
      if (n.channel_inapp) channelPills.push('<span class="adm-status-chip green" style="font-size:0.68rem">📥 Feed</span>');

      const varPills = (n.variables || []).slice(0, 4).map(v => 
        `<code style="background:rgba(255,255,255,0.06);color:#38BDF8;padding:1px 5px;border-radius:4px;font-size:0.7rem;margin-right:3px">{{${escapeHtml(v)}}}</code>`
      ).join('');

      const isPaused = n.status === 'paused';
      const statusBadge = isPaused ? 
        '<span class="adm-status-chip red" style="font-size:0.7rem">⏸️ PAUSED</span>' : 
        '<span class="adm-status-chip green" style="font-size:0.7rem">🟢 ACTIVE</span>';

      return `
        <tr style="${isPaused ? 'opacity:0.65;background:rgba(239,68,68,0.02)' : ''}">
          <td>
            <div style="display:flex;align-items:center;gap:6px">
              <span class="adm-tag" style="font-family:monospace;font-weight:700;color:#34D399">${escapeHtml(n.trigger)}</span>
            </div>
            <b style="color:#fff;display:block;margin-top:3px;font-size:0.88rem">${escapeHtml(n.title)}</b>
            <small style="color:#64748B;text-transform:capitalize">Scope: ${escapeHtml(n.category || 'general')}</small>
          </td>
          <td>
            <div style="display:flex;gap:4px;flex-wrap:wrap">
              ${channelPills.join('') || '<span style="color:#64748B">None</span>'}
            </div>
          </td>
          <td style="max-width:280px">
            <div style="font-size:0.84rem;color:#E2E8F0;font-weight:600;margin-bottom:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis" title="${escapeHtml(n.subject)}">
              ${escapeHtml(n.subject)}
            </div>
            <div>${varPills}</div>
          </td>
          <td>
            <div style="font-size:0.8rem;color:#10B981;font-weight:700">✓ ${n.delivery_rate || '100%'} Delivery</div>
            <small style="color:#94A3B8">${Number(n.sent_count || 0).toLocaleString()} sent • Open ${n.open_rate || '85%'}</small>
          </td>
          <td>
            ${statusBadge}
          </td>
          <td>
            <div class="adm-action-btns">
              <button class="adm-btn-act" onclick="openPreviewNotifModal(${n.id})" title="Live Responsive Preview" style="background:#1E1B4B;border-color:#6366F1;color:#818CF8">👁️</button>
              <button class="adm-btn-act" onclick="openTestNotifModal(${n.id})" title="Send Test Dispatch" style="color:#FBBF24;border-color:rgba(245,158,11,0.3)">🧪</button>
              <button class="adm-btn-act" onclick="openEditNotifModal(${n.id})" title="Edit Template & HTML" style="color:#38BDF8;border-color:rgba(56,189,248,0.3)">✏️</button>
              <button class="adm-btn-act" onclick="toggleNotifStatus(${n.id})" title="${isPaused ? 'Resume Automation' : 'Pause Automation'}">
                ${isPaused ? '▶️' : '⏸️'}
              </button>
              <button class="adm-btn-act danger" onclick="deleteNotifTemplate(${n.id})" title="Delete Template">🗑️</button>
            </div>
          </td>
        </tr>
      `;
    }).join('');

  } catch (err) {
    tbody.innerHTML = `<tr><td colspan="6" class="error-td">Error loading notifications: ${escapeHtml(err.message)}</td></tr>`;
  }
}

window.resetNotifFilters = function() {
  const s = document.getElementById('notif-search-input');
  if (s) s.value = '';
  const c = document.getElementById('notif-category-filter');
  if (c) c.value = 'all';
  const ch = document.getElementById('notif-channel-filter');
  if (ch) ch.value = 'all';
  const st = document.getElementById('notif-status-filter');
  if (st) st.value = 'all';
  loadNotificationsTable();
};

window.openCreateNotifModal = function() {
  document.getElementById('mne-modal-title').textContent = '✉️ Create Notification Template';
  document.getElementById('mne-modal-sub').textContent = 'Define a new trigger event and multi-channel notification template.';
  document.getElementById('mne-id').value = '';
  document.getElementById('mne-trigger').value = '';
  document.getElementById('mne-trigger').disabled = false;
  document.getElementById('mne-category').value = 'tasks';
  document.getElementById('mne-title').value = '';
  document.getElementById('mne-status').value = 'active';
  document.getElementById('mne-chan-email').checked = true;
  document.getElementById('mne-chan-sms').checked = false;
  document.getElementById('mne-chan-push').checked = true;
  document.getElementById('mne-chan-inapp').checked = true;
  document.getElementById('mne-subject').value = 'Notification: {{task_title}} - XtraEarn';
  document.getElementById('mne-body-html').value = '<p>Hello <b>{{user_name}}</b>,</p><p>We have an important update regarding <b>{{task_title}}</b>.</p><p>Amount: <b>৳{{amount}}</b></p>';
  document.getElementById('mne-body-sms').value = '[XtraEarn] Update on {{task_title}}. Check xtraearn.com';
  openModal('modal-notif-editor');
};

window.openEditNotifModal = async function(id) {
  try {
    const res = await api(`/api/admin/notifications/${id}`);
    const n = res.item || notifTemplatesCache.find(x => x.id === id);
    if (!n) return toast('Template not found', 'error');

    document.getElementById('mne-modal-title').textContent = `✉️ Edit: ${n.title}`;
    document.getElementById('mne-modal-sub').textContent = `Trigger: ${n.trigger} · ID #${n.id}`;
    document.getElementById('mne-id').value = n.id;
    document.getElementById('mne-trigger').value = n.trigger;
    document.getElementById('mne-trigger').disabled = true;
    document.getElementById('mne-category').value = n.category || 'tasks';
    document.getElementById('mne-title').value = n.title;
    document.getElementById('mne-status').value = n.status || 'active';
    document.getElementById('mne-chan-email').checked = Boolean(n.channel_email);
    document.getElementById('mne-chan-sms').checked = Boolean(n.channel_sms);
    document.getElementById('mne-chan-push').checked = Boolean(n.channel_push);
    document.getElementById('mne-chan-inapp').checked = Boolean(n.channel_inapp);
    document.getElementById('mne-subject').value = n.subject;
    document.getElementById('mne-body-html').value = n.body_html || '';
    document.getElementById('mne-body-sms').value = n.body_sms || '';

    openModal('modal-notif-editor');
  } catch (err) {
    toast(err.message, 'error');
  }
};

window.insertNotifToken = function(token) {
  const textarea = document.getElementById('mne-body-html');
  if (!textarea) return;
  const start = textarea.selectionStart;
  const end = textarea.selectionEnd;
  const text = textarea.value;
  textarea.value = text.substring(0, start) + token + text.substring(end);
  textarea.focus();
  textarea.selectionStart = textarea.selectionEnd = start + token.length;
};

window.handleNotifEditorSubmit = async function(e) {
  e.preventDefault();
  const id = document.getElementById('mne-id').value;
  const payload = {
    trigger: document.getElementById('mne-trigger').value.trim(),
    category: document.getElementById('mne-category').value,
    title: document.getElementById('mne-title').value.trim(),
    status: document.getElementById('mne-status').value,
    channel_email: document.getElementById('mne-chan-email').checked ? 1 : 0,
    channel_sms: document.getElementById('mne-chan-sms').checked ? 1 : 0,
    channel_push: document.getElementById('mne-chan-push').checked ? 1 : 0,
    channel_inapp: document.getElementById('mne-chan-inapp').checked ? 1 : 0,
    subject: document.getElementById('mne-subject').value.trim(),
    body_html: document.getElementById('mne-body-html').value.trim(),
    body_sms: document.getElementById('mne-body-sms').value.trim()
  };

  try {
    if (id) {
      await api(`/api/admin/notifications/${id}`, { method: 'PUT', body: payload });
      toast('Notification template updated successfully!', 'success');
    } else {
      await api('/api/admin/notifications', { method: 'POST', body: payload });
      toast('New notification template registered!', 'success');
    }
    closeModal('modal-notif-editor');
    loadNotificationsTable();
  } catch (err) {
    toast(err.message, 'error');
  }
};

