/* ---------- 20. SUPPORT TICKETS ---------- */
let supportTicketsCache = [];

async function loadSupportTicketsTable() {
  const tbody = document.getElementById('support-table-body');
  if (!tbody) return;
  try {
    const res = await api('/api/admin/support');
    supportTicketsCache = res.items || [];
    tbody.innerHTML = supportTicketsCache.map(t => `
      <tr>
        <td><b style="color:#818CF8">${escapeHtml(t.ticket_code)}</b></td>
        <td>
          <b>${escapeHtml(t.user_name)}</b>
          <small style="display:block;color:#94A3B8">${escapeHtml(t.user_email)}</small>
        </td>
        <td>
          <b>${escapeHtml(t.subject)}</b>
          <span class="adm-status-chip blue" style="margin-left:6px">${t.category}</span>
        </td>
        <td><span class="adm-status-chip ${t.priority === 'High' ? 'red' : 'amber'}">${t.priority}</span></td>
        <td><span class="adm-status-chip ${t.status === 'open' ? 'amber' : t.status === 'answered' ? 'green' : 'blue'}">${t.status.toUpperCase()}</span></td>
        <td>${t.created_at}</td>
        <td><button class="btn btn-green btn-sm" onclick="openSupportReplyModal(${t.id})">💬 Reply</button></td>
      </tr>
    `).join('');
  } catch (err) { tbody.innerHTML = `<tr><td colspan="7" style="color:#EF4444">${err.message}</td></tr>`; }
}

function openSupportReplyModal(id) {
  const t = supportTicketsCache.find(item => item.id === id);
  if (!t) return;
  document.getElementById('sup-ticket-id').value = t.id;
  document.getElementById('sup-modal-sub').textContent = `${t.ticket_code} — ${t.subject} (${t.user_name})`;

  const history = document.getElementById('sup-modal-history');
  history.innerHTML = t.replies.map(r => `
    <div style="margin-bottom:8px;padding:6px 10px;border-radius:6px;background:${r.sender === 'Super Admin' ? 'rgba(99,102,241,0.15)' : 'rgba(255,255,255,0.05)'}">
      <b style="color:${r.sender === 'Super Admin' ? '#818CF8' : '#fff'};font-size:0.8rem">${r.sender}</b> <small style="color:#64748B">${r.time}</small>
      <p style="margin:4px 0 0;font-size:0.82rem;color:#E2E8F0">${escapeHtml(r.text)}</p>
    </div>
  `).join('');

  openModal('modal-support-reply');
}

async function handleSupportReply(e) {
  e.preventDefault();
  const id = document.getElementById('sup-ticket-id').value;
  const text = document.getElementById('sup-reply-text').value.trim();

  try {
    await api(`/api/admin/support/${id}/reply`, { method: 'POST', body: { text } });
    closeModal('modal-support-reply');
    document.getElementById('sup-reply-text').value = '';
    toast('Support ticket reply sent!', 'success');
    loadSupportTicketsTable();
  } catch (err) { toast(err.message, 'error'); }
}

