/* ================= 29. CORPORATE BUSINESSES & B2B MANAGEMENT CONTROLLER ================= */
let currentBusinessesList = [];
let selectedBusinessIds = new Set();
let currentBizFilterTab = 'all';
let currentBizViewMode = 'cards';
let activeInspectedBiz = null;
let bizSearchTimer = null;

async function loadBusinesses() {
  await Promise.all([
    fetchBusinessesKPIs(),
    fetchBusinessesList()
  ]);
  setupBusinessesListeners();
}

async function fetchBusinessesKPIs() {
  try {
    const kpis = await api('/api/admin/businesses/kpis');
    if (!kpis) return;
    renderBusinessesKPIs(kpis);
  } catch (err) {
    console.error('Failed to load businesses KPIs:', err);
  }
}

function renderBusinessesKPIs(kpis) {
  setElText('kpi-biz-total', kpis.total_businesses || 0);
  setElText('kpi-biz-active-sub', `${kpis.active_businesses || 0} Active · ${kpis.pending_verification || 0} In Verification`);
  setElText('kpi-biz-enterprise', kpis.enterprise_vip || 0);
  setElText('kpi-biz-spend', `৳${formatNumberCompact(kpis.total_spend || 0)}`);
  setElText('kpi-biz-escrow', `৳${formatNumberCompact(kpis.total_escrow_deposit || 0)} Escrow Deposits`);
  setElText('kpi-biz-jobs', kpis.active_tasks_count || 0);
  setElText('kpi-biz-credit', `৳${formatNumberCompact(kpis.total_credit_allocated || 0)}`);
  const utilPct = kpis.total_credit_allocated > 0 ? Math.round((kpis.total_credit_used / kpis.total_credit_allocated) * 100) : 0;
  setElText('kpi-biz-credit-used', `৳${formatNumberCompact(kpis.total_credit_used || 0)} Utilized (${utilPct}%)`);

  setElText('biz-badge-all', kpis.total_businesses || 0);
  setElText('biz-badge-enterprise', kpis.enterprise_vip || 0);
  setElText('biz-badge-smb', kpis.smb_growth || 0);
  setElText('biz-badge-credit', (currentBusinessesList.filter(b => (b.credit_limit || 0) > 0)).length || 15);
  setElText('biz-badge-pending', kpis.pending_verification || 0);
}

function formatNumberCompact(num) {
  if (num >= 1000000) return (num / 1000000).toFixed(1) + 'M';
  if (num >= 1000) return (num / 1000).toFixed(0) + 'K';
  return String(num);
}

async function fetchBusinessesList() {
  try {
    const q = document.getElementById('biz-search-input')?.value || '';
    const industry = document.getElementById('biz-industry-filter')?.value || 'all';
    const accountTier = document.getElementById('biz-tier-filter')?.value || 'all';
    const verificationStatus = document.getElementById('biz-verify-filter')?.value || 'all';
    const status = document.getElementById('biz-status-filter')?.value || 'all';
    const sortBy = document.getElementById('biz-sort-filter')?.value || 'spend_high';

    let url = `/admin/businesses?sortBy=${sortBy}`;
    if (q) url += `&q=${encodeURIComponent(q)}`;
    if (industry && industry !== 'all') url += `&industry=${encodeURIComponent(industry)}`;
    if (accountTier && accountTier !== 'all') url += `&accountTier=${encodeURIComponent(accountTier)}`;
    if (verificationStatus && verificationStatus !== 'all') url += `&verificationStatus=${encodeURIComponent(verificationStatus)}`;
    if (status && status !== 'all') url += `&status=${encodeURIComponent(status)}`;
    if (currentBizFilterTab && currentBizFilterTab !== 'all') url += `&flag=${encodeURIComponent(currentBizFilterTab)}`;

    const res = await api(url);
    currentBusinessesList = res.items || [];

    if (currentBizViewMode === 'cards') {
      renderBusinessesCards(currentBusinessesList);
    } else {
      renderBusinessesTable(currentBusinessesList);
    }
  } catch (err) {
    console.error('Failed to list businesses:', err);
  }
}

function renderBusinessesCards(items) {
  const container = document.getElementById('businesses-cards-grid');
  const tableWrap = document.getElementById('businesses-table-wrap');
  if (!container) return;

  container.style.display = 'grid';
  if (tableWrap) tableWrap.style.display = 'none';

  if (!items || !items.length) {
    container.innerHTML = `
      <div style="grid-column:1/-1;text-align:center;padding:48px;background:#0F172A;border-radius:14px;border:1px dashed rgba(255,255,255,0.1)">
        <div style="font-size:2.5rem;margin-bottom:10px">🏢</div>
        <h4 style="color:#fff;margin:0 0 6px">No Corporate Clients Found</h4>
        <p style="color:#94A3B8;font-size:0.84rem;margin:0 0 16px">Try changing your search terms or filters</p>
        <button class="btn btn-purple btn-sm" onclick="openCreateBusinessModal()">+ Onboard Business Client</button>
      </div>
    `;
    return;
  }

  container.innerHTML = items.map(b => {
    const isChecked = selectedBusinessIds.has(b.id);
    const tierBadge = b.account_tier === 'enterprise_vip'
      ? `<span class="adm-badge purple" style="font-size:0.7rem;font-weight:700">👑 VIP Enterprise</span>`
      : b.account_tier === 'growth'
      ? `<span class="adm-badge blue" style="font-size:0.7rem">🚀 Growth</span>`
      : `<span class="adm-badge" style="font-size:0.7rem;background:rgba(255,255,255,0.1);color:#CBD5E1">Standard</span>`;

    const statusBadge = b.status === 'active'
      ? `<span class="adm-badge green" style="font-size:0.7rem">🟢 Active</span>`
      : b.status === 'pending_verification'
      ? `<span class="adm-badge orange" style="font-size:0.7rem">⏳ Pending</span>`
      : b.status === 'postpaid_hold'
      ? `<span class="adm-badge red" style="font-size:0.7rem">⏸️ Hold</span>`
      : `<span class="adm-badge red" style="font-size:0.7rem">🔴 Suspended</span>`;

    const verifyIcon = b.is_verified ? `<span title="Verified License" style="color:#10B981;font-size:0.85rem">✅</span>` : `<span title="Unverified" style="color:#F59E0B;font-size:0.85rem">⏳</span>`;

    const creditLimitFmt = b.credit_limit > 0 ? `৳${(b.credit_limit).toLocaleString()}` : 'Prepaid Only';
    const spendFmt = `৳${(b.total_spend || 0).toLocaleString()}`;

    return `
      <div class="adm-card" style="background:#0F172A;border:1px solid rgba(255,255,255,0.08);border-radius:16px;padding:18px;display:flex;flex-direction:column;justify-content:space-between;position:relative;transition:all 0.2s">
        <div>
          <!-- Header: Checkbox, Avatar, Name & Tier -->
          <div style="display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:12px">
            <div style="display:flex;align-items:center;gap:10px">
              <input type="checkbox" ${isChecked ? 'checked' : ''} onchange="toggleBusinessSelect(${b.id}, this.checked)">
              <div style="width:40px;height:40px;border-radius:10px;background:${b.brand_color || '#6366F1'};color:#fff;display:flex;align-items:center;justify-content:center;font-size:1.25rem;font-weight:700">
                ${b.logo_icon || '🏢'}
              </div>
              <div>
                <div style="display:flex;align-items:center;gap:6px">
                  <h4 style="color:#fff;margin:0;font-size:0.96rem;font-weight:700">${escapeHtml(b.company_name)}</h4>
                  ${verifyIcon}
                </div>
                <div style="color:#94A3B8;font-size:0.75rem;margin-top:1px">${escapeHtml(b.industry || 'Business')} · ${escapeHtml(b.district || 'Dhaka')}</div>
              </div>
            </div>
            <div>${tierBadge}</div>
          </div>

          <!-- Legal & Contact Summary -->
          <div style="background:#1E293B;padding:10px 12px;border-radius:10px;font-size:0.78rem;margin-bottom:12px;display:flex;flex-direction:column;gap:4px">
            <div style="display:flex;justify-content:space-between">
              <span style="color:#94A3B8">Contact Rep:</span>
              <span style="color:#E2E8F0;font-weight:600">${escapeHtml(b.contact_person?.name || 'Representative')}</span>
            </div>
            <div style="display:flex;justify-content:space-between">
              <span style="color:#94A3B8">Work Email:</span>
              <span style="color:#60A5FA">${escapeHtml(b.contact_person?.email || 'N/A')}</span>
            </div>
            <div style="display:flex;justify-content:space-between">
              <span style="color:#94A3B8">TIN/BIN:</span>
              <span style="color:#34D399;font-family:monospace">${escapeHtml(b.bin_tin?.split('·')[0] || 'Registered')}</span>
            </div>
          </div>

          <!-- Financial Snapshot & Active Jobs -->
          <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;text-align:center;background:#111827;padding:10px 6px;border-radius:10px;margin-bottom:14px">
            <div>
              <div style="font-size:0.68rem;color:#94A3B8">Total Spend</div>
              <div style="font-size:0.86rem;font-weight:800;color:#10B981">${spendFmt}</div>
            </div>
            <div>
              <div style="font-size:0.68rem;color:#94A3B8">Credit Line</div>
              <div style="font-size:0.86rem;font-weight:800;color:#FBBF24">${creditLimitFmt}</div>
            </div>
            <div>
              <div style="font-size:0.68rem;color:#94A3B8">Active Jobs</div>
              <div style="font-size:0.86rem;font-weight:800;color:#38BDF8">${b.active_tasks_count || 0} Live</div>
            </div>
          </div>
        </div>

        <!-- Footer Actions -->
        <div style="display:flex;align-items:center;justify-content:space-between;border-top:1px solid rgba(255,255,255,0.06);padding-top:12px">
          <div>${statusBadge}</div>
          <div style="display:flex;gap:6px">
            <button class="btn btn-outline-light btn-sm" onclick="openBusinessCreditModal(${b.id})" title="Credit & Escrow" style="padding:4px 8px;font-size:0.75rem">💳</button>
            <button class="btn btn-outline-light btn-sm" onclick="openEditBusinessModal(${b.id})" title="Edit Business" style="padding:4px 8px;font-size:0.75rem">✏️</button>
            <button class="btn btn-purple btn-sm" onclick="viewBusinessDetails(${b.id})" style="padding:5px 12px;font-size:0.76rem;font-weight:700">👁️ 360° Inspect</button>
          </div>
        </div>
      </div>
    `;
  }).join('');
}

function renderBusinessesTable(items) {
  const container = document.getElementById('businesses-cards-grid');
  const tableWrap = document.getElementById('businesses-table-wrap');
  const tbody = document.getElementById('businesses-table-body');
  if (!tableWrap || !tbody) return;

  if (container) container.style.display = 'none';
  tableWrap.style.display = 'block';

  if (!items || !items.length) {
    tbody.innerHTML = `<tr><td colspan="9" style="text-align:center;padding:32px;color:#94A3B8">No corporate businesses matching filter criteria.</td></tr>`;
    return;
  }

  tbody.innerHTML = items.map(b => {
    const isChecked = selectedBusinessIds.has(b.id);
    const tierBadge = b.account_tier === 'enterprise_vip'
      ? `<span class="adm-badge purple" style="font-size:0.68rem">👑 VIP</span>`
      : `<span class="adm-badge blue" style="font-size:0.68rem">${b.account_tier}</span>`;

    const statusBadge = b.status === 'active'
      ? `<span class="adm-badge green" style="font-size:0.68rem">Active</span>`
      : `<span class="adm-badge orange" style="font-size:0.68rem">${b.status}</span>`;

    return `
      <tr>
        <td><input type="checkbox" ${isChecked ? 'checked' : ''} onchange="toggleBusinessSelect(${b.id}, this.checked)"></td>
        <td>
          <div style="display:flex;align-items:center;gap:8px">
            <span style="font-size:1.1rem">${b.logo_icon || '🏢'}</span>
            <div>
              <b style="color:#fff">${escapeHtml(b.company_name)}</b>
              <div style="font-size:0.74rem;color:#94A3B8;font-family:monospace">${b.company_code} · ${escapeHtml(b.legal_name || '')}</div>
            </div>
          </div>
        </td>
        <td>
          <div style="font-weight:600;color:#CBD5E1">${escapeHtml(b.industry || 'General')}</div>
          <small style="color:#94A3B8">${escapeHtml(b.district || 'Dhaka')}</small>
        </td>
        <td>
          <div style="font-weight:600;color:#fff">${escapeHtml(b.contact_person?.name || '')}</div>
          <div style="font-size:0.74rem;color:#60A5FA">${escapeHtml(b.contact_person?.email || '')}</div>
        </td>
        <td>
          <div>${tierBadge}</div>
          <small style="color:#94A3B8">${escapeHtml(b.sla_plan?.split(' ')[0] || 'Standard')}</small>
        </td>
        <td>
          <b style="color:#FBBF24">৳${(b.credit_limit || 0).toLocaleString()}</b>
          <div style="font-size:0.72rem;color:#10B981">৳${(b.escrow_deposit_balance || 0).toLocaleString()} Escrow</div>
        </td>
        <td>
          <b style="color:#10B981">৳${(b.total_spend || 0).toLocaleString()}</b>
          <div style="font-size:0.72rem;color:#38BDF8">${b.total_tasks_posted || 0} tasks (${b.active_tasks_count || 0} live)</div>
        </td>
        <td>
          ${b.is_verified ? '<span class="adm-badge green" style="font-size:0.68rem">Verified</span>' : '<span class="adm-badge orange" style="font-size:0.68rem">Pending</span>'}
          <div style="margin-top:4px">${statusBadge}</div>
        </td>
        <td style="text-align:right;white-space:nowrap">
          <button class="btn btn-outline-light btn-sm" onclick="openBusinessCreditModal(${b.id})" title="Credit Limit" style="padding:4px 8px">💳</button>
          <button class="btn btn-outline-light btn-sm" onclick="openEditBusinessModal(${b.id})" title="Edit" style="padding:4px 8px">✏️</button>
          <button class="btn btn-purple btn-sm" onclick="viewBusinessDetails(${b.id})" style="padding:4px 10px;font-weight:700">👁️</button>
        </td>
      </tr>
    `;
  }).join('');
}

function setupBusinessesListeners() {
  // Segmented Tabs
  document.querySelectorAll('#biz-segment-tabs .adm-tab-btn').forEach(btn => {
    btn.onclick = () => {
      document.querySelectorAll('#biz-segment-tabs .adm-tab-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      currentBizFilterTab = btn.getAttribute('data-biz-tab') || 'all';
      fetchBusinessesList();
    };
  });

  // Search input debounce
  const searchInp = document.getElementById('biz-search-input');
  if (searchInp) {
    searchInp.oninput = () => {
      clearTimeout(bizSearchTimer);
      bizSearchTimer = setTimeout(() => fetchBusinessesList(), 250);
    };
  }

  // Filter dropdowns
  ['biz-industry-filter', 'biz-tier-filter', 'biz-verify-filter', 'biz-status-filter', 'biz-sort-filter'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.onchange = () => fetchBusinessesList();
  });

  // View switchers
  const btnCards = document.getElementById('btn-biz-view-cards');
  const btnTable = document.getElementById('btn-biz-view-table');

  if (btnCards) {
    btnCards.onclick = () => {
      currentBizViewMode = 'cards';
      btnCards.classList.add('active');
      btnTable?.classList.remove('active');
      renderBusinessesCards(currentBusinessesList);
    };
  }
  if (btnTable) {
    btnTable.onclick = () => {
      currentBizViewMode = 'table';
      btnTable.classList.add('active');
      btnCards?.classList.remove('active');
      renderBusinessesTable(currentBusinessesList);
    };
  }
}

function toggleBusinessSelect(id, checked) {
  if (checked) selectedBusinessIds.add(id);
  else selectedBusinessIds.delete(id);
  updateBusinessesBulkBar();
}

function toggleAllBusinessCheckboxes(checked) {
  if (checked) {
    currentBusinessesList.forEach(b => selectedBusinessIds.add(b.id));
  } else {
    selectedBusinessIds.clear();
  }
  updateBusinessesBulkBar();
  if (currentBizViewMode === 'cards') renderBusinessesCards(currentBusinessesList);
  else renderBusinessesTable(currentBusinessesList);
}

function updateBusinessesBulkBar() {
  const bar = document.getElementById('businesses-bulk-bar');
  const countEl = document.getElementById('biz-selected-count');
  if (!bar || !countEl) return;

  if (selectedBusinessIds.size > 0) {
    bar.style.display = 'flex';
    countEl.textContent = selectedBusinessIds.size;
  } else {
    bar.style.display = 'none';
  }
}

function deselectAllBusinesses() {
  selectedBusinessIds.clear();
  updateBusinessesBulkBar();
  if (currentBizViewMode === 'cards') renderBusinessesCards(currentBusinessesList);
  else renderBusinessesTable(currentBusinessesList);
}

function openCreateBusinessModal() {
  document.getElementById('form-create-business')?.reset();
  document.getElementById('biz-edit-id').value = '';
  document.getElementById('modal-biz-title').textContent = '🏢 Onboard Corporate Business Client';
  openModal('modal-create-business');
}

async function openEditBusinessModal(id) {
  try {
    const business = await api(`/admin/businesses/${id}`);
    if (!business) return toast('Business not found', 'error');

    document.getElementById('biz-edit-id').value = business.id;
    document.getElementById('modal-biz-title').textContent = `✏️ Edit ${business.company_name}`;
    document.getElementById('mbiz-name').value = business.company_name || '';
    document.getElementById('mbiz-color').value = business.brand_color || '#6366F1';
    document.getElementById('mbiz-icon').value = business.logo_icon || '🏢';
    document.getElementById('mbiz-legal-name').value = business.legal_name || '';
    document.getElementById('mbiz-industry').value = business.industry || 'E-Commerce & Retail';
    document.getElementById('mbiz-bin-tin').value = business.bin_tin || '';
    document.getElementById('mbiz-trade-license').value = business.trade_license || '';
    document.getElementById('mbiz-contact-name').value = business.contact_person?.name || '';
    document.getElementById('mbiz-contact-email').value = business.contact_person?.email || '';
    document.getElementById('mbiz-contact-desig').value = business.contact_person?.designation || '';
    document.getElementById('mbiz-contact-phone').value = business.contact_person?.phone || '';
    document.getElementById('mbiz-district').value = business.district || 'Dhaka';
    document.getElementById('mbiz-address').value = business.address || '';
    document.getElementById('mbiz-tier').value = business.account_tier || 'standard';
    document.getElementById('mbiz-credit-limit').value = business.credit_limit || 0;
    document.getElementById('mbiz-escrow-balance').value = business.escrow_deposit_balance || 0;
    document.getElementById('mbiz-sla').value = business.sla_plan || 'Standard SLA';
    document.getElementById('mbiz-is-verified').value = business.is_verified ? '1' : '0';
    document.getElementById('mbiz-status').value = business.status || 'active';

    openModal('modal-create-business');
  } catch (err) {
    toast('Error loading business: ' + err.message, 'error');
  }
}

async function handleSaveBusiness(e) {
  e.preventDefault();
  const editId = document.getElementById('biz-edit-id')?.value;

  const payload = {
    company_name: document.getElementById('mbiz-name').value.trim(),
    brand_color: document.getElementById('mbiz-color').value,
    logo_icon: document.getElementById('mbiz-icon').value.trim(),
    legal_name: document.getElementById('mbiz-legal-name').value.trim(),
    industry: document.getElementById('mbiz-industry').value,
    bin_tin: document.getElementById('mbiz-bin-tin').value.trim(),
    trade_license: document.getElementById('mbiz-trade-license').value.trim(),
    contact_name: document.getElementById('mbiz-contact-name').value.trim(),
    contact_email: document.getElementById('mbiz-contact-email').value.trim(),
    contact_designation: document.getElementById('mbiz-contact-desig').value.trim(),
    contact_phone: document.getElementById('mbiz-contact-phone').value.trim(),
    district: document.getElementById('mbiz-district').value.trim(),
    address: document.getElementById('mbiz-address').value.trim(),
    account_tier: document.getElementById('mbiz-tier').value,
    credit_limit: Number(document.getElementById('mbiz-credit-limit').value) || 0,
    escrow_deposit_balance: Number(document.getElementById('mbiz-escrow-balance').value) || 0,
    sla_plan: document.getElementById('mbiz-sla').value,
    is_verified: document.getElementById('mbiz-is-verified').value === '1',
    status: document.getElementById('mbiz-status').value
  };

  try {
    if (editId) {
      await api(`/admin/businesses/${editId}`, { method: 'PUT', body: payload });
      toast('Business record updated successfully!', 'success');
    } else {
      await api('/admin/businesses', { method: 'POST', body: payload });
      toast('Corporate client onboarded successfully!', 'success');
    }
    closeModal('modal-create-business');
    await loadBusinesses();
  } catch (err) {
    toast('Error saving business: ' + err.message, 'error');
  }
}

