function switchBizInspectTab(tabId) {
  ['overview', 'credit', 'team', 'compliance'].forEach(t => {
    const tabEl = document.getElementById(`binsp-tab-${t}`);
    const btnEl = document.getElementById(`btn-binsp-tab-${t}`);
    if (tabEl) tabEl.style.display = t === tabId ? 'block' : 'none';
    if (btnEl) {
      if (t === tabId) btnEl.classList.add('active');
      else btnEl.classList.remove('active');
    }
  });
}

