function exportBusinessesCatalog(type = 'json') {
  if (!currentBusinessesList || !currentBusinessesList.length) return toast('No data to export', 'error');

  let dataStr = '';
  let filename = `xtraearn-businesses-${new Date().toISOString().split('T')[0]}`;

  if (type === 'json') {
    dataStr = 'data:text/json;charset=utf-8,' + encodeURIComponent(JSON.stringify(currentBusinessesList, null, 2));
    filename += '.json';
  } else {
    const headers = ['ID', 'Code', 'Company Name', 'Legal Name', 'Industry', 'District', 'Contact Name', 'Contact Email', 'Tier', 'Credit Limit', 'Spend', 'Tasks Posted', 'Status'];
    const rows = currentBusinessesList.map(b => [
      b.id,
      b.company_code || '',
      `"${(b.company_name || '').replace(/"/g, '""')}"`,
      `"${(b.legal_name || '').replace(/"/g, '""')}"`,
      b.industry || '',
      b.district || '',
      `"${(b.contact_person?.name || '').replace(/"/g, '""')}"`,
      b.contact_person?.email || '',
      b.account_tier || '',
      b.credit_limit || 0,
      b.total_spend || 0,
      b.total_tasks_posted || 0,
      b.status || ''
    ]);
    const csvContent = [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
    dataStr = 'data:text/csv;charset=utf-8,' + encodeURIComponent(csvContent);
    filename += '.csv';
  }

  const dlAnchor = document.createElement('a');
  dlAnchor.setAttribute('href', dataStr);
  dlAnchor.setAttribute('download', filename);
  document.body.appendChild(dlAnchor);
  dlAnchor.click();
  dlAnchor.remove();
  toast(`Exported ${currentBusinessesList.length} corporate records (${type.toUpperCase()})`, 'success');
}

/* ================= 30. EXPERT MARKETPLACE & VERIFIED CONSULTATIONS CONTROLLER ================= */
let currentExpertsList = [];
let selectedExpertIds = new Set();
let currentExpFilterTab = 'all';
let currentExpViewMode = 'cards';
let activeInspectedExpert = null;
let expSearchTimer = null;

async function loadExperts() {
  await Promise.all([
    fetchExpertsKPIs(),
    fetchExpertsList()
  ]);
  setupExpertsListeners();
}

async function fetchExpertsKPIs() {
  try {
    const kpis = await api('/admin/experts/kpis');
    if (!kpis) return;
    renderExpertsKPIs(kpis);
  } catch (err) {
    console.error('Failed to load experts KPIs:', err);
  }
}

function renderExpertsKPIs(kpis) {
  setElText('kpi-exp-total', kpis.total_experts || 0);
  setElText('kpi-exp-active-sub', `${kpis.active_experts || 0} Active · ${kpis.pending_credentials || 0} In-Review`);
  setElText('kpi-exp-sessions', kpis.total_sessions || 0);
  setElText('kpi-exp-revenue', `৳${Number(kpis.total_earnings || 0).toLocaleString()}`);
  setElText('kpi-exp-online', kpis.online_now || 0);
  setElText('kpi-exp-rating', `${kpis.avg_rating || 4.96} ★`);

  const c = kpis.counts || {};
  setElText('exp-badge-all', c.all !== undefined ? c.all : (kpis.total_experts || 0));
  setElText('exp-badge-legal', c.legal !== undefined ? c.legal : 5);
  setElText('exp-badge-medical', c.medical !== undefined ? c.medical : 6);
  setElText('exp-badge-engineering', c.engineering !== undefined ? c.engineering : 6);
  setElText('exp-badge-finance', c.finance !== undefined ? c.finance : 4);
  setElText('exp-badge-tech', c.tech !== undefined ? c.tech : 4);
  setElText('exp-badge-education', c.education !== undefined ? c.education : 2);
  setElText('exp-badge-marketing', c.marketing !== undefined ? c.marketing : 3);
  setElText('exp-badge-pending', c.pending !== undefined ? c.pending : (kpis.pending_credentials || 0));
  setElText('exp-badge-suspended', c.suspended !== undefined ? c.suspended : 1);
}

async function fetchExpertsList() {
  try {
    const q = document.getElementById('exp-search-input')?.value || '';
    const domain = document.getElementById('exp-domain-filter')?.value || 'all';
    const verificationStatus = document.getElementById('exp-verify-filter')?.value || 'all';
    const availabilityStatus = document.getElementById('exp-avail-filter')?.value || 'all';
    const status = document.getElementById('exp-status-filter')?.value || 'all';
    const sortBy = document.getElementById('exp-sort-filter')?.value || 'rating_high';

    let url = `/admin/experts?sortBy=${sortBy}`;
    if (q) url += `&q=${encodeURIComponent(q)}`;
    if (domain && domain !== 'all') url += `&domain=${encodeURIComponent(domain)}`;
    if (verificationStatus && verificationStatus !== 'all') url += `&verificationStatus=${encodeURIComponent(verificationStatus)}`;
    if (availabilityStatus && availabilityStatus !== 'all') url += `&availabilityStatus=${encodeURIComponent(availabilityStatus)}`;
    if (status && status !== 'all') url += `&status=${encodeURIComponent(status)}`;
    if (currentExpFilterTab && currentExpFilterTab !== 'all') url += `&flag=${encodeURIComponent(currentExpFilterTab)}`;

    const res = await api(url);
    currentExpertsList = res.items || [];

    if (currentExpViewMode === 'cards') {
      renderExpertsCards(currentExpertsList);
    } else {
      renderExpertsTable(currentExpertsList);
    }
  } catch (err) {
    console.error('Failed to list experts:', err);
  }
}

function renderExpertsCards(items) {
  const container = document.getElementById('experts-cards-grid');
  const tableWrap = document.getElementById('experts-table-wrap');
  if (!container) return;

  container.style.display = 'grid';
  if (tableWrap) tableWrap.style.display = 'none';

  if (!items || !items.length) {
    container.innerHTML = `
      <div style="grid-column:1/-1;text-align:center;padding:48px;background:#0F172A;border-radius:14px;border:1px dashed rgba(255,255,255,0.1)">
        <div style="font-size:2.5rem;margin-bottom:10px">🧠</div>
        <h4 style="color:#fff;margin:0 0 6px">No Verified Experts Found</h4>
        <p style="color:#94A3B8;font-size:0.84rem;margin:0 0 16px">Try changing your search terms or filters</p>
        <button class="btn btn-purple btn-sm" onclick="openCreateExpertModal()">+ Onboard Expert Specialist</button>
      </div>
    `;
    return;
  }

  container.innerHTML = items.map(e => {
    const isChecked = selectedExpertIds.has(e.id);
    const domainIcon = e.domain.includes('Legal') ? '⚖️'
      : e.domain.includes('Medical') ? '🏥'
      : e.domain.includes('Engineering') ? '🏗️'
      : e.domain.includes('Finance') ? '💼'
      : e.domain.includes('Tech') ? '💻'
      : e.domain.includes('Education') ? '🧑‍🏫'
      : '📣';

    const availBadge = e.availability_status === 'online'
      ? `<span class="adm-badge green" style="font-size:0.68rem">🟢 Online</span>`
      : e.availability_status === 'busy'
      ? `<span class="adm-badge orange" style="font-size:0.68rem">🟡 Busy</span>`
      : `<span class="adm-badge" style="font-size:0.68rem;background:rgba(255,255,255,0.1);color:#CBD5E1">⚪ Offline</span>`;

    const statusBadge = e.status === 'active'
      ? `<span class="adm-badge green" style="font-size:0.68rem">Active</span>`
      : e.status === 'pending_credentials'
      ? `<span class="adm-badge orange" style="font-size:0.68rem">Pending Credentials</span>`
      : `<span class="adm-badge red" style="font-size:0.68rem">Suspended</span>`;

    const verifyBadge = e.is_verified
      ? `<span class="adm-badge blue" style="font-size:0.68rem;font-weight:700" title="Accredited License">🛡️ ${escapeHtml(e.verified_badge || 'Verified')}</span>`
      : `<span class="adm-badge orange" style="font-size:0.68rem">⏳ Pending Review</span>`;

    const p15 = e.packages?.quick_advice?.price ? `৳${e.packages.quick_advice.price}` : `৳${Math.round((e.hourly_rate || 2000) * 0.4)}`;
    const p30 = e.packages?.standard_consult?.price ? `৳${e.packages.standard_consult.price}` : `৳${Math.round((e.hourly_rate || 2000) * 0.65)}`;

    return `
      <div class="adm-card" style="background:#0F172A;border:1px solid rgba(255,255,255,0.08);border-radius:16px;padding:18px;display:flex;flex-direction:column;justify-content:space-between;position:relative;transition:all 0.2s">
        <div>
          <!-- Header: Checkbox, Avatar, Name & Domain -->
          <div style="display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:12px">
            <div style="display:flex;align-items:center;gap:10px">
              <input type="checkbox" ${isChecked ? 'checked' : ''} onchange="toggleExpertSelect(${e.id}, this.checked)">
              <div style="width:42px;height:42px;border-radius:10px;background:${e.avatar_color || '#4F46E5'};color:#fff;display:flex;align-items:center;justify-content:center;font-size:1.3rem;font-weight:800">
                ${domainIcon}
              </div>
              <div>
                <h4 style="color:#fff;margin:0;font-size:0.96rem;font-weight:700">${escapeHtml(e.name)}</h4>
                <div style="color:#A78BFA;font-size:0.76rem;margin-top:1px;font-weight:600">${escapeHtml(e.profession || e.title)}</div>
              </div>
            </div>
            <div>${availBadge}</div>
          </div>

          <!-- Professional License & Verification Tag -->
          <div style="background:#1E293B;padding:10px 12px;border-radius:10px;font-size:0.78rem;margin-bottom:12px;display:flex;flex-direction:column;gap:4px">
            <div style="display:flex;justify-content:space-between;align-items:center">
              <span style="color:#94A3B8">Credentials:</span>
              <div>${verifyBadge}</div>
            </div>
            <div style="display:flex;justify-content:space-between;align-items:center">
              <span style="color:#94A3B8">License Reg:</span>
              <span style="color:#34D399;font-family:monospace;font-size:0.74rem">${escapeHtml(e.license_number?.split('·')[0] || 'Registered')}</span>
            </div>
            <div style="display:flex;justify-content:space-between">
              <span style="color:#94A3B8">Location:</span>
              <span style="color:#CBD5E1">${escapeHtml(e.district || 'Dhaka')} · ${e.experience_years || 5}+ yrs exp</span>
            </div>
          </div>

          <!-- Consultation Rates & Package Matrix -->
          <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;text-align:center;background:#111827;padding:10px 6px;border-radius:10px;margin-bottom:14px">
            <div>
              <div style="font-size:0.68rem;color:#94A3B8">15m Chat</div>
              <div style="font-size:0.86rem;font-weight:800;color:#10B981">${p15}</div>
            </div>
            <div>
              <div style="font-size:0.68rem;color:#94A3B8">30m Call</div>
              <div style="font-size:0.86rem;font-weight:800;color:#38BDF8">${p30}</div>
            </div>
            <div>
              <div style="font-size:0.68rem;color:#94A3B8">Hourly Fee</div>
              <div style="font-size:0.86rem;font-weight:800;color:#FBBF24">৳${(e.hourly_rate || 2000).toLocaleString()}</div>
            </div>
          </div>

          <!-- Performance Stats -->
          <div style="display:flex;align-items:center;justify-content:space-between;font-size:0.78rem;color:#94A3B8;margin-bottom:14px;padding:0 4px">
            <span>⭐ <b style="color:#fff">${e.rating || 5.0}</b> (${e.reviews_count || 0} reviews)</span>
            <span>🗓️ <b style="color:#fff">${e.total_sessions_completed || 0}</b> sessions</span>
            <span>💎 <b style="color:#10B981">৳${(e.total_earnings || 0).toLocaleString()}</b></span>
          </div>
        </div>

        <!-- Footer Actions -->
        <div style="display:flex;align-items:center;justify-content:space-between;border-top:1px solid rgba(255,255,255,0.06);padding-top:12px">
          <div>${statusBadge}</div>
          <div style="display:flex;gap:6px">
            <button class="btn btn-outline-light btn-sm" onclick="openExpertRatesModal(${e.id})" title="Rates & Packages" style="padding:4px 8px;font-size:0.75rem">💰</button>
            <button class="btn btn-outline-light btn-sm" onclick="openEditExpertModal(${e.id})" title="Edit Profile" style="padding:4px 8px;font-size:0.75rem">✏️</button>
            <button class="btn btn-purple btn-sm" onclick="viewExpertDetails(${e.id})" style="padding:5px 12px;font-size:0.76rem;font-weight:700">👁️ 360° Inspect</button>
          </div>
        </div>
      </div>
    `;
  }).join('');
}

function renderExpertsTable(items) {
  const container = document.getElementById('experts-cards-grid');
  const tableWrap = document.getElementById('experts-table-wrap');
  const tbody = document.getElementById('experts-table-body');
  if (!tableWrap || !tbody) return;

  if (container) container.style.display = 'none';
  tableWrap.style.display = 'block';

  if (!items || !items.length) {
    tbody.innerHTML = `<tr><td colspan="9" style="text-align:center;padding:32px;color:#94A3B8">No verified experts matching criteria.</td></tr>`;
    return;
  }

  tbody.innerHTML = items.map(e => {
    const isChecked = selectedExpertIds.has(e.id);
    const domainIcon = e.domain.includes('Legal') ? '⚖️'
      : e.domain.includes('Medical') ? '🏥'
      : e.domain.includes('Engineering') ? '🏗️'
      : e.domain.includes('Finance') ? '💼'
      : e.domain.includes('Tech') ? '💻'
      : e.domain.includes('Education') ? '🧑‍🏫'
      : '📣';

    const statusBadge = e.status === 'active'
      ? `<span class="adm-badge green" style="font-size:0.68rem">Active</span>`
      : `<span class="adm-badge orange" style="font-size:0.68rem">${e.status}</span>`;

    return `
      <tr>
        <td><input type="checkbox" ${isChecked ? 'checked' : ''} onchange="toggleExpertSelect(${e.id}, this.checked)"></td>
        <td>
          <div style="display:flex;align-items:center;gap:8px">
            <span style="font-size:1.1rem">${domainIcon}</span>
            <div>
              <b style="color:#fff">${escapeHtml(e.name)}</b>
              <div style="font-size:0.74rem;color:#A78BFA">${escapeHtml(e.profession || e.title)}</div>
            </div>
          </div>
        </td>
        <td>
          <div style="font-weight:600;color:#CBD5E1">${escapeHtml(e.domain)}</div>
          <small style="color:#94A3B8">${escapeHtml(e.district || 'Dhaka')}</small>
        </td>
        <td>
          <div style="font-size:0.76rem;color:#34D399;font-family:monospace">${escapeHtml(e.license_number || 'Registered')}</div>
          <small style="color:#94A3B8">${e.is_verified ? '🛡️ Verified' : '⏳ Pending'}</small>
        </td>
        <td>
          <b style="color:#FBBF24">৳${(e.hourly_rate || 2000).toLocaleString()}/hr</b>
          <div style="font-size:0.72rem;color:#38BDF8">30m: ৳${e.packages?.standard_consult?.price || Math.round((e.hourly_rate || 2000) * 0.65)}</div>
        </td>
        <td>
          <b style="color:#10B981">৳${(e.total_earnings || 0).toLocaleString()}</b>
          <div style="font-size:0.72rem;color:#94A3B8">${e.total_sessions_completed || 0} sessions</div>
        </td>
        <td>
          <span style="color:#FBBF24;font-weight:700">${e.rating || 5.0} ★</span>
          <div style="font-size:0.72rem;color:#94A3B8">${e.reviews_count || 0} reviews</div>
        </td>
        <td>${statusBadge}</td>
        <td style="text-align:right;white-space:nowrap">
          <button class="btn btn-outline-light btn-sm" onclick="openExpertRatesModal(${e.id})" title="Rates" style="padding:4px 8px">💰</button>
          <button class="btn btn-outline-light btn-sm" onclick="openEditExpertModal(${e.id})" title="Edit" style="padding:4px 8px">✏️</button>
          <button class="btn btn-purple btn-sm" onclick="viewExpertDetails(${e.id})" style="padding:4px 10px;font-weight:700">👁️</button>
        </td>
      </tr>
    `;
  }).join('');
}

function setupExpertsListeners() {
  // Segmented Tabs
  document.querySelectorAll('#exp-segment-tabs .adm-tab-btn').forEach(btn => {
    btn.onclick = () => {
      document.querySelectorAll('#exp-segment-tabs .adm-tab-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      currentExpFilterTab = btn.getAttribute('data-exp-tab') || 'all';
      fetchExpertsList();
    };
  });

  // Search input debounce
  const searchInp = document.getElementById('exp-search-input');
  if (searchInp) {
    searchInp.oninput = () => {
      clearTimeout(expSearchTimer);
      expSearchTimer = setTimeout(() => fetchExpertsList(), 250);
    };
  }

  // Filter dropdowns
  ['exp-domain-filter', 'exp-verify-filter', 'exp-avail-filter', 'exp-status-filter', 'exp-sort-filter'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.onchange = () => fetchExpertsList();
  });

  // View switchers
  const btnCards = document.getElementById('btn-exp-view-cards');
  const btnTable = document.getElementById('btn-exp-view-table');

  if (btnCards) {
    btnCards.onclick = () => {
      currentExpViewMode = 'cards';
      btnCards.classList.add('active');
      btnTable?.classList.remove('active');
      renderExpertsCards(currentExpertsList);
    };
  }
  if (btnTable) {
    btnTable.onclick = () => {
      currentExpViewMode = 'table';
      btnTable.classList.add('active');
      btnCards?.classList.remove('active');
      renderExpertsTable(currentExpertsList);
    };
  }

  // Bookings search & filter listeners
  const bkSearch = document.getElementById('bk-search-input');
  if (bkSearch) {
    bkSearch.oninput = () => {
      clearTimeout(bkSearchTimer);
      bkSearchTimer = setTimeout(() => loadConsultationBookings(), 250);
    };
  }

  ['bk-status-filter', 'bk-domain-filter'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.onchange = () => loadConsultationBookings();
  });
}

function toggleExpertSelect(id, checked) {
  if (checked) selectedExpertIds.add(id);
  else selectedExpertIds.delete(id);
  updateExpertsBulkBar();
}

function toggleAllExpertCheckboxes(checked) {
  if (checked) {
    currentExpertsList.forEach(e => selectedExpertIds.add(e.id));
  } else {
    selectedExpertIds.clear();
  }
  updateExpertsBulkBar();
  if (currentExpViewMode === 'cards') renderExpertsCards(currentExpertsList);
  else renderExpertsTable(currentExpertsList);
}

function updateExpertsBulkBar() {
  const bar = document.getElementById('experts-bulk-bar');
  const countEl = document.getElementById('exp-selected-count');
  if (!bar || !countEl) return;

  if (selectedExpertIds.size > 0) {
    bar.style.display = 'flex';
    countEl.textContent = selectedExpertIds.size;
  } else {
    bar.style.display = 'none';
  }
}

function deselectAllExperts() {
  selectedExpertIds.clear();
  updateExpertsBulkBar();
  if (currentExpViewMode === 'cards') renderExpertsCards(currentExpertsList);
  else renderExpertsTable(currentExpertsList);
}

function openCreateExpertModal() {
  document.getElementById('form-create-expert')?.reset();
  document.getElementById('exp-edit-id').value = '';
  document.getElementById('modal-exp-title').textContent = '🧠 Onboard Verified Expert Specialist';
  const domainSel = document.getElementById('mexp-domain');
  if (domainSel) domainSel.value = 'Legal & Law';
  const customWrap = document.getElementById('mexp-custom-domain-wrap');
  if (customWrap) customWrap.style.display = 'none';
  const customInp = document.getElementById('mexp-custom-domain');
  if (customInp) customInp.value = '';
  openModal('modal-create-expert');
}

async function openEditExpertModal(id) {
  try {
    const expert = await api(`/admin/experts/${id}`);
    if (!expert) return toast('Expert not found', 'error');

    document.getElementById('exp-edit-id').value = expert.id;
    document.getElementById('modal-exp-title').textContent = `✏️ Edit ${expert.name}`;
    document.getElementById('mexp-name').value = expert.name || '';

    const domainSelect = document.getElementById('mexp-domain');
    const customWrap = document.getElementById('mexp-custom-domain-wrap');
    const customInp = document.getElementById('mexp-custom-domain');

    let optionExists = false;
    if (domainSelect) {
      for (let opt of domainSelect.options) {
        if (opt.value === expert.domain) { optionExists = true; break; }
      }
      if (optionExists) {
        domainSelect.value = expert.domain;
        if (customWrap) customWrap.style.display = 'none';
        if (customInp) customInp.value = '';
      } else {
        domainSelect.value = '__custom__';
        if (customWrap) customWrap.style.display = 'block';
        if (customInp) customInp.value = expert.domain || '';
      }
    }

    document.getElementById('mexp-color').value = expert.avatar_color || '#4F46E5';
    document.getElementById('mexp-title').value = expert.title || '';
    document.getElementById('mexp-profession').value = expert.profession || '';
    document.getElementById('mexp-license').value = expert.license_number || '';
    document.getElementById('mexp-badge').value = expert.verified_badge || '';
    document.getElementById('mexp-education').value = expert.education || '';
    document.getElementById('mexp-experience').value = expert.experience_years || 5;
    document.getElementById('mexp-district').value = expert.district || 'Dhaka';
    document.getElementById('mexp-hourly-rate').value = expert.hourly_rate || 2000;
    document.getElementById('mexp-pkg-15').value = expert.packages?.quick_advice?.price || 800;
    document.getElementById('mexp-pkg-30').value = expert.packages?.standard_consult?.price || 1500;
    document.getElementById('mexp-pkg-written').value = expert.packages?.written_opinion?.price || 3500;
    document.getElementById('mexp-languages').value = expert.languages || 'Bengali, English';
    document.getElementById('mexp-response-time').value = expert.response_time_mins || 15;
    document.getElementById('mexp-avail').value = expert.availability_status || 'online';
    document.getElementById('mexp-bio').value = expert.bio || '';
    document.getElementById('mexp-is-verified').value = expert.is_verified ? '1' : '0';
    document.getElementById('mexp-status').value = expert.status || 'active';

    openModal('modal-create-expert');
  } catch (err) {
    toast('Error loading expert: ' + err.message, 'error');
  }
}

async function handleSaveExpert(e) {
  e.preventDefault();
  const editId = document.getElementById('exp-edit-id')?.value;

  const hourlyRate = Number(document.getElementById('mexp-hourly-rate').value) || 2000;
  const selectedDomain = document.getElementById('mexp-domain')?.value;
  const customDomain = document.getElementById('mexp-custom-domain')?.value.trim();
  const domain = (selectedDomain === '__custom__' && customDomain) ? customDomain : (selectedDomain || 'Legal & Law');

  const payload = {
    name: document.getElementById('mexp-name').value.trim(),
    domain: domain,
    avatar_color: document.getElementById('mexp-color').value,
    title: document.getElementById('mexp-title').value.trim(),
    profession: document.getElementById('mexp-profession').value.trim(),
    license_number: document.getElementById('mexp-license').value.trim(),
    verified_badge: document.getElementById('mexp-badge').value.trim(),
    education: document.getElementById('mexp-education').value.trim(),
    experience_years: Number(document.getElementById('mexp-experience').value) || 5,
    district: document.getElementById('mexp-district').value.trim(),
    hourly_rate: hourlyRate,
    packages: {
      quick_advice: { name: '15-Min Quick Consultation', price: Number(document.getElementById('mexp-pkg-15').value) || 800, duration: '15 mins', description: 'Fast Q&A triage' },
      standard_consult: { name: '30-Min Strategy Call', price: Number(document.getElementById('mexp-pkg-30').value) || 1500, duration: '30 mins', description: 'Live diagnostic / strategic video consultation' },
      deep_dive: { name: '60-Min Deep Dive Advisory', price: hourlyRate, duration: '60 mins', description: 'Full deep-dive advisory and roadmap' },
      written_opinion: { name: 'Formal Written Opinion', price: Number(document.getElementById('mexp-pkg-written').value) || 3500, duration: '24 Hours SLA', description: 'Signed formal written report' }
    },
    languages: document.getElementById('mexp-languages').value.trim(),
    response_time_mins: Number(document.getElementById('mexp-response-time').value) || 15,
    availability_status: document.getElementById('mexp-avail').value,
    bio: document.getElementById('mexp-bio').value.trim(),
    is_verified: document.getElementById('mexp-is-verified').value === '1',
    status: document.getElementById('mexp-status').value
  };

  try {
    if (editId) {
      await api(`/admin/experts/${editId}`, { method: 'PUT', body: payload });
      toast('Expert specialist record updated successfully!', 'success');
    } else {
      await api('/admin/experts', { method: 'POST', body: payload });
      toast('Verified specialist onboarded successfully!', 'success');
    }
    closeModal('modal-create-expert');
    await loadExperts();
  } catch (err) {
    toast('Error saving expert: ' + err.message, 'error');
  }
}

async function viewExpertDetails(id) {
  try {
    const e = await api(`/admin/experts/${id}`);
    if (!e) return toast('Expert not found', 'error');

    activeInspectedExpert = e;

    const avatar = document.getElementById('exp-insp-avatar');
    if (avatar) {
      avatar.style.background = e.avatar_color || '#4F46E5';
      const d = (e.domain || '').toLowerCase();
      avatar.textContent = d.includes('legal') ? '⚖️'
        : d.includes('medical') ? '🏥'
        : d.includes('engineering') ? '🏗️'
        : d.includes('finance') ? '💼'
        : d.includes('tech') ? '💻'
        : d.includes('education') ? '🧑‍🏫' : '📣';
    }

    setElText('exp-insp-name', e.name || 'Verified Specialist');
    setElText('exp-insp-code', e.expert_code || `EXP-${e.id}`);
    setElText('exp-insp-profession', `${e.profession || e.title || 'Consultant'} · ${e.district || 'Dhaka'}`);
    setElText('exp-insp-sessions', e.total_sessions_completed || 0);
    setElText('exp-insp-earnings', `৳${(e.total_earnings || 0).toLocaleString()}`);
    setElText('exp-insp-rating', `${e.rating || 5.0} ★`);
    setElText('exp-insp-response', `${e.response_time_mins || 15} mins`);
    setElText('exp-insp-bio', e.bio || 'Professional consultant registered on XtraEarn Expert Marketplace.');
    setElText('exp-insp-education', e.education || 'Graduate Degree');
    setElText('exp-insp-exp-years', `${e.experience_years || 5} Years`);
    setElText('exp-insp-languages', e.languages || 'Bengali, English');
    setElText('exp-insp-avail-label', e.availability_status === 'online' ? '🟢 Online Now' : e.availability_status === 'busy' ? '🟡 In Session' : '⚪ Offline');
    setElText('exp-insp-district', e.district || 'Dhaka');
    setElText('exp-insp-created', (e.created_at || '2026-06-05').split(' ')[0]);

    // License Tab
    setElText('exp-insp-badge-tag', e.verified_badge || (e.is_verified ? 'Verified Specialist' : 'Pending Review'));
    setElText('exp-insp-license-val', e.license_number || 'Registered Credential');
    setElText('exp-insp-domain-tag', `${e.domain || 'General'} (${e.profession || 'Specialist'})`);

    // Rates Tab
    setElText('exp-insp-p15', `৳${(e.packages?.quick_advice?.price || Math.round((e.hourly_rate || 2000) * 0.4)).toLocaleString()}`);
    setElText('exp-insp-p30', `৳${(e.packages?.standard_consult?.price || Math.round((e.hourly_rate || 2000) * 0.65)).toLocaleString()}`);
    setElText('exp-insp-p60', `৳${(e.hourly_rate || 2000).toLocaleString()}`);
    setElText('exp-insp-pwritten', `৳${(e.packages?.written_opinion?.price || Math.round((e.hourly_rate || 2000) * 1.8)).toLocaleString()}`);

    // Reviews Tab
    setElText('exp-insp-big-rating', e.rating || 5.0);
    setElText('exp-insp-r5', e.total_reviews_breakdown?.star5 || Math.round((e.reviews_count || 20) * 0.88));
    setElText('exp-insp-r4', e.total_reviews_breakdown?.star4 || Math.round((e.reviews_count || 20) * 0.10));
    setElText('exp-insp-r3', e.total_reviews_breakdown?.star3 || 1);

    // Bookings list
    const bookingsList = document.getElementById('exp-insp-bookings-list');
    if (bookingsList) {
      if (e.sample_bookings && e.sample_bookings.length) {
        bookingsList.innerHTML = e.sample_bookings.map(b => `
          <div style="display:flex;justify-content:space-between;align-items:center;background:#0F172A;padding:8px 12px;border-radius:8px;font-size:0.8rem">
            <div>
              <b style="color:#fff">${escapeHtml(b.client_name)}</b> · <span style="color:#60A5FA">${escapeHtml(b.service)}</span>
              <div style="color:#94A3B8;font-size:0.72rem">${b.date} · Rating: <span style="color:#FBBF24">${b.rating} ★</span> - "${escapeHtml(b.note)}"</div>
            </div>
            <span style="color:#10B981;font-weight:700">৳${b.fee.toLocaleString()}</span>
          </div>
        `).join('');
      } else {
        bookingsList.innerHTML = `<div style="color:#94A3B8;font-size:0.8rem;padding:8px">No recorded sessions in memory ledger.</div>`;
      }
    }

    switchExpertInspectTab('overview');
    openModal('modal-expert-details');
  } catch (err) {
    toast('Error opening expert inspector: ' + err.message, 'error');
  }
}

function switchExpertInspectTab(tabId) {
  ['overview', 'license', 'rates', 'reviews'].forEach(t => {
    const tabEl = document.getElementById(`einsp-tab-${t}`);
    const btnEl = document.getElementById(`btn-einsp-tab-${t}`);
    if (tabEl) tabEl.style.display = t === tabId ? 'block' : 'none';
    if (btnEl) {
      if (t === tabId) btnEl.classList.add('active');
      else btnEl.classList.remove('active');
    }
  });
}

