async function handleSaveExpertRates(e) {
  e.preventDefault();
  const id = document.getElementById('mexprates-id')?.value;
  if (!id) return;

  const hourly = Number(document.getElementById('mexprates-hourly').value) || 2000;
  const payload = {
    hourly_rate: hourly,
    packages: {
      quick_advice: { name: '15-Min Quick Consultation', price: Number(document.getElementById('mexprates-p15').value) || Math.round(hourly * 0.4), duration: '15 mins' },
      standard_consult: { name: '30-Min Strategy Call', price: Number(document.getElementById('mexprates-p30').value) || Math.round(hourly * 0.65), duration: '30 mins' },
      deep_dive: { name: '60-Min Deep Dive Session', price: hourly, duration: '60 mins' },
      written_opinion: { name: 'Written Formal Opinion', price: Number(document.getElementById('mexprates-pwritten').value) || Math.round(hourly * 1.8), duration: '24 Hours SLA' }
    }
  };

  try {
    await api(`/admin/experts/${id}/rates`, {
      method: 'PATCH',
      body: payload
    });
    toast('Consultation fees & packages updated successfully!', 'success');
    closeModal('modal-expert-rates');
    if (activeInspectedExpert && activeInspectedExpert.id === Number(id)) {
      await viewExpertDetails(id);
    }
    await loadExperts();
  } catch (err) {
    toast('Error adjusting rates: ' + err.message, 'error');
  }
}

function handleBulkExpActionChange(val) {
  // Can be extended if custom input fields are needed
}

async function handleApplyBulkExperts(e) {
  e.preventDefault();
  const action = document.getElementById('bulk-exp-action')?.value;
  const targetIds = selectedExpertIds.size ? Array.from(selectedExpertIds) : currentExpertsList.map(item => item.id);

  if (!targetIds.length) return toast('No experts selected', 'error');

  let reqAction = 'status';
  let payload = {};

  if (action === 'status_active') {
    reqAction = 'status'; payload = { status: 'active' };
  } else if (action === 'status_suspended') {
    reqAction = 'status'; payload = { status: 'suspended' };
  } else if (action === 'verify_grant') {
    reqAction = 'verify'; payload = { is_verified: 1 };
  } else if (action === 'verify_revoke') {
    reqAction = 'verify'; payload = { is_verified: 0 };
  } else if (action === 'avail_online') {
    reqAction = 'availability'; payload = { availability_status: 'online' };
  } else if (action === 'rate_increase') {
    reqAction = 'rate_adjust'; payload = { rate_delta: 500 };
  } else if (action === 'rate_decrease') {
    reqAction = 'rate_adjust'; payload = { rate_delta: -500 };
  }

  try {
    const res = await api('/admin/experts/bulk', {
      method: 'POST',
      body: { action: reqAction, expertIds: targetIds, payload }
    });
    toast(`Batch action applied to ${res.modified || targetIds.length} expert records!`, 'success');
    closeModal('modal-bulk-experts');
    deselectAllExperts();
    await loadExperts();
  } catch (err) {
    toast('Bulk action failed: ' + err.message, 'error');
  }
}

async function bulkVerifyExperts(isVerified) {
  if (!selectedExpertIds.size) return toast('Select at least one expert', 'error');
  try {
    await api('/admin/experts/bulk', {
      method: 'POST',
      body: { action: 'verify', expertIds: Array.from(selectedExpertIds), payload: { is_verified: isVerified } }
    });
    toast(`Updated verification for ${selectedExpertIds.size} experts`, 'success');
    deselectAllExperts();
    await loadExperts();
  } catch (err) {
    toast('Error: ' + err.message, 'error');
  }
}

async function bulkUpdateExpertsStatus(status) {
  if (!selectedExpertIds.size) return toast('Select at least one expert', 'error');
  try {
    await api('/admin/experts/bulk', {
      method: 'POST',
      body: { action: 'status', expertIds: Array.from(selectedExpertIds), payload: { status } }
    });
    toast(`Updated ${selectedExpertIds.size} experts to ${status}`, 'success');
    deselectAllExperts();
    await loadExperts();
  } catch (err) {
    toast('Error: ' + err.message, 'error');
  }
}

function exportExpertsCatalog(type = 'json') {
  if (!currentExpertsList || !currentExpertsList.length) return toast('No data to export', 'error');

  let dataStr = '';
  let filename = `xtraearn-experts-${new Date().toISOString().split('T')[0]}`;

  if (type === 'json') {
    dataStr = 'data:text/json;charset=utf-8,' + encodeURIComponent(JSON.stringify(currentExpertsList, null, 2));
    filename += '.json';
  } else {
    const headers = ['ID', 'Code', 'Name', 'Title', 'Profession', 'Domain', 'License Number', 'District', 'Hourly Rate', 'Sessions Completed', 'Earnings', 'Rating', 'Status'];
    const rows = currentExpertsList.map(e => [
      e.id,
      e.expert_code || '',
      `"${(e.name || '').replace(/"/g, '""')}"`,
      `"${(e.title || '').replace(/"/g, '""')}"`,
      `"${(e.profession || '').replace(/"/g, '""')}"`,
      e.domain || '',
      `"${(e.license_number || '').replace(/"/g, '""')}"`,
      e.district || '',
      e.hourly_rate || 0,
      e.total_sessions_completed || 0,
      e.total_earnings || 0,
      e.rating || 5.0,
      e.status || ''
    ]);
    const csvContent = [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
    dataStr = 'data:text/csv;charset=utf-8,' + encodeURIComponent(csvContent);
    filename += '.csv';
  }

  const dlAnchor = document.createElement('a');
  dlAnchor.setAttribute('href', dataStr);
  dlAnchor.setAttribute('download', filename);
  document.body.appendChild(dlAnchor);
  dlAnchor.click();
  dlAnchor.remove();
  toast(`Exported ${currentExpertsList.length} expert records (${type.toUpperCase()})`, 'success');
}

