let currentExpertSubView = 'directory';
let currentConsultationBookings = [];
let activeInspectedBooking = null;
let bkSearchTimer = null;

function switchExpertSubView(view) {
  currentExpertSubView = view;
  const dirSub = document.getElementById('expert-directory-subview');
  const bkSub = document.getElementById('expert-bookings-subview');
  const btnDir = document.getElementById('tab-exp-view-directory');
  const btnBk = document.getElementById('tab-exp-view-bookings');

  if (view === 'directory') {
    if (dirSub) dirSub.style.display = 'block';
    if (bkSub) bkSub.style.display = 'none';
    if (btnDir) { btnDir.className = 'btn btn-sm btn-purple'; }
    if (btnBk) { btnBk.className = 'btn btn-sm btn-outline-light'; }
    loadExperts();
  } else {
    if (dirSub) dirSub.style.display = 'none';
    if (bkSub) bkSub.style.display = 'block';
    if (btnDir) { btnDir.className = 'btn btn-sm btn-outline-light'; }
    if (btnBk) { btnBk.className = 'btn btn-sm btn-purple'; }
    loadConsultationBookings();
  }
}

async function loadConsultationBookings() {
  const tbody = document.getElementById('bookings-table-body');
  if (!tbody) return;

  try {
    const q = document.getElementById('bk-search-input')?.value || '';
    const status = document.getElementById('bk-status-filter')?.value || 'all';
    const domain = document.getElementById('bk-domain-filter')?.value || 'all';

    let url = `/admin/experts/bookings?status=${status}&domain=${encodeURIComponent(domain)}`;
    if (q && q.trim()) url += `&q=${encodeURIComponent(q.trim())}`;

    const data = await api(url);
    currentConsultationBookings = data.items || [];

    if (data.kpis) {
      setElText('kpi-bk-total', data.kpis.total_bookings);
      setElText('kpi-bk-escrow', `৳${(data.kpis.active_escrow || 0).toLocaleString()}`);
      setElText('kpi-bk-completed', data.kpis.completed_sessions);
      setElText('kpi-bk-today', data.kpis.today_sessions);
      setElText('cnt-sub-bookings', data.kpis.total_bookings);
    }

    if (!currentConsultationBookings.length) {
      tbody.innerHTML = `
        <tr>
          <td colspan="10" style="text-align:center;padding:36px 16px;color:#94A3B8">
            <div style="font-size:1.8rem;margin-bottom:6px">📅</div>
            <b>No consultation bookings found matching your filters</b>
          </td>
        </tr>
      `;
      return;
    }

    tbody.innerHTML = currentConsultationBookings.map(b => {
      const isConfirmed = b.status === 'confirmed';
      const isCompleted = b.status === 'completed';
      const isProgress = b.status === 'in_progress';
      const isCancelled = b.status === 'cancelled' || b.status === 'refunded';

      const statusBadge = isConfirmed
        ? `<span class="adm-badge" style="background:rgba(59,130,246,0.15);color:#93C5FD;border:1px solid rgba(59,130,246,0.3)">Confirmed</span>`
        : isProgress
        ? `<span class="adm-badge" style="background:rgba(245,158,11,0.15);color:#FDE68A;border:1px solid rgba(245,158,11,0.3)">Live / In Session</span>`
        : isCompleted
        ? `<span class="adm-badge" style="background:rgba(16,185,129,0.15);color:#A7F3D0;border:1px solid rgba(16,185,129,0.3)">Completed &amp; Paid</span>`
        : `<span class="adm-badge" style="background:rgba(239,68,68,0.15);color:#FECACA;border:1px solid rgba(239,68,68,0.3)">Cancelled / Refunded</span>`;

      const modeIcon = b.communication_mode === 'video_call' ? '📹 Video' : b.communication_mode === 'audio_call' ? '📞 Voice' : '📄 Written';

      return `
        <tr style="border-bottom:1px solid rgba(255,255,255,0.06)">
          <td>
            <b style="color:#A78BFA;font-family:monospace;font-size:0.88rem">${escapeHtml(b.booking_code)}</b>
            <div style="font-size:0.72rem;color:#94A3B8">${b.created_at || ''}</div>
          </td>
          <td>
            <div style="display:flex;align-items:center;gap:8px">
              <div style="width:32px;height:32px;border-radius:8px;background:${b.expert_avatar_color || '#4F46E5'};color:#fff;display:flex;align-items:center;justify-content:center;font-size:0.95rem;font-weight:700">
                ${(b.expert_name || 'E').substring(0, 1)}
              </div>
              <div>
                <b style="color:#fff">${escapeHtml(b.expert_name)}</b>
                <div style="color:#94A3B8;font-size:0.72rem">${escapeHtml(b.expert_domain || 'Specialist')}</div>
              </div>
            </div>
          </td>
          <td>
            <b style="color:#fff">${escapeHtml(b.user_name)}</b>
            <div style="color:#94A3B8;font-size:0.74rem">📞 ${escapeHtml(b.user_phone || '')}</div>
          </td>
          <td>
            <div style="color:#E2E8F0;font-weight:600">${escapeHtml(b.package_name)}</div>
            <small style="color:#10B981;font-weight:700">⏱ ${escapeHtml(b.duration)}</small>
          </td>
          <td>
            <div style="color:#fff;font-weight:700">📅 ${escapeHtml(b.scheduled_date)}</div>
            <small style="color:#FBBF24">🕒 ${escapeHtml(b.scheduled_time)}</small>
          </td>
          <td>
            <span class="adm-badge" style="background:#1E293B;color:#E2E8F0">${modeIcon}</span>
          </td>
          <td>
            <b style="color:#10B981;font-size:0.95rem">৳${Number(b.fee).toLocaleString()}</b>
            <div style="font-size:0.7rem;color:#94A3B8">${b.escrow_status === 'released_to_specialist' ? 'Released' : b.escrow_status === 'refunded_to_client' ? 'Refunded' : '🔒 In Escrow'}</div>
          </td>
          <td>
            <div style="display:flex;gap:4px">
              <a href="${b.meeting_link}" target="_blank" class="btn btn-purple btn-sm" style="padding:3px 8px;font-size:0.72rem" title="Join Video Room">🔗 Join</a>
              <button class="btn btn-outline-light btn-sm" style="padding:3px 8px;font-size:0.72rem" onclick="navigator.clipboard.writeText('${b.meeting_link}');toast('Meeting room link copied!','success')" title="Copy URL">📋</button>
            </div>
          </td>
          <td>${statusBadge}</td>
          <td style="text-align:right">
            <div style="display:flex;gap:6px;justify-content:flex-end">
              <button class="btn btn-outline-light btn-sm" onclick="openConsultationBookingDetails(${b.id})" style="font-size:0.74rem;padding:4px 8px" title="Inspect Booking Dossier">👁️</button>
              ${!isCompleted && !isCancelled ? `
                <button class="btn btn-sm" onclick="quickCompleteBooking(${b.id})" style="background:#10B981;color:#fff;border:none;font-size:0.74rem;padding:4px 8px" title="Complete & Release Escrow">✅</button>
                <button class="btn btn-outline-light btn-sm" onclick="quickResendBookingNotif(${b.id})" style="font-size:0.74rem;padding:4px 8px" title="Re-send Notification Reminder">📲</button>
                <button class="btn btn-sm" onclick="quickCancelBooking(${b.id})" style="background:#EF4444;color:#fff;border:none;font-size:0.74rem;padding:4px 8px" title="Cancel & Refund Escrow">❌</button>
              ` : ''}
            </div>
          </td>
        </tr>
      `;
    }).join('');
  } catch (err) {
    toast('Error loading consultation bookings: ' + err.message, 'error');
  }
}

async function openConsultationBookingDetails(bookingId) {
  const b = currentConsultationBookings.find(x => x.id === Number(bookingId));
  if (!b) return toast('Booking record not found', 'error');

  activeInspectedBooking = b;

  setElText('bk-modal-title', `📅 Consultation Session: ${b.booking_code}`);
  setElText('bk-modal-sub', `1-on-1 ${b.package_name} with ${b.expert_name} · 100% Escrow Protected`);
  setElText('bk-modal-exp-name', b.expert_name);
  setElText('bk-modal-exp-domain', `${b.expert_profession || ''} · ${b.expert_domain || ''}`);
  setElText('bk-modal-client-name', b.user_name);
  setElText('bk-modal-client-phone', b.user_phone);
  setElText('bk-modal-client-email', b.user_email);
  setElText('bk-modal-tier', `${b.package_name} (${b.duration})`);
  setElText('bk-modal-slot', `${b.scheduled_date} @ ${b.scheduled_time}`);
  setElText('bk-modal-mode', b.communication_mode === 'video_call' ? '📹 Live Video Call' : b.communication_mode === 'audio_call' ? '📞 Voice Call' : '📄 Formal Written Opinion');
  setElText('bk-modal-fee', `৳${Number(b.fee).toLocaleString()} (${b.escrow_status === 'released_to_specialist' ? 'Paid to Specialist' : b.escrow_status === 'refunded_to_client' ? 'Refunded to Client' : 'Locked in Escrow'})`);
  setElText('bk-modal-link-text', b.meeting_link);
  setElText('bk-modal-notes', b.consultation_notes || 'No custom notes provided by client.');

  const joinBtn = document.getElementById('bk-modal-join-btn');
  if (joinBtn) joinBtn.href = b.meeting_link;

  const completeBtn = document.getElementById('btn-bk-complete');
  const cancelBtn = document.getElementById('btn-bk-cancel');
  if (completeBtn) completeBtn.style.display = (b.status === 'completed' || b.status === 'cancelled') ? 'none' : 'inline-block';
  if (cancelBtn) cancelBtn.style.display = (b.status === 'completed' || b.status === 'cancelled') ? 'none' : 'inline-block';

  openModal('modal-consultation-booking-details');
}

function copyBookingLink() {
  if (!activeInspectedBooking) return;
  navigator.clipboard.writeText(activeInspectedBooking.meeting_link);
  toast('Encrypted meeting room link copied to clipboard!', 'success');
}

async function quickCompleteBooking(id) {
  if (!confirm('Are you sure you want to mark this consultation as completed and release the escrow funds to the specialist?')) return;
  try {
    await api(`/admin/experts/bookings/${id}/status`, {
      method: 'PATCH',
      body: { status: 'completed' }
    });
    toast('Consultation completed and escrow funds released!', 'success');
    await loadConsultationBookings();
  } catch (err) {
    toast('Error completing booking: ' + err.message, 'error');
  }
}

async function quickCancelBooking(id) {
  if (!confirm('Are you sure you want to cancel this booking and refund the escrow fee back to the client?')) return;
  try {
    await api(`/admin/experts/bookings/${id}/status`, {
      method: 'PATCH',
      body: { status: 'cancelled' }
    });
    toast('Consultation cancelled and escrow refunded to client!', 'info');
    await loadConsultationBookings();
  } catch (err) {
    toast('Error cancelling booking: ' + err.message, 'error');
  }
}

async function quickResendBookingNotif(id) {
  try {
    const res = await api(`/admin/experts/bookings/${id}/resend`, { method: 'POST' });
    toast(`Session reminder & video link re-sent for ${res.booking_code}!`, 'success');
  } catch (err) {
    toast('Error re-sending notification: ' + err.message, 'error');
  }
}

async function handleAdminCompleteBooking() {
  if (!activeInspectedBooking) return;
  await quickCompleteBooking(activeInspectedBooking.id);
  closeModal('modal-consultation-booking-details');
}

async function handleAdminCancelBooking() {
  if (!activeInspectedBooking) return;
  await quickCancelBooking(activeInspectedBooking.id);
  closeModal('modal-consultation-booking-details');
}

async function handleAdminResendBookingNotif() {
  if (!activeInspectedBooking) return;
  await quickResendBookingNotif(activeInspectedBooking.id);
}

