  async function loadCouponsDashboard() {
    try {
      const q = document.getElementById('cpn-search-input')?.value || '';
      const category = document.getElementById('cpn-filter-category')?.value || 'all';
      const status = document.getElementById('cpn-filter-status')?.value || 'all';
      const sort = document.getElementById('cpn-filter-sort')?.value || 'newest';

      const [kpis, data] = await Promise.all([
        api('/admin/coupons/kpis').catch(() => null),
        api(`/admin/coupons?q=${encodeURIComponent(q)}&category=${encodeURIComponent(category)}&status=${status}&sort=${sort}`).catch(() => ({ items: [] }))
      ]);

      if (kpis) {
        setElText('cpn-kpi-active-count', (kpis.active_campaigns || 0).toLocaleString());
        setElText('cpn-kpi-total-sub', `${(kpis.total_campaigns || 0).toLocaleString()} Total Live`);
        setElText('cpn-kpi-redemptions-count', (kpis.total_redemptions || 0).toLocaleString());
        setElText('cpn-kpi-gmv-amount', `৳${(kpis.gross_gmv_driven || 0).toLocaleString('en-US', { minimumFractionDigits: 2 })}`);
        setElText('cpn-kpi-subsidies-amount', `৳${(kpis.discount_subsidies_disbursed || 0).toLocaleString('en-US', { minimumFractionDigits: 2 })}`);
        setElText('cpn-kpi-roi-multiplier', `${kpis.average_roi || '4.8'}x`);
        setElText('cpn-kpi-burn-pct', `${kpis.budget_burn_rate_pct || 0}%`);
      }

      renderCouponsTable(data?.items || []);
    } catch (err) {
      toast && toast(err.message, 'error');
    }
  }

  function renderCouponsTable(items) {
    const tbody = document.getElementById('coupons-table-body');
    if (!tbody) return;

    if (!items || items.length === 0) {
      tbody.innerHTML = `<tr><td colspan="9" style="text-align:center;padding:30px;color:#94A3B8">No promo coupon campaigns found matching query.</td></tr>`;
      return;
    }

    tbody.innerHTML = items.map(c => {
      let discountBadge = '';
      if (c.type === 'percentage') discountBadge = `<b style="color:#818CF8">${c.discountPct}% OFF</b>`;
      else if (c.type === 'fixed_amount') discountBadge = `<b style="color:#10B981">৳${c.fixedDiscount} FLAT</b>`;
      else discountBadge = `<b style="color:#F59E0B">0% FEE WAIVER</b>`;

      let statusBadge = '';
      if (c.status === 'active') statusBadge = '<span class="badge-chip" style="background:rgba(16,185,129,0.2);color:#34D399;font-weight:700">🟢 Active</span>';
      else if (c.status === 'paused') statusBadge = '<span class="badge-chip" style="background:rgba(245,158,11,0.2);color:#FBBF24;font-weight:700">⏸️ Paused</span>';
      else if (c.status === 'expired') statusBadge = '<span class="badge-chip" style="background:rgba(239,68,68,0.2);color:#F87171;font-weight:700">⏳ Expired</span>';
      else statusBadge = '<span class="badge-chip" style="background:rgba(148,163,184,0.2);color:#94A3B8;font-weight:700">🔴 Exhausted</span>';

      const burnPct = c.budgetCap > 0 ? Math.min(100, Math.round(((c.budgetBurned || 0) / c.budgetCap) * 100)) : 0;

      return `
        <tr>
          <td>
            <b style="font-family:monospace;color:#A78BFA;font-size:0.95rem">${escapeHtml(c.code)}</b>
            <span style="color:#fff;font-size:0.84rem;display:block">${escapeHtml(c.title)}</span>
          </td>
          <td>
            ${discountBadge}
            <small style="color:#94A3B8;display:block">Type: ${escapeHtml(c.type)}</small>
          </td>
          <td>
            <span style="color:#CBD5E1">Min: ৳${c.minSpend || 0}</span>
            <small style="color:#94A3B8;display:block">Max Cap: ৳${c.maxDiscount || 'Unlimited'}</small>
          </td>
          <td>
            <span class="badge-chip" style="background:#1E293B;color:#CBD5E1">${escapeHtml(c.targetAudience || 'all')}</span>
            <small style="color:#94A3B8;display:block">Scope: ${escapeHtml(c.categoryScope || 'all')}</small>
          </td>
          <td>
            <b style="color:#fff">${(c.usageCount || 0).toLocaleString()}</b>
            <small style="color:#94A3B8;display:block">Limit: ${c.usageLimitGlobal || '∞'}</small>
          </td>
          <td>
            <div style="width:90px;background:rgba(255,255,255,0.1);height:6px;border-radius:3px;overflow:hidden;margin-bottom:4px">
              <div style="width:${burnPct}%;background:${burnPct > 80 ? '#EF4444' : '#10B981'};height:100%"></div>
            </div>
            <small style="color:#94A3B8">৳${(c.budgetBurned || 0).toLocaleString()} / ৳${(c.budgetCap || 0).toLocaleString()}</small>
          </td>
          <td>
            <small style="color:#CBD5E1">${c.validFrom || 'Now'} ➔ ${c.validUntil || 'Ongoing'}</small>
          </td>
          <td>${statusBadge}</td>
          <td style="text-align:right">
            <div style="display:flex;gap:6px;justify-content:flex-end">
              <button class="btn btn-xs btn-outline-light" onclick="openCouponDossier('${c.id}')" title="Inspect Campaign Dossier">👁️</button>
              <button class="btn btn-xs btn-outline-light" onclick="toggleCouponStatus('${c.id}', '${c.status}')" title="Pause / Activate">
                ${c.status === 'active' ? '⏸️' : '▶️'}
              </button>
              <button class="btn btn-xs btn-outline-light" onclick="deleteCouponRecord('${c.id}')" title="Delete Coupon" style="color:#EF4444">🗑️</button>
            </div>
          </td>
        </tr>
      `;
    }).join('');
  }

  function switchCouponTab(tab) {
    const campaignsTab = document.getElementById('coupon-tab-campaigns');
    const redemptionsTab = document.getElementById('coupon-tab-redemptions');
    const batchesTab = document.getElementById('coupon-tab-batches');

    const btnCamp = document.getElementById('tab-btn-cpn-campaigns');
    const btnRed = document.getElementById('tab-btn-cpn-redemptions');
    const btnBatch = document.getElementById('tab-btn-cpn-batches');

    if (campaignsTab) campaignsTab.style.display = tab === 'campaigns' ? 'block' : 'none';
    if (redemptionsTab) redemptionsTab.style.display = tab === 'redemptions' ? 'block' : 'none';
    if (batchesTab) batchesTab.style.display = tab === 'batches' ? 'block' : 'none';

    if (btnCamp) btnCamp.className = tab === 'campaigns' ? 'btn btn-sm btn-purple' : 'btn btn-sm btn-outline-light';
    if (btnRed) btnRed.className = tab === 'redemptions' ? 'btn btn-sm btn-purple' : 'btn btn-sm btn-outline-light';
    if (btnBatch) btnBatch.className = tab === 'batches' ? 'btn btn-sm btn-purple' : 'btn btn-sm btn-outline-light';

    if (tab === 'campaigns') loadCouponsDashboard();
    else if (tab === 'redemptions') loadCouponRedemptionsTable();
    else if (tab === 'batches') loadVoucherBatchesTable();
  }

