  async function loadReferralsDashboard() {
    try {
      const q = document.getElementById('ref-search-input')?.value || '';
      const status = document.getElementById('ref-status-filter')?.value || 'all';

      const [kpis, data] = await Promise.all([
        api('/admin/referrals/kpis'),
        api(`/admin/referrals?q=${encodeURIComponent(q)}&status=${status}`)
      ]);

      if (kpis) {
        setElText('ref-kpi-referrers', (kpis.active_referrers || 0).toLocaleString());
        setElText('ref-kpi-total', (kpis.total_referrals || 0).toLocaleString());
        setElText('ref-kpi-qualified', (kpis.qualified_conversions || 0).toLocaleString());
        setElText('ref-kpi-disbursed', `৳${(kpis.total_rewards_disbursed || 0).toLocaleString('en-US', { minimumFractionDigits: 2 })}`);
        setElText('ref-kpi-cvr', `${kpis.conversion_rate_pct || 0}%`);
        setElText('ref-kpi-kfactor', `${kpis.viral_k_factor || '0.00'}`);
      }

      renderReferralsTable(data?.items || []);
    } catch (err) {
      toast && toast(err.message, 'error');
    }
  }

  function renderReferralsTable(items) {
    const tbody = document.getElementById('referrals-table-body');
    if (!tbody) return;

    if (!items || items.length === 0) {
      tbody.innerHTML = `<tr><td colspan="8" style="text-align:center;padding:30px;color:#94A3B8">No referral records found matching query.</td></tr>`;
      return;
    }

    tbody.innerHTML = items.map(r => {
      let statusBadge = '';
      if (r.status === 'reward_paid') statusBadge = '<span class="badge-chip" style="background:rgba(16,185,129,0.2);color:#34D399;font-weight:700">💸 Reward Paid</span>';
      else if (r.status === 'reward_approved') statusBadge = '<span class="badge-chip" style="background:rgba(59,130,246,0.2);color:#60A5FA;font-weight:700">✅ Approved</span>';
      else if (r.status === 'rejected_fraud') statusBadge = '<span class="badge-chip" style="background:rgba(239,68,68,0.2);color:#F87171;font-weight:700">🚫 Flagged / Rejected</span>';
      else statusBadge = '<span class="badge-chip" style="background:rgba(245,158,11,0.2);color:#FBBF24;font-weight:700">⏳ Pending Task</span>';

      return `
        <tr>
          <td><b style="font-family:monospace;color:#818CF8;font-size:0.92rem">${escapeHtml(r.referral_code)}</b></td>
          <td>
            <b style="color:#fff;display:block">${escapeHtml(r.referrer_name)}</b>
            <small style="color:#94A3B8;font-size:0.75rem">${escapeHtml(r.referrer_role)} (ID: ${r.referrer_id})</small>
          </td>
          <td>
            <b style="color:#fff;display:block">${escapeHtml(r.referee_name)}</b>
            <small style="color:#94A3B8;font-size:0.75rem">${escapeHtml(r.referee_role)} (ID: ${r.referee_id})</small>
          </td>
          <td><b style="color:#10B981">৳${Number(r.reward_amount || 100).toLocaleString()}</b></td>
          <td>
            ${r.qualification_task_id ? `<span style="color:#CBD5E1">Task #${r.qualification_task_id} (৳${r.qualification_spend})</span>` : '<span style="color:#64748B">None</span>'}
          </td>
          <td>${statusBadge}</td>
          <td><small style="color:#94A3B8">${r.created_at ? new Date(r.created_at).toLocaleDateString() : 'N/A'}</small></td>
          <td style="text-align:right">
            <div style="display:flex;gap:6px;justify-content:flex-end">
              <button class="btn btn-xs btn-outline-light" onclick="openReferralDossier('${r.id}')" title="Inspect Link Dossier">👁️</button>
              ${r.status === 'pending_qualification' || r.status === 'reward_approved' ? `
                <button class="btn btn-xs btn-green" onclick="approveReferralReward('${r.id}')" title="Approve & Disburse Reward">💸 Pay</button>
                <button class="btn btn-xs btn-outline-light" onclick="rejectReferralReward('${r.id}')" title="Reject / Flag Fraud" style="color:#EF4444">🚫</button>
              ` : ''}
            </div>
          </td>
        </tr>
      `;
    }).join('');
  }

