          <div style="margin-top:6px;display:flex;justify-content:space-between;align-items:center">
            <span style="color:#fff">${r.qualification_task_id ? `Completed Task #${r.qualification_task_id} (Spent ৳${r.qualification_spend} BDT)` : 'No qualifying task completed yet'}</span>
            <span class="badge-chip" style="background:#1E293B;color:#fff">${r.status}</span>
          </div>
