  async function loadAffiliatesDashboard() {
    try {
      const q = document.getElementById('aff-search-input')?.value || '';
      const tier = document.getElementById('aff-tier-filter')?.value || 'all';
      const status = document.getElementById('aff-status-filter')?.value || 'all';
      const sort = document.getElementById('aff-sort-filter')?.value || 'highest_gmv';

      const [kpis, data] = await Promise.all([
        api('/admin/affiliates/kpis'),
        api(`/admin/affiliates?q=${encodeURIComponent(q)}&tier=${tier}&status=${status}&sort=${sort}`)
      ]);

      if (kpis) {
        setElText('aff-kpi-partners', (kpis.active_partners || 0).toLocaleString());
        setElText('aff-kpi-clicks', (kpis.total_clicks || 0).toLocaleString());
        setElText('aff-kpi-conversions', (kpis.total_conversions || 0).toLocaleString());
        setElText('aff-kpi-gmv', `৳${(kpis.gross_gmv_attributed || 0).toLocaleString('en-US', { minimumFractionDigits: 2 })}`);
        setElText('aff-kpi-paid', `৳${(kpis.commission_paid_total || 0).toLocaleString('en-US', { minimumFractionDigits: 2 })}`);
        setElText('aff-kpi-pending', `৳${(kpis.commission_pending_total || 0).toLocaleString('en-US', { minimumFractionDigits: 2 })}`);
      }

      renderAffiliatesTable(data?.items || []);
    } catch (err) {
      toast && toast(err.message, 'error');
    }
  }

  function renderAffiliatesTable(items) {
    const tbody = document.getElementById('affiliates-table-body');
    if (!tbody) return;

    if (!items || items.length === 0) {
      tbody.innerHTML = `<tr><td colspan="10" style="text-align:center;padding:30px;color:#94A3B8">No affiliate partners found matching query.</td></tr>`;
      return;
    }

    tbody.innerHTML = items.map(p => {
      let tierBadge = '';
      if (p.tier === 'strategic_partner') tierBadge = '<span class="badge-chip" style="background:rgba(236,72,153,0.2);color:#F472B6;font-weight:700">Strategic (25%)</span>';
      else if (p.tier === 'vip_influencer') tierBadge = '<span class="badge-chip" style="background:rgba(139,92,246,0.2);color:#A78BFA;font-weight:700">VIP Influencer (20%)</span>';
      else if (p.tier === 'verified_agency') tierBadge = '<span class="badge-chip" style="background:rgba(59,130,246,0.2);color:#60A5FA;font-weight:700">Agency (15%)</span>';
      else tierBadge = '<span class="badge-chip" style="background:rgba(16,185,129,0.2);color:#34D399;font-weight:700">Standard (10%)</span>';

      return `
        <tr>
          <td><b style="font-family:monospace;color:#10B981;font-size:0.95rem">${escapeHtml(p.code)}</b></td>
          <td>
            <b style="color:#fff;display:block">${escapeHtml(p.partner_name)}</b>
            <small style="color:#94A3B8;font-size:0.75rem">${escapeHtml(p.channel)}</small>
          </td>
          <td>${tierBadge}</td>
          <td><b style="color:#fff">${(p.clicks || 0).toLocaleString()}</b></td>
          <td><b style="color:#34D399">${(p.conversions || 0).toLocaleString()}</b></td>
          <td><b style="color:#60A5FA">৳${(p.gmv_attributed || 0).toLocaleString()}</b></td>
          <td>
            <span style="color:#10B981;display:block">Earned: ৳${(p.earned_commission || 0).toLocaleString()}</span>
            <small style="color:#94A3B8">Paid: ৳${(p.paid_commission || 0).toLocaleString()}</small>
          </td>
          <td><b style="color:#F59E0B">৳${(p.pending_commission || 0).toLocaleString()}</b></td>
          <td>
            <span class="badge-chip" style="background:${p.status === 'active' ? 'rgba(16,185,129,0.2)' : 'rgba(239,68,68,0.2)'};color:${p.status === 'active' ? '#34D399' : '#F87171'}">
              ${p.status === 'active' ? '● Active' : '✕ Suspended'}
            </span>
          </td>
          <td style="text-align:right">
            <div style="display:flex;gap:6px;justify-content:flex-end">
              <button class="btn btn-xs btn-outline-light" onclick="openAffiliateDossier('${p.id}')" title="Inspect Partner Performance">👁️</button>
              ${p.pending_commission > 0 ? `
                <button class="btn btn-xs btn-green" onclick="openAffiliatePayoutModal('${p.id}', '${escapeHtml(p.partner_name)}', '${escapeHtml(p.code)}', ${p.pending_commission})" title="Disburse Commission Payout">💳 Payout</button>
              ` : ''}
              <button class="btn btn-xs btn-outline-light" onclick="toggleAffiliateStatus('${p.id}', '${p.status}')" title="Toggle Active / Suspended">
                ${p.status === 'active' ? '⏸️' : '▶️'}
              </button>
            </div>
          </td>
        </tr>
      `;
    }).join('');
  }

  function openAffiliateCreateModal() {
    openModal('modal-affiliate-create');
  }

  async function handleCreateAffiliate(e) {
    e.preventDefault();
    const code = document.getElementById('aff-create-code').value;
    const partner_name = document.getElementById('aff-create-name').value;
    const email = document.getElementById('aff-create-email').value;
    const channel = document.getElementById('aff-create-channel').value;
    const tier = document.getElementById('aff-create-tier').value;
    const commission_rate = document.getElementById('aff-create-rate').value;

    try {
      await api('/admin/affiliates', {
        method: 'POST',
        body: { code, partner_name, email, channel, tier, commission_rate }
      });

      closeModal('modal-affiliate-create');
      toast && toast(`Affiliate partner ${code} onboarded successfully!`, 'success');
      loadAffiliatesDashboard();
    } catch (err) {
      toast && toast(err.message, 'error');
    }
  }

  async function openAffiliateDossier(id) {
    try {
      const p = await api(`/admin/affiliates/${id}`);
      const container = document.getElementById('affiliate-dossier-content');
      if (!container) return;

      container.innerHTML = `
        <div style="background:#1E293B;border-radius:10px;padding:16px;margin-bottom:16px;display:flex;align-items:center;justify-content:space-between">
          <div>
            <span style="color:#94A3B8;font-size:0.75rem;text-transform:uppercase;font-weight:700">Affiliate Tracking Code</span>
            <h2 style="margin:2px 0 0;color:#10B981;font-family:monospace;font-size:1.4rem">${escapeHtml(p.code)}</h2>
            <small style="color:#CBD5E1">${escapeHtml(p.partner_name)} (${escapeHtml(p.channel)})</small>
          </div>
          <div style="text-align:right">
            <span class="badge-chip" style="background:rgba(59,130,246,0.2);color:#60A5FA;font-weight:700;font-size:0.9rem">Commission: ${p.commission_rate}% Rev-Share</span>
          </div>
        </div>

        <div class="adm-kpi-grid" style="grid-template-columns:repeat(4, 1fr);gap:10px;margin-bottom:16px">
          <div class="adm-kpi-card" style="padding:10px;background:#0F172A">
            <small style="color:#94A3B8;font-size:0.75rem">Clicks / Visits</small>
            <b style="color:#fff;font-size:1.1rem">${(p.clicks || 0).toLocaleString()}</b>
          </div>
          <div class="adm-kpi-card" style="padding:10px;background:#0F172A">
            <small style="color:#94A3B8;font-size:0.75rem">Conversions</small>
            <b style="color:#34D399;font-size:1.1rem">${(p.conversions || 0).toLocaleString()}</b>
          </div>
          <div class="adm-kpi-card" style="padding:10px;background:#0F172A">
            <small style="color:#94A3B8;font-size:0.75rem">Attributed GMV</small>
            <b style="color:#60A5FA;font-size:1.1rem">৳${(p.gmv_attributed || 0).toLocaleString()}</b>
          </div>
          <div class="adm-kpi-card" style="padding:10px;background:#0F172A">
            <small style="color:#94A3B8;font-size:0.75rem">Pending Balance</small>
            <b style="color:#F59E0B;font-size:1.1rem">৳${(p.pending_commission || 0).toLocaleString()}</b>
          </div>
        </div>

        <div style="background:#0F172A;border-radius:8px;padding:12px;margin-bottom:16px;border:1px solid rgba(255,255,255,0.06)">
          <small style="color:#94A3B8;font-weight:700">HISTORICAL PAYOUT DISBURSEMENTS</small>
          <div style="margin-top:8px">
            ${(p.payouts && p.payouts.length > 0) ? p.payouts.map(pay => `
              <div style="display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px solid rgba(255,255,255,0.04);font-size:0.84rem">
                <span><b>${escapeHtml(pay.trx_id)}</b> via ${escapeHtml(pay.method)}</span>
                <span style="color:#10B981;font-weight:700">৳${pay.amount?.toLocaleString()} BDT</span>
              </div>
            `).join('') : '<p style="color:#64748B;margin:4px 0;font-size:0.84rem">No prior payout disbursements.</p>'}
          </div>
        </div>

        <div style="display:flex;justify-content:flex-end;gap:10px">
          <button class="btn btn-outline-light btn-sm" onclick="closeModal('modal-affiliate-dossier')">Close</button>
          ${p.pending_commission > 0 ? `
            <button class="btn btn-green btn-sm" onclick="closeModal('modal-affiliate-dossier');openAffiliatePayoutModal('${p.id}', '${escapeHtml(p.partner_name)}', '${escapeHtml(p.code)}', ${p.pending_commission})">Disburse ৳${p.pending_commission}</button>
          ` : ''}
        </div>
      `;

      openModal('modal-affiliate-dossier');
    } catch (err) {
      toast && toast(err.message, 'error');
    }
  }

  function openAffiliatePayoutModal(id, name, code, pending) {
    document.getElementById('aff-payout-id').value = id;
    document.getElementById('aff-payout-partner-display').value = `${name} (${code})`;
    document.getElementById('aff-payout-amount').value = pending || 1000;
    openModal('modal-affiliate-payout');
  }

  async function handleProcessAffiliatePayout(e) {
    e.preventDefault();
    const id = document.getElementById('aff-payout-id').value;
    const amount = document.getElementById('aff-payout-amount').value;
    const method = document.getElementById('aff-payout-method').value;

    try {
      await api(`/admin/affiliates/${id}/payout`, {
        method: 'POST',
        body: { amount, method }
      });

      closeModal('modal-affiliate-payout');
      toast && toast(`Disbursed ৳${amount} BDT commission successfully!`, 'success');
      loadAffiliatesDashboard();
    } catch (err) {
      toast && toast(err.message, 'error');
    }
  }

  async function toggleAffiliateStatus(id, currentStatus) {
    const nextStatus = currentStatus === 'active' ? 'suspended' : 'active';
    try {
      await api(`/admin/affiliates/${id}`, {
        method: 'PATCH',
        body: { status: nextStatus }
      });
      toast && toast(`Affiliate status updated to ${nextStatus}`, 'success');
      loadAffiliatesDashboard();
    } catch (err) {
      toast && toast(err.message, 'error');
    }
  }

