  // ==========================================
  // 14D. OMNICHANNEL MARKETING CAMPAIGNS CONTROLLER
  // ==========================================
  let campaignSearchDebounce = null;
  function handleCampaignSearch(val) {
    clearTimeout(campaignSearchDebounce);
    campaignSearchDebounce = setTimeout(() => {
      loadCampaignsDashboard();
    }, 250);
  }

  async function loadCampaignsDashboard() {
    try {
      const q = document.getElementById('cmp-search-input')?.value || '';
      const channel = document.getElementById('cmp-channel-filter')?.value || 'all';
      const status = document.getElementById('cmp-status-filter')?.value || 'all';

      const [kpis, data] = await Promise.all([
        api('/admin/campaigns/kpis'),
        api(`/admin/campaigns?q=${encodeURIComponent(q)}&channel=${channel}&status=${status}`)
      ]);

      if (kpis) {
        setElText('cmp-kpi-active', (kpis.active_campaigns || 0).toLocaleString());
        setElText('cmp-kpi-reach', (kpis.total_reach || 0).toLocaleString());
        setElText('cmp-kpi-clicks', (kpis.total_clicks || 0).toLocaleString());
        setElText('cmp-kpi-ctr-sub', `${kpis.average_ctr_pct || 0}% Avg CTR`);
        setElText('cmp-kpi-conversions', (kpis.total_conversions || 0).toLocaleString());
        setElText('cmp-kpi-spend', `৳${(kpis.total_spend || 0).toLocaleString('en-US', { minimumFractionDigits: 2 })}`);
        setElText('cmp-kpi-budget-sub', `of ৳${(kpis.total_budget || 0).toLocaleString()} Budget`);
        setElText('cmp-kpi-roi', `${kpis.overall_roi || 0}x`);
      }

      renderCampaignsTable(data?.items || []);
    } catch (err) {
      toast && toast(err.message, 'error');
    }
  }

  function renderCampaignsTable(items) {
    const tbody = document.getElementById('campaigns-table-body');
    if (!tbody) return;

    if (!items || items.length === 0) {
      tbody.innerHTML = `<tr><td colspan="10" style="text-align:center;padding:30px;color:#94A3B8">No marketing campaigns found.</td></tr>`;
      return;
    }

    tbody.innerHTML = items.map(c => {
      const ctr = c.reach > 0 ? +((c.clicks / c.reach) * 100).toFixed(1) : 0;
      return `
        <tr>
          <td><b style="color:#fff;font-size:0.95rem">${escapeHtml(c.title)}</b></td>
          <td><span class="badge-chip" style="background:#1E293B;color:#fff">${escapeHtml(c.channel)}</span></td>
          <td><small style="color:#CBD5E1">${escapeHtml(c.target_segment)}</small></td>
          <td>
            <span style="color:#10B981;font-weight:700">৳${(c.spend || 0).toLocaleString()}</span>
            <small style="color:#94A3B8;display:block">Cap: ৳${(c.budget || 0).toLocaleString()}</small>
          </td>
          <td>
            <span style="color:#fff">${(c.reach || 0).toLocaleString()} Views</span>
            <small style="color:#60A5FA;display:block">${(c.clicks || 0).toLocaleString()} Clicks</small>
          </td>
          <td><b style="color:#F472B6">${ctr}%</b></td>
          <td><b style="color:#34D399">${(c.conversions || 0).toLocaleString()}</b></td>
          <td><b style="color:#22D3EE">${c.roi || 0}x</b></td>
          <td>
            <span class="badge-chip" style="background:${c.status === 'active' ? 'rgba(16,185,129,0.2)' : 'rgba(148,163,184,0.2)'};color:${c.status === 'active' ? '#34D399' : '#94A3B8'}">
              ${c.status}
            </span>
          </td>
          <td style="text-align:right">
            <div style="display:flex;gap:6px;justify-content:flex-end">
              <button class="btn btn-xs btn-outline-light" onclick="toggleCampaignStatus('${c.id}', '${c.status}')" title="Pause / Resume">
                ${c.status === 'active' ? '⏸️' : '▶️'}
              </button>
              <button class="btn btn-xs btn-outline-light" onclick="deleteCampaign('${c.id}')" title="Delete Campaign" style="color:#EF4444">🗑️</button>
            </div>
          </td>
        </tr>
      `;
    }).join('');
  }

  function openCampaignCreateModal() {
    const today = new Date().toISOString().slice(0, 10);
    document.getElementById('cmp-create-start').value = today;
    document.getElementById('cmp-create-end').value = '2026-12-31';
    openModal('modal-campaign-create');
  }

  async function handleCreateCampaign(e) {
    e.preventDefault();
    const title = document.getElementById('cmp-create-title').value;
    const channel = document.getElementById('cmp-create-channel').value;
    const target_segment = document.getElementById('cmp-create-segment').value;
    const budget = document.getElementById('cmp-create-budget').value;
    const start_date = document.getElementById('cmp-create-start').value;
    const end_date = document.getElementById('cmp-create-end').value;

    try {
      await api('/admin/campaigns', {
        method: 'POST',
        body: { title, channel, target_segment, budget, start_date, end_date }
      });

      closeModal('modal-campaign-create');
      toast && toast(`Campaign '${title}' launched successfully!`, 'success');
      loadCampaignsDashboard();
    } catch (err) {
      toast && toast(err.message, 'error');
    }
  }

  async function toggleCampaignStatus(id, currentStatus) {
    const nextStatus = currentStatus === 'active' ? 'paused' : 'active';
    try {
      await api(`/admin/campaigns/${id}`, {
        method: 'PATCH',
        body: { status: nextStatus }
      });
      toast && toast(`Campaign status updated to ${nextStatus}`, 'success');
      loadCampaignsDashboard();
    } catch (err) {
      toast && toast(err.message, 'error');
    }
  }

  async function deleteCampaign(id) {
    if (!confirm('Are you sure you want to delete this marketing campaign?')) return;
    try {
      await api(`/admin/campaigns/${id}`, { method: 'DELETE' });
      toast && toast('Campaign deleted.', 'info');
      loadCampaignsDashboard();
    } catch (err) {
      toast && toast(err.message, 'error');
    }
  }

