  function renderFeaturedTasksTable(items) {
    const tbody = document.getElementById('featured-tasks-table-body');
    if (!tbody) return;

    if (!items || items.length === 0) {
      tbody.innerHTML = `<tr><td colspan="10" style="text-align:center;padding:30px;color:#94A3B8">No featured tasks found.</td></tr>`;
      return;
    }

    tbody.innerHTML = items.map(t => {
      let tierBadge = '';
      if (t.placement_tier === 'homepage_hero') tierBadge = '<span class="badge-chip" style="background:rgba(139,92,246,0.2);color:#A78BFA;font-weight:700">👑 Homepage Hero</span>';
      else if (t.placement_tier === 'category_top_pin') tierBadge = '<span class="badge-chip" style="background:rgba(59,130,246,0.2);color:#60A5FA;font-weight:700">📌 Category Pin</span>';
      else tierBadge = '<span class="badge-chip" style="background:rgba(245,158,11,0.2);color:#FBBF24;font-weight:700">🔥 Urgent Flame</span>';

      return `
        <tr>
          <td>
            <b style="color:#fff;font-size:0.95rem;display:block">${escapeHtml(t.task_title)}</b>
            <small style="color:#94A3B8">Task #${t.task_id}</small>
          </td>
          <td><span style="color:#CBD5E1">${escapeHtml(t.client_name)}</span></td>
          <td>${tierBadge}</td>
          <td><b style="color:#10B981">৳${t.daily_fee}/day</b></td>
          <td>
            <span style="color:#fff">${t.days_active} Days</span>
            <small style="color:#60A5FA;display:block">Spent: ৳${t.total_spent}</small>
          </td>
          <td>
            <span style="color:#fff">${(t.impressions || 0).toLocaleString()} Views</span>
            <small style="color:#A78BFA;display:block">${(t.clicks || 0).toLocaleString()} Clicks</small>
          </td>
          <td><b style="color:#F472B6">${t.bids_count || 0} Bids</b></td>
          <td><small style="color:#94A3B8">${t.expires_at || 'N/A'}</small></td>
          <td>
            <span class="badge-chip" style="background:${t.status === 'active' ? 'rgba(16,185,129,0.2)' : 'rgba(148,163,184,0.2)'};color:${t.status === 'active' ? '#34D399' : '#94A3B8'}">
              ${t.status}
            </span>
          </td>
          <td style="text-align:right">
            <button class="btn btn-xs btn-outline-light" onclick="removeFeaturedTask('${t.id}')" title="Remove Placement" style="color:#EF4444">🛑</button>
          </td>
        </tr>
      `;
    }).join('');
  }

