  async function loadFeaturedProsDashboard() {
    try {
      const q = document.getElementById('feat-pro-search-input')?.value || '';
      const tier = document.getElementById('feat-pro-tier-filter')?.value || 'all';
      const status = document.getElementById('feat-pro-status-filter')?.value || 'all';

      const [kpis, data] = await Promise.all([
        api('/admin/featured-pros/kpis'),
        api(`/admin/featured-pros?q=${encodeURIComponent(q)}&spotlight_tier=${tier}&status=${status}`)
      ]);

      if (kpis) {
        setElText('feat-pro-kpi-active', (kpis.active_spotlights || 0).toLocaleString());
        setElText('feat-pro-kpi-boost', `+${kpis.average_view_boost_pct || 420}%`);
        setElText('feat-pro-kpi-inquiries', (kpis.total_direct_inquiries || 0).toLocaleString());
        setElText('feat-pro-kpi-rating', `${kpis.average_rating || 4.92} ★`);
      }

      renderFeaturedProsTable(data?.items || []);
    } catch (err) {
      toast && toast(err.message, 'error');
    }
  }

