  function switchLoyaltyTab(tab) {
    const tabUsers = document.getElementById('loyalty-tab-users');
    const tabRewards = document.getElementById('loyalty-tab-rewards');
    const btnUsers = document.getElementById('loy-tab-btn-users');
    const btnRewards = document.getElementById('loy-tab-btn-rewards');

    if (tab === 'rewards') {
      if (tabUsers) tabUsers.style.display = 'none';
      if (tabRewards) tabRewards.style.display = 'block';
      if (btnUsers) btnUsers.classList.remove('active');
      if (btnRewards) btnRewards.classList.add('active');
      loadLoyaltyRewardsTable();
    } else {
      if (tabUsers) tabUsers.style.display = 'block';
      if (tabRewards) tabRewards.style.display = 'none';
      if (btnUsers) btnUsers.classList.add('active');
      if (btnRewards) btnRewards.classList.remove('active');
      loadLoyaltyDashboard();
    }
  }

  async function loadLoyaltyDashboard() {
    try {
      const q = document.getElementById('loy-user-search')?.value || '';
      const level = document.getElementById('loy-level-filter')?.value || 'all';
      const role = document.getElementById('loy-role-filter')?.value || 'all';

      const [kpis, data] = await Promise.all([
        api('/admin/loyalty/kpis'),
        api(`/admin/loyalty/users?q=${encodeURIComponent(q)}&level=${level}&role=${role}`)
      ]);

      if (kpis) {
        setElText('loy-kpi-members', (kpis.total_members || 0).toLocaleString());
        setElText('loy-kpi-avg-xp', `${(kpis.average_xp || 0).toLocaleString()} XP`);
        setElText('loy-kpi-points', `${(kpis.total_points_in_circulation || 0).toLocaleString()} pts`);
        setElText('loy-kpi-redemptions', (kpis.total_rewards_redeemed || 0).toLocaleString());
        setElText('loy-kpi-titans', (kpis.max_level_members || 0).toLocaleString());
      }

      renderUserLoyaltyTable(data?.items || []);
    } catch (err) {
      toast && toast(err.message, 'error');
    }
  }

  function renderUserLoyaltyTable(items) {
    const tbody = document.getElementById('loyalty-users-table-body');
    if (!tbody) return;

    if (!items || items.length === 0) {
      tbody.innerHTML = `<tr><td colspan="9" style="text-align:center;padding:30px;color:#94A3B8">No loyalty members found.</td></tr>`;
      return;
    }

    tbody.innerHTML = items.map((u, idx) => {
      let levelCrest = '';
      if (u.level === 6) levelCrest = '⚡ Level 6 (Titan)';
      else if (u.level === 5) levelCrest = '👑 Level 5 (Diamond)';
      else if (u.level === 4) levelCrest = '💎 Level 4 (Platinum)';
      else if (u.level === 3) levelCrest = '🥇 Level 3 (Gold)';
      else if (u.level === 2) levelCrest = '🥈 Level 2 (Silver)';
      else levelCrest = '🥉 Level 1 (Bronze)';

      return `
        <tr>
          <td>
            <div style="display:flex;align-items:center;gap:10px">
              <span style="font-weight:800;color:#64748B;font-size:0.9rem">#${idx + 1}</span>
              <div>
                <b style="color:#fff;display:block">${escapeHtml(u.name)}</b>
                <small style="color:#94A3B8">User ID: #${u.user_id}</small>
              </div>
            </div>
          </td>
          <td><span class="badge-chip" style="background:#1E293B;color:#fff">${escapeHtml(u.role)}</span></td>
          <td><b style="color:#A78BFA">${levelCrest}</b></td>
          <td><b style="color:#34D399">${(u.xp || 0).toLocaleString()} XP</b></td>
          <td><b style="color:#FBBF24">🔥 ${u.streak_days || 0} Days</b></td>
          <td><span style="color:#CBD5E1">${u.tasks_delivered || 0} Tasks</span></td>
          <td><b style="color:#F472B6">🪙 ${(u.points_balance || 0).toLocaleString()}</b></td>
          <td>
            <div style="display:flex;gap:4px;flex-wrap:wrap">
              ${(u.badges || []).map(b => `<span class="badge-chip" style="background:rgba(139,92,246,0.15);color:#A78BFA;font-size:0.7rem">${escapeHtml(b)}</span>`).join('')}
            </div>
          </td>
          <td style="text-align:right">
            <button class="btn btn-xs btn-purple" onclick="openLoyaltyAdjustModal('${u.user_id}', '${escapeHtml(u.name)}')" title="Adjust XP / Points">⚡ Adjust</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  async function loadLoyaltyRewardsTable() {
    try {
      const res = await api('/admin/loyalty/rewards');
      const items = res?.items || [];
      const tbody = document.getElementById('loyalty-rewards-table-body');
      if (!tbody) return;

      tbody.innerHTML = items.map(r => `
        <tr>
          <td><b style="color:#fff;font-size:0.95rem">${escapeHtml(r.title)}</b></td>
          <td><span class="badge-chip" style="background:#1E293B;color:#fff">${escapeHtml(r.reward_type)}</span></td>
          <td><b style="color:#F472B6">🪙 ${r.points_cost} pts</b></td>
          <td><span style="color:#34D399;font-weight:700">Value: ${r.reward_value}</span></td>
          <td><b style="color:#60A5FA">${r.redemptions_count || 0} Used</b></td>
          <td>
            <span class="badge-chip" style="background:${r.status === 'active' ? 'rgba(16,185,129,0.2)' : 'rgba(239,68,68,0.2)'};color:${r.status === 'active' ? '#34D399' : '#F87171'}">
              ${r.status}
            </span>
          </td>
          <td style="text-align:right">
            <button class="btn btn-xs btn-outline-light" onclick="toggleLoyaltyReward('${r.id}')">
              ${r.status === 'active' ? 'Deactivate' : 'Activate'}
            </button>
          </td>
        </tr>
      `).join('');
    } catch (err) {
      toast && toast(err.message, 'error');
    }
  }

