async function loadHelpTicketsList() {
  const searchInput = document.getElementById('help-tickets-search');
  const statusSelect = document.getElementById('help-tickets-filter-status');
  const prioSelect = document.getElementById('help-tickets-filter-priority');

  const q = searchInput ? searchInput.value.trim() : '';
  const status = statusSelect ? statusSelect.value : 'all';
  const priority = prioSelect ? prioSelect.value : 'all';

  const tbody = document.getElementById('help-tickets-table-body');
  if (!tbody) return;

  tbody.innerHTML = '<tr><td colspan="8" style="text-align:center;padding:24px;color:#94A3B8">Loading support ticket queue...</td></tr>';

  try {
    const params = new URLSearchParams();
    if (q) params.append('q', q);
    if (status !== 'all') params.append('status', status);
    if (priority !== 'all') params.append('priority', priority);

    const res = await api(`/admin/help-center/tickets?${params.toString()}`);
    currentHelpTicketsCache = res.items || [];

    if (!currentHelpTicketsCache.length) {
      tbody.innerHTML = '<tr><td colspan="8" style="text-align:center;padding:24px;color:#64748B">No support tickets match the selected filter.</td></tr>';
      return;
    }

    tbody.innerHTML = currentHelpTicketsCache.map(t => {
      let prioBadge = '<span class="adm-badge-role" style="background:rgba(148,163,184,0.15);color:#94A3B8">Normal</span>';
      if (t.priority === 'urgent') prioBadge = '<span class="adm-badge-role alert" style="background:rgba(239,68,68,0.2);color:#F87171;border:1px solid #EF4444">Urgent</span>';
      else if (t.priority === 'high') prioBadge = '<span class="adm-badge-role warning" style="background:rgba(245,158,11,0.2);color:#FBBF24">High</span>';

      let statusBadge = '<span class="adm-badge-role pro" style="background:rgba(16,185,129,0.15);color:#34D399">Open</span>';
      if (t.status === 'in_progress') statusBadge = '<span class="adm-badge-role" style="background:rgba(56,189,248,0.15);color:#38BDF8">In Progress</span>';
      else if (t.status === 'waiting_client') statusBadge = '<span class="adm-badge-role warning" style="background:rgba(245,158,11,0.15);color:#FBBF24">Waiting Client</span>';
      else if (t.status === 'resolved') statusBadge = '<span class="adm-badge-role online" style="background:rgba(16,185,129,0.15);color:#10B981">Resolved</span>';

      return `
        <tr>
          <td><b style="color:#A78BFA;font-family:monospace">${t.ticket_code}</b></td>
          <td>
            <div style="font-weight:700;color:#fff;font-size:0.85rem">${escapeHtml(t.requester_name)}</div>
            <small style="color:#94A3B8">${escapeHtml(t.requester_email)} · <span style="text-transform:capitalize;color:#38BDF8">${t.user_role}</span></small>
          </td>
          <td>
            <div style="color:#F8FAFC;font-weight:600">${escapeHtml(t.subject)}</div>
            <small style="color:#64748B">${t.category}</small>
          </td>
          <td>${prioBadge}</td>
          <td>${statusBadge}</td>
          <td><small style="color:#F59E0B">⏳ ${t.sla_deadline || 'Within 2h'}</small></td>
          <td><small style="color:#94A3B8">${t.created_at}</small></td>
          <td style="text-align:right">
            <button class="btn btn-purple btn-sm" onclick="openHelpTicketReplyModal(${t.id})">💬 Reply &amp; Resolve</button>
          </td>
        </tr>
      `;
    }).join('');
  } catch (err) {
    tbody.innerHTML = `<tr><td colspan="8" style="text-align:center;padding:20px;color:#F87171">Failed to load tickets: ${escapeHtml(err.message)}</td></tr>`;
  }
}

async function openHelpTicketReplyModal(id) {
  try {
    const ticket = await api(`/admin/help-center/tickets/${id}`);
    if (!ticket) return;

    document.getElementById('modal-ticket-id').value = ticket.id;
    document.getElementById('modal-ticket-title').textContent = `${ticket.ticket_code}: ${ticket.subject}`;
    document.getElementById('modal-ticket-subtitle').textContent = `Requester: ${ticket.requester_name} (${ticket.requester_email}) · Priority: ${ticket.priority.toUpperCase()}`;
    document.getElementById('modal-ticket-status').value = ticket.status === 'open' ? 'in_progress' : ticket.status;
    document.getElementById('modal-ticket-reply-text').value = '';

    const threadBox = document.getElementById('modal-ticket-thread');
    if (threadBox) {
      threadBox.innerHTML = (ticket.replies || []).map(r => `
        <div style="background:${r.role === 'agent' ? 'rgba(139,92,246,0.15)' : 'rgba(255,255,255,0.05)'};border-left:3px solid ${r.role === 'agent' ? '#8B5CF6' : '#38BDF8'};padding:10px 12px;border-radius:6px">
          <div style="display:flex;justify-content:space-between;margin-bottom:4px;font-size:0.75rem">
            <b style="color:${r.role === 'agent' ? '#A78BFA' : '#38BDF8'}">${escapeHtml(r.sender)}</b>
            <span style="color:#64748B">${r.created_at}</span>
          </div>
          <div style="color:#E2E8F0;font-size:0.83rem;line-height:1.4">${escapeHtml(r.text)}</div>
        </div>
      `).join('');
    }

    openModal('modal-help-ticket-reply');
  } catch (err) {
    toast && toast(err.message, 'error');
  }
}

