let currentBannersCache = [];
let currentBannerPlacementsCache = [];
let currentBannerAbTestsCache = [];

async function loadBannersDashboard() {
  await Promise.all([
    loadBannersKPIs(),
    loadBannersTable(),
    loadBannersPlacementsList(),
    loadBannersAbTests(),
    loadBannersAnalytics()
  ]);
  updateStorefrontSimulator();
}

async function loadBannersKPIs() {
  try {
    const res = await api('/admin/banners/kpis');
    if (!res) return;

    const elAct = document.getElementById('banners-kpi-active');
    if (elAct) elAct.textContent = `${res.active_banners} Banners`;

    const elImpr = document.getElementById('banners-kpi-impressions');
    if (elImpr) elImpr.textContent = Number(res.impressions_24h || 0).toLocaleString();

    const elClicks = document.getElementById('banners-kpi-clicks');
    if (elClicks) elClicks.textContent = Number(res.clicks_24h || 0).toLocaleString();

    const elCtr = document.getElementById('banners-kpi-ctr');
    if (elCtr) elCtr.textContent = `${res.avg_ctr} Average CTR`;

    const elRev = document.getElementById('banners-kpi-revenue');
    if (elRev) elRev.textContent = res.attributed_gmv || '৳542,000';

    const elAb = document.getElementById('banners-kpi-ab-tests');
    if (elAb) elAb.textContent = `${res.active_ab_tests} Running`;

    const elTop = document.getElementById('banners-kpi-top-slot');
    if (elTop) elTop.textContent = res.top_placement || 'Hero Carousel';
  } catch (err) {
    console.error('Failed to load Banners KPIs:', err);
  }
}

function switchBannerTab(tabName) {
  const tabs = ['registry', 'composer', 'placements', 'ab-testing', 'analytics', 'live-simulator'];
  tabs.forEach(t => {
    const btn = document.getElementById(`banners-tab-btn-${t}`);
    const panel = document.getElementById(`banners-subtab-${t}`);
    if (btn) btn.classList.toggle('active', t === tabName);
    if (panel) panel.style.display = (t === tabName) ? 'block' : 'none';
  });

  if (tabName === 'registry') loadBannersTable();
  else if (tabName === 'composer') updateLiveBannerPreview();
  else if (tabName === 'placements') loadBannersPlacementsList();
  else if (tabName === 'ab-testing') loadBannersAbTests();
  else if (tabName === 'analytics') loadBannersAnalytics();
  else if (tabName === 'live-simulator') updateStorefrontSimulator();
}

async function loadBannersTable() {
  const searchInput = document.getElementById('banners-search');
  const placementSelect = document.getElementById('banners-filter-placement');
  const audienceSelect = document.getElementById('banners-filter-audience');
  const statusSelect = document.getElementById('banners-filter-status');

  const q = searchInput ? searchInput.value.trim() : '';
  const placement = placementSelect ? placementSelect.value : 'all';
  const audience = audienceSelect ? audienceSelect.value : 'all';
  const status = statusSelect ? statusSelect.value : 'all';

  const tbody = document.getElementById('banners-table-body');
  if (!tbody) return;

  tbody.innerHTML = '<tr><td colspan="8" style="text-align:center;padding:24px;color:#94A3B8">Loading promotional banners...</td></tr>';

  try {
    const params = new URLSearchParams();
    if (q) params.append('q', q);
    if (placement !== 'all') params.append('placement', placement);
    if (audience !== 'all') params.append('audience', audience);
    if (status !== 'all') params.append('status', status);

    const res = await api(`/admin/banners?${params.toString()}`);
    currentBannersCache = res.items || [];

    if (!currentBannersCache.length) {
      tbody.innerHTML = '<tr><td colspan="8" style="text-align:center;padding:24px;color:#64748B">No promotional banners match your filters.</td></tr>';
      return;
    }

    tbody.innerHTML = currentBannersCache.map(b => {
      const statusPill = b.status === 'active'
        ? '<span class="adm-badge-role pro" style="background:rgba(16,185,129,0.15);color:#34D399;border:1px solid rgba(16,185,129,0.3)">Active</span>'
        : '<span class="adm-badge-role" style="background:rgba(148,163,184,0.15);color:#94A3B8;border:1px solid rgba(148,163,184,0.3)">Paused</span>';

      return `
        <tr>
          <td>
            <div style="display:flex;align-items:center;gap:10px">
              <div style="width:48px;height:28px;border-radius:6px;background:${b.gradient_theme || '#059669'};box-shadow:0 2px 8px rgba(0,0,0,0.3);flex-shrink:0"></div>
              <div>
                <b style="color:#A78BFA;font-family:monospace;font-size:0.8rem">${b.code}</b>
                <small style="color:#64748B;display:block">Order: #${b.sort_order || 1}</small>
              </div>
            </div>
          </td>
          <td>
            <div style="font-weight:700;color:#fff;font-size:0.88rem">${escapeHtml(b.title)}</div>
            <small style="color:#94A3B8">${escapeHtml(b.tagline || '')}</small>
          </td>
          <td>
            <span style="background:rgba(56,189,248,0.1);color:#38BDF8;padding:3px 8px;border-radius:6px;font-size:0.75rem;font-weight:600">
              ${escapeHtml(b.placement_name || b.placement_code)}
            </span>
          </td>
          <td>
            <div style="font-size:0.78rem;color:#E2E8F0;text-transform:capitalize">${b.audience}</div>
            <small style="color:#10B981">${escapeHtml(b.cta_text || 'CTA')} → ${escapeHtml(b.cta_url || '')}</small>
          </td>
          <td>
            <div style="font-weight:700;color:#F8FAFC">${Number(b.impressions_count || 0).toLocaleString()} <span style="font-weight:400;font-size:0.75rem;color:#94A3B8">impr</span></div>
            <small style="color:#F59E0B">⚡ ${Number(b.clicks_count || 0).toLocaleString()} clicks (<b>${b.ctr || '0%'}</b>)</small>
          </td>
          <td>
            <span style="color:#34D399;font-weight:700">৳${Number(b.attributed_revenue || 0).toLocaleString()}</span>
          </td>
          <td>${statusPill}</td>
          <td style="text-align:right">
            <div style="display:inline-flex;gap:6px">
              <button class="btn btn-outline-light btn-sm" onclick="openViewBannerModal(${b.id})" title="View Banner Showcase" style="color:#38BDF8;font-weight:700">👁️ View</button>
              <button class="btn btn-outline-light btn-sm" onclick="openBannerEditor(${b.id})" title="Edit in Studio">✏️</button>
              <button class="btn btn-outline-light btn-sm" onclick="handleDuplicateBanner(${b.id})" title="Clone as Draft">📋</button>
              <button class="btn btn-outline-light btn-sm" onclick="handleToggleBannerStatus(${b.id})" title="Toggle Active/Paused">${b.status === 'active' ? '⏸️' : '▶️'}</button>
              <button class="btn btn-outline-light btn-sm" style="color:#F87171" onclick="handleDeleteBanner(${b.id})" title="Delete Banner">🗑️</button>
            </div>
          </td>
        </tr>
      `;
    }).join('');
  } catch (err) {
    tbody.innerHTML = `<tr><td colspan="8" style="text-align:center;padding:20px;color:#F87171">Failed to load banners: ${escapeHtml(err.message)}</td></tr>`;
  }
}

async function openBannerEditor(id) {
  try {
    const banner = id ? await api(`/admin/banners/${id}`) : null;

    document.getElementById('banner-editor-id').value = banner ? banner.id : '';
    document.getElementById('banner-editor-title').value = banner ? banner.title : '⚡ 50% Cashback on Tasks';
    document.getElementById('banner-editor-tagline').value = banner ? banner.tagline : 'Deposit escrow and get instant bonus back in your wallet.';
    document.getElementById('banner-editor-placement').value = banner ? banner.placement_code : 'homepage_hero';
    document.getElementById('banner-editor-audience').value = banner ? banner.audience : 'all';
    document.getElementById('banner-editor-badge').value = banner ? (banner.badge_text || 'PROMO') : 'LIMITED TIME OFFER';
    document.getElementById('banner-editor-cta-text').value = banner ? (banner.cta_text || 'Get Started →') : 'Claim Offer →';
    document.getElementById('banner-editor-cta-url').value = banner ? (banner.cta_url || '/tasks') : '/tasks';
    document.getElementById('banner-editor-status').value = banner ? banner.status : 'active';
    document.getElementById('banner-editor-start-date').value = banner ? banner.start_date : new Date().toISOString().substring(0, 10);
    document.getElementById('banner-editor-end-date').value = banner ? banner.end_date : '2026-12-31';
    const imgInput = document.getElementById('banner-editor-image');
    if (imgInput) imgInput.value = banner ? (banner.background_image || '') : '';

    if (banner && banner.gradient_theme) {
      setBannerGradient(banner.gradient_theme, banner.accent_color || '#10B981');
    } else {
      setBannerGradient('linear-gradient(135deg, #059669 0%, #10B981 50%, #047857 100%)', '#10B981');
    }

    const heading = document.getElementById('banner-editor-heading');
    if (heading) heading.textContent = banner ? `🎨 Edit Banner: ${banner.title}` : '🎨 Create New Promotional Banner';

    updateLiveBannerPreview();
    switchBannerTab('composer');
  } catch (err) {
    toast && toast(err.message, 'error');
  }
}

function setBannerGradient(gradientStr, accentColor) {
  document.getElementById('banner-editor-gradient').value = gradientStr;
  document.getElementById('banner-editor-accent').value = accentColor || '#10B981';
  updateLiveBannerPreview();
}

function updateLiveBannerPreview() {
  const title = document.getElementById('banner-editor-title')?.value || 'Promotional Banner Headline';
  const tagline = document.getElementById('banner-editor-tagline')?.value || 'Complete micro-tasks and earn instant bonus rewards.';
  const badge = document.getElementById('banner-editor-badge')?.value || 'SPECIAL OFFER';
  const ctaText = document.getElementById('banner-editor-cta-text')?.value || 'Explore Deals →';
  const gradient = document.getElementById('banner-editor-gradient')?.value || 'linear-gradient(135deg, #059669, #10B981)';
  const placement = document.getElementById('banner-editor-placement')?.value || 'homepage_hero';

  const bgImage = document.getElementById('banner-editor-image')?.value.trim() || '';
  const overlayOpacity = document.getElementById('banner-editor-overlay-opacity')?.value || '0.6';
  const previewBox = document.getElementById('banner-canvas-preview');
  if (!previewBox) return;

  const bgStyle = bgImage
    ? `background: linear-gradient(rgba(15,23,42,${overlayOpacity}), rgba(15,23,42,${overlayOpacity})), url('${bgImage}') center/cover no-repeat;`
    : `background:${gradient};`;

  previewBox.innerHTML = `
    <div style="${bgStyle}border-radius:14px;padding:32px 36px;color:#fff;box-shadow:0 10px 30px rgba(0,0,0,0.5);display:flex;justify-content:space-between;align-items:center;position:relative;overflow:hidden;min-height:160px">
      <div style="position:relative;z-index:2;max-width:70%">
        <div style="display:inline-block;background:rgba(0,0,0,0.3);backdrop-filter:blur(4px);border:1px solid rgba(255,255,255,0.25);border-radius:20px;padding:4px 14px;font-size:0.75rem;font-weight:800;letter-spacing:0.5px;margin-bottom:12px;color:#FEF08A">
          ✨ ${escapeHtml(badge)}
        </div>
        <h2 style="margin:0 0 8px;font-size:1.6rem;font-weight:900;color:#fff;text-shadow:0 2px 8px rgba(0,0,0,0.4)">${escapeHtml(title)}</h2>
        <p style="margin:0;font-size:0.95rem;color:rgba(255,255,255,0.9);line-height:1.4;text-shadow:0 1px 4px rgba(0,0,0,0.3)">${escapeHtml(tagline)}</p>
      </div>
      <div style="position:relative;z-index:2">
        <button style="background:#fff;color:#0F172A;font-weight:800;font-size:0.95rem;padding:14px 28px;border-radius:10px;border:none;box-shadow:0 6px 20px rgba(0,0,0,0.35);cursor:pointer;display:inline-flex;align-items:center;gap:8px">
          ${escapeHtml(ctaText)}
        </button>
      </div>
    </div>
  `;
}

async function handleSaveBanner() {
  const id = document.getElementById('banner-editor-id')?.value;
  const title = document.getElementById('banner-editor-title')?.value.trim();
  const tagline = document.getElementById('banner-editor-tagline')?.value.trim();
  const placement_code = document.getElementById('banner-editor-placement')?.value;
  const audience = document.getElementById('banner-editor-audience')?.value;
  const badge_text = document.getElementById('banner-editor-badge')?.value.trim();
  const cta_text = document.getElementById('banner-editor-cta-text')?.value.trim();
  const cta_url = document.getElementById('banner-editor-cta-url')?.value.trim();
  const status = document.getElementById('banner-editor-status')?.value;
  const start_date = document.getElementById('banner-editor-start-date')?.value;
  const end_date = document.getElementById('banner-editor-end-date')?.value;
  const gradient_theme = document.getElementById('banner-editor-gradient')?.value;
  const accent_color = document.getElementById('banner-editor-accent')?.value;
  const background_image = document.getElementById('banner-editor-image')?.value.trim() || '';

  if (!title) {
    toast && toast('Banner title is required', 'error');
    return;
  }

  const payload = { title, tagline, placement_code, audience, badge_text, cta_text, cta_url, status, start_date, end_date, gradient_theme, accent_color, background_image };

  try {
    if (id) {
      const res = await api(`/admin/banners/${id}`, { method: 'PUT', body: payload });
      toast && toast(res.message || 'Banner updated successfully', 'success');
    } else {
      const res = await api('/admin/banners', { method: 'POST', body: payload });
      document.getElementById('banner-editor-id').value = res.item.id;
      toast && toast(res.message || 'Banner created successfully', 'success');
    }
    loadBannersKPIs();
  } catch (err) {
    toast && toast(err.message, 'error');
  }
}

