function handleBannerImageUpload(e) {
  const file = e.target.files && e.target.files[0];
  if (!file) return;

  const reader = new FileReader();
  reader.onload = function(evt) {
    const dataUrl = evt.target.result;
    const imgInput = document.getElementById('banner-editor-image');
    if (imgInput) imgInput.value = dataUrl;
    updateLiveBannerPreview();
    toast && toast('Banner image loaded successfully!', 'success');
  };
  reader.readAsDataURL(file);
}

function setBannerImagePreset(url) {
  const imgInput = document.getElementById('banner-editor-image');
  if (imgInput) imgInput.value = url;
  updateLiveBannerPreview();
  toast && toast('Stock preset image applied!', 'success');
}

function clearBannerImage() {
  const imgInput = document.getElementById('banner-editor-image');
  if (imgInput) imgInput.value = '';
  const fileInput = document.getElementById('banner-editor-file-input');
  if (fileInput) fileInput.value = '';
  updateLiveBannerPreview();
  toast && toast('Image removed (gradient background active)', 'info');
}



