async function openViewBlogPostModal(id) {
  try {
    const post = await api(`/admin/blog/posts/${id}`);
    if (!post) return;

    document.getElementById('modal-blog-view-title').textContent = post.title;
    document.getElementById('modal-blog-view-slug').textContent = `/blog/${post.slug}`;
    document.getElementById('modal-blog-view-reads').textContent = Number(post.views_count || 0).toLocaleString();
    document.getElementById('modal-blog-view-shares').textContent = Number(post.social_shares || 0).toLocaleString();
    document.getElementById('modal-blog-view-time').textContent = `${post.reading_time_minutes || 4}m read`;
    document.getElementById('modal-blog-view-seo').textContent = `${post.seo_score || 96}/100`;

    const wrap = document.getElementById('modal-blog-view-cover-wrap');
    if (wrap && post.cover_image) {
      wrap.innerHTML = `<img src="${post.cover_image}" style="width:100%;height:220px;border-radius:10px;object-fit:cover;box-shadow:0 4px 16px rgba(0,0,0,0.3)" alt="Cover">`;
    }

    const editBtn = document.getElementById('modal-blog-view-edit-btn');
    if (editBtn) {
      editBtn.onclick = () => {
        closeModal('modal-blog-view');
        openBlogEditor(post.id);
      };
    }

    const tags = Array.isArray(post.tags) ? post.tags.join(', ') : (post.tags || 'General');
    document.getElementById('modal-blog-view-meta').textContent = `Author: ${post.author_name} (${post.author_role || ''}) · Category: ${post.category_name} · Tags: ${tags}`;

    const body = document.getElementById('modal-blog-view-body');
    if (body) {
      let parsed = (post.content_markdown || '')
        .replace(/^### (.*$)/gim, '<h3 style="color:#38BDF8;margin:16px 0 8px;font-size:1.15rem;font-weight:700">$1</h3>')
        .replace(/^## (.*$)/gim, '<h2 style="color:#fff;margin:20px 0 10px;font-size:1.35rem;font-weight:800">$1</h2>')
        .replace(/^# (.*$)/gim, '<h1 style="color:#fff;margin:24px 0 12px;font-size:1.55rem;font-weight:900">$1</h1>')
        .replace(/\> \[\!NOTE\]\n\> (.*$)/gim, '<div style="background:rgba(56,189,248,0.12);border-left:3px solid #38BDF8;padding:10px 14px;border-radius:6px;margin:10px 0;color:#BAE6FD">📌 <b>Note:</b> $1</div>')
        .replace(/\> \[\!IMPORTANT\]\n\> (.*$)/gim, '<div style="background:rgba(239,68,68,0.12);border-left:3px solid #EF4444;padding:10px 14px;border-radius:6px;margin:10px 0;color:#FECACA">⚠️ <b>Important:</b> $1</div>')
        .replace(/\*\*(.*?)\*\*/gim, '<strong style="color:#fff">$1</strong>')
        .replace(/\*(.*?)\*/gim, '<em>$1</em>')
        .replace(new RegExp('\\x60([^\\x60]+)\\x60', 'gim'), '<code style="background:#1E293B;color:#F472B6;padding:2px 5px;border-radius:4px;font-size:0.82rem">$1</code>')
        .replace(/\n/gim, '<br>');

      body.innerHTML = parsed;
    }

    openModal('modal-blog-view');
  } catch (err) {
    toast && toast(err.message, 'error');
  }
}

async function loadBlogCategoriesGrid() {
  const container = document.getElementById('blog-categories-grid');
  if (!container) return;

  try {
    const res = await api('/admin/blog/categories');
    const categories = res.items || [];

    container.innerHTML = categories.map(c => `
      <div style="background:#0F172A;border:1px solid rgba(255,255,255,0.08);border-radius:12px;padding:20px">
        <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:8px">
          <span style="font-size:1.8rem">${c.icon || '📁'}</span>
          <span style="background:rgba(56,189,248,0.15);color:#38BDF8;padding:2px 8px;border-radius:6px;font-size:0.75rem;font-weight:700">${c.post_count || 0} Articles</span>
        </div>
        <h4 style="margin:0 0 6px;color:#fff;font-size:0.95rem;font-weight:700">${escapeHtml(c.name)}</h4>
        <code style="color:#A78BFA;font-size:0.75rem;display:block;margin-bottom:8px">/category/${c.slug}</code>
        <p style="margin:0 0 14px;color:#94A3B8;font-size:0.78rem;line-height:1.4">${escapeHtml(c.description || '')}</p>
        <div style="display:flex;justify-content:flex-end">
          <button class="btn btn-outline-light btn-sm" style="color:#F87171;font-size:0.72rem" onclick="handleDeleteBlogCategory(${c.id})">Delete</button>
        </div>
      </div>
    `).join('');
  } catch (err) {
    container.innerHTML = `<div style="color:#F87171">Failed to load categories: ${escapeHtml(err.message)}</div>`;
  }
}

function openCreateBlogCategoryModal() {
  const form = document.getElementById('form-modal-blog-cat-create');
  if (form) form.reset();
  openModal('modal-blog-cat-create');
}

async function handleCreateBlogCategorySubmit(e) {
  e.preventDefault();
  const name = document.getElementById('modal-blog-cat-name').value.trim();
  const icon = document.getElementById('modal-blog-cat-icon').value.trim();
  const slug = document.getElementById('modal-blog-cat-slug').value.trim();
  const description = document.getElementById('modal-blog-cat-desc').value.trim();

  try {
    const res = await api('/admin/blog/categories', {
      method: 'POST',
      body: { name, icon, slug, description }
    });

    closeModal('modal-blog-cat-create');
    toast && toast(res.message || 'Category created', 'success');
    loadBlogCategoriesGrid();
  } catch (err) {
    toast && toast(err.message, 'error');
  }
}

async function handleDeleteBlogCategory(id) {
  if (!confirm('Are you sure you want to delete this editorial category?')) return;
  try {
    const res = await api(`/admin/blog/categories/${id}`, { method: 'DELETE' });
    toast && toast(res.message, 'success');
    loadBlogCategoriesGrid();
  } catch (err) {
    toast && toast(err.message, 'error');
  }
}

