// =========================================================================
// ENTERPRISE AI INTELLIGENCE & AUTOMATED QC CONTROLLER
// =========================================================================

let currentAiMatchesCache = [];
let currentAiModerationCache = [];

async function loadAiDashboard() {
  await Promise.all([
    loadAiKPIs(),
    loadAiMatchesTable(),
    loadAiModerationTable(),
    loadAiConfig()
  ]);
}

async function loadAiKPIs() {
  try {
    const res = await api('/admin/ai/kpis');
    if (!res) return;

    const elOps = document.getElementById('ai-kpi-ops');
    if (elOps) elOps.textContent = Number(res.automated_actions_24h || 0).toLocaleString();

    const elAcc = document.getElementById('ai-kpi-accuracy');
    if (elAcc) elAcc.textContent = res.match_accuracy || '97.4%';

    const elLat = document.getElementById('ai-kpi-latency');
    if (elLat) elLat.textContent = res.avg_inference_latency || '48ms';

    const elThr = document.getElementById('ai-kpi-threats');
    if (elThr) elThr.textContent = `${res.threats_prevented_24h} Scams`;

    const elBri = document.getElementById('ai-kpi-briefs');
    if (elBri) elBri.textContent = Number(res.task_briefs_generated || 0).toLocaleString();

    const elMod = document.getElementById('ai-kpi-model');
    if (elMod) elMod.textContent = res.active_model ? res.active_model.replace('Google DeepMind ', '') : 'Gemini 1.5 Flash';
  } catch (err) {
    console.error('Failed to load AI KPIs:', err);
  }
}

function switchAiTab(tabName) {
  const tabs = ['matching', 'moderation', 'task-gen', 'qc', 'config'];
  tabs.forEach(t => {
    const btn = document.getElementById(`ai-tab-btn-${t}`);
    const panel = document.getElementById(`ai-subtab-${t}`);
    if (btn) btn.classList.toggle('active', t === tabName);
    if (panel) panel.style.display = (t === tabName) ? 'block' : 'none';
  });

  if (tabName === 'matching') loadAiMatchesTable();
  else if (tabName === 'moderation') loadAiModerationTable();
  else if (tabName === 'config') loadAiConfig();
}

async function loadAiMatchesTable() {
  const searchInput = document.getElementById('ai-match-search');
  const q = searchInput ? searchInput.value.trim() : '';

  const tbody = document.getElementById('ai-matches-table-body');
  if (!tbody) return;

  tbody.innerHTML = '<tr><td colspan="7" style="text-align:center;padding:24px;color:#94A3B8">Calculating vector embeddings &amp; cosine similarity...</td></tr>';

  try {
    const params = new URLSearchParams();
    if (q) params.append('q', q);

    const res = await api(`/admin/ai/matches?${params.toString()}`);
    currentAiMatchesCache = res.items || [];

    if (!currentAiMatchesCache.length) {
      tbody.innerHTML = '<tr><td colspan="7" style="text-align:center;padding:24px;color:#64748B">No match vectors found.</td></tr>';
      return;
    }

    tbody.innerHTML = currentAiMatchesCache.map(m => {
      return `
        <tr>
          <td>
            <div style="font-weight:700;color:#fff;font-size:0.88rem">${escapeHtml(m.task_title)}</div>
            <code style="color:#38BDF8;font-size:0.75rem">Task ID #${m.task_id}</code>
          </td>
          <td>
            <div style="font-weight:700;color:#E2E8F0;font-size:0.85rem">👨‍💼 ${escapeHtml(m.worker_name)}</div>
            <span class="adm-badge-role pro" style="background:rgba(139,92,246,0.15);color:#A78BFA;font-size:0.7rem">${m.worker_level}</span>
          </td>
          <td>
            <div style="display:flex;align-items:center;gap:8px">
              <div style="width:60px;height:8px;background:#1E293B;border-radius:4px;overflow:hidden">
                <div style="width:${m.match_percentage};height:100%;background:linear-gradient(90deg, #10B981, #38BDF8);border-radius:4px"></div>
              </div>
              <b style="color:#34D399;font-size:0.88rem">${m.match_percentage}</b>
            </div>
            <small style="color:#64748B">Cosine: ${m.similarity_score}</small>
          </td>
          <td>
            <div style="display:flex;flex-wrap:wrap;gap:4px">
              ${(m.skill_overlaps || []).map(s => `<span style="background:rgba(56,189,248,0.12);color:#38BDF8;font-size:0.7rem;padding:2px 6px;border-radius:4px">${escapeHtml(s)}</span>`).join('')}
            </div>
          </td>
          <td>
            <span style="color:#FBBF24;font-weight:700">${m.estimated_completion_days} Days</span>
          </td>
          <td>
            <span style="background:rgba(16,185,129,0.15);color:#34D399;padding:3px 8px;border-radius:6px;font-size:0.75rem;font-weight:800">${m.confidence_level}</span>
          </td>
          <td>
            <span style="color:#A78BFA;font-weight:700;font-size:0.82rem">${escapeHtml(m.recommended_action)}</span>
          </td>
        </tr>
      `;
    }).join('');
  } catch (err) {
    tbody.innerHTML = `<tr><td colspan="7" style="text-align:center;padding:20px;color:#F87171">Failed to load matches: ${escapeHtml(err.message)}</td></tr>`;
  }
}

function openSimulateMatchModal() {
  openModal('modal-ai-match-simulate');
}

async function handleSimulateMatchSubmit(e) {
  e.preventDefault();
  const task_id = document.getElementById('modal-ai-sim-task').value;
  const worker_id = document.getElementById('modal-ai-sim-worker').value;

  try {
    const res = await api('/admin/ai/match-simulate', {
      method: 'POST',
      body: { task_id, worker_id }
    });

    closeModal('modal-ai-match-simulate');
    toast && toast(`AI Matchmaking synthesized: ${res.match.match_percentage} Cosine Similarity!`, 'success');
    loadAiMatchesTable();
    loadAiKPIs();
  } catch (err) {
    toast && toast(err.message, 'error');
  }
}

async function loadAiModerationTable() {
  const tbody = document.getElementById('ai-moderation-table-body');
  if (!tbody) return;

  try {
    const res = await api('/admin/ai/moderation');
    currentAiModerationCache = res.items || [];

    if (!currentAiModerationCache.length) {
      tbody.innerHTML = '<tr><td colspan="8" style="text-align:center;padding:24px;color:#64748B">No moderation alerts detected.</td></tr>';
      return;
    }

    tbody.innerHTML = currentAiModerationCache.map(l => {
      let sevBadge = '<span class="adm-badge-role warning" style="background:rgba(245,158,11,0.2);color:#FBBF24">Medium</span>';
      if (l.threat_severity === 'critical') sevBadge = '<span class="adm-badge-role alert" style="background:rgba(239,68,68,0.2);color:#F87171;border:1px solid #EF4444">🔴 Critical</span>';

      return `
        <tr>
          <td>
            <b style="color:#A78BFA;font-family:monospace;font-size:0.8rem">${l.code}</b>
            <span style="color:#64748B;font-size:0.72rem;display:block">${l.source_type}</span>
          </td>
          <td>
            <div style="font-weight:700;color:#fff;font-size:0.82rem">${escapeHtml(l.sender_name)}</div>
            <small style="color:#94A3B8">ID #${l.sender_id}</small>
          </td>
          <td style="max-width:280px">
            <div style="background:rgba(239,68,68,0.1);border-left:3px solid #EF4444;padding:6px 10px;border-radius:4px;color:#FECACA;font-size:0.8rem;line-height:1.4">
              "${escapeHtml(l.content_snippet)}"
            </div>
          </td>
          <td>
            <span style="color:#F472B6;font-weight:700;font-size:0.8rem">${escapeHtml(l.violation_type)}</span>
            <small style="color:#64748B;display:block">Confidence: ${(l.confidence_score * 100).toFixed(1)}%</small>
          </td>
          <td>${sevBadge}</td>
          <td>
            <code style="color:#38BDF8;font-size:0.75rem">${escapeHtml(l.auto_action_taken)}</code>
          </td>
          <td>
            <span style="background:rgba(239,68,68,0.15);color:#F87171;padding:2px 8px;border-radius:4px;font-size:0.72rem;font-weight:700;text-transform:uppercase">${l.status}</span>
          </td>
          <td style="text-align:right">
            <div style="display:inline-flex;gap:6px">
              <button class="btn btn-outline-light btn-sm" style="color:#34D399;font-size:0.72rem" onclick="handleActionAiModeration(${l.id}, 'approve')" title="Mark Cleared & False Positive">✓ Clear</button>
              <button class="btn btn-outline-light btn-sm" style="color:#F87171;font-size:0.72rem" onclick="handleActionAiModeration(${l.id}, 'ban_user')" title="Freeze Wallet & Restrict User">🚫 Ban</button>
            </div>
          </td>
        </tr>
      `;
    }).join('');
  } catch (err) {
    tbody.innerHTML = `<tr><td colspan="8" style="text-align:center;padding:20px;color:#F87171">Failed to load moderation logs: ${escapeHtml(err.message)}</td></tr>`;
  }
}

async function handleActionAiModeration(id, action) {
  try {
    const res = await api(`/admin/ai/moderation/${id}/action`, {
      method: 'POST',
      body: { action }
    });
    toast && toast(res.message, 'success');
    loadAiModerationTable();
    loadAiKPIs();
  } catch (err) {
    toast && toast(err.message, 'error');
  }
}

