function openCmsCommandPalette() {
  openModal('modal-cms-command-palette');
  const input = document.getElementById('cms-command-input');
  if (input) {
    input.value = '';
    setTimeout(() => input.focus(), 100);
  }
}

function executeCmsCommand(cmd) {
  closeModal('modal-cms-command-palette');
  if (cmd === 'edit_home') {
    switchView('cms');
    if (currentCmsPagesCache.length) openCmsPageInBuilder(currentCmsPagesCache[0].id);
  } else if (cmd === 'manage_header') {
    switchView('cms');
    switchCmsTab('headers');
  } else if (cmd === 'manage_footer') {
    switchView('cms');
    switchCmsTab('footers');
  } else if (cmd === 'theme_tokens') {
    switchView('cms');
    switchCmsTab('theme');
  } else if (cmd === 'popups') {
    switchView('cms');
    switchCmsTab('popups');
  }
}

function filterCmsCommands() {
  const val = (document.getElementById('cms-command-input')?.value || '').toLowerCase();
  const list = document.getElementById('cms-command-list');
  if (!list) return;

  const items = list.getElementsByTagName('div');
  for (let i = 0; i < items.length; i++) {
    const txt = items[i].textContent.toLowerCase();
    items[i].style.display = txt.includes(val) ? 'block' : 'none';
  }
}

// Global Ctrl+K Listener
document.addEventListener('keydown', (e) => {
  if ((e.ctrlKey || e.metaKey) && e.key === 'k') {
    e.preventDefault();
    openCmsCommandPalette();
  }
});

